// ═══════════════════════════════════════════════════════════════════
// نظام الخصوصية وبصمة الجهاز (Privacy & Device Fingerprint)
// ═══════════════════════════════════════════════════════════════════

/**
 * جمع بصمة جهاز مجهولة · لا تعرف الشخص شخصيا
 * تستدعى فقط بعد موافقة المستخدم
 */
function collectDeviceFingerprint(){
  try{
    const ua = navigator.userAgent || '';
    // كشف نوع الجهاز
    const isMobile = /Mobi|Android|iPhone|iPad|iPod/i.test(ua);
    const isTablet = /iPad|Tablet|Android(?!.*Mobi)/i.test(ua);
    const deviceType = isTablet ? 'تابلت' : (isMobile ? 'موبايل' : 'حاسب');
    // كشف نظام التشغيل
    let os = 'غير محدد';
    if(/Windows/i.test(ua)) os = 'Windows';
    else if(/Mac OS X|Macintosh/i.test(ua)) os = 'macOS';
    else if(/Android/i.test(ua)) os = 'Android';
    else if(/iPhone|iPad|iPod/i.test(ua)) os = 'iOS';
    else if(/Linux/i.test(ua)) os = 'Linux';
    // كشف المتصفح
    let browser = 'غير محدد';
    if(/Edg\//i.test(ua)) browser = 'Edge';
    else if(/Chrome\//i.test(ua) && !/Edg\//i.test(ua)) browser = 'Chrome';
    else if(/Safari\//i.test(ua) && !/Chrome\//i.test(ua)) browser = 'Safari';
    else if(/Firefox\//i.test(ua)) browser = 'Firefox';
    else if(/OPR\//i.test(ua)) browser = 'Opera';
    // المنطقة الزمنية واللغة
    const tz = Intl.DateTimeFormat().resolvedOptions().timeZone || 'غير محدد';
    const lang = navigator.language || navigator.userLanguage || 'غير محدد';
    // استنتاج البلد من المنطقة الزمنية
    const countryMap = {
      'Asia/Qatar':'قطر','Asia/Riyadh':'السعودية','Asia/Dubai':'الإمارات',
      'Asia/Kuwait':'الكويت','Asia/Bahrain':'البحرين','Asia/Muscat':'عمان',
      'Asia/Baghdad':'العراق','Asia/Amman':'الأردن','Africa/Cairo':'مصر',
      'Asia/Beirut':'لبنان','Africa/Tunis':'تونس','Africa/Algiers':'الجزائر',
      'Africa/Casablanca':'المغرب','Africa/Khartoum':'السودان','Asia/Aden':'اليمن',
      'Asia/Damascus':'سوريا','Asia/Gaza':'فلسطين','Asia/Jerusalem':'فلسطين',
      'Africa/Tripoli':'ليبيا','Africa/Mogadishu':'الصومال' };
    const country = countryMap[tz] || (tz.split('/')[0] || 'غير محدد');
    // دقة الشاشة
    const screenRes = (window.screen && window.screen.width) ? `${window.screen.width}×${window.screen.height}` : 'غير محدد';
    // معرف جلسة دائم (يحفظ في localStorage)
    let sessionId = localStorage.getItem('hh_device_id');
    if(!sessionId){
      sessionId = 'dev_' + Date.now().toString(36) + '_' + Math.random().toString(36).substr(2,9);
      localStorage.setItem('hh_device_id', sessionId);
    }
    return {
      deviceType, os, browser, timezone: tz, country, language: lang,
      screenRes, sessionId,
      userAgent: ua.substr(0,200), // مختصر
      collectedAt: Date.now()
    };
  }catch(e){
    return {deviceType:'غير محدد', os:'غير محدد', browser:'غير محدد', error:String(e).substr(0,80)};
  }
}

/**
 * الحصول على البصمة إذا كان المستخدم وافق، وإلا إرجاع null
 */
function getFingerprintIfConsented(){
  if(localStorage.getItem('hh_privacy_consent') !== 'yes') return null;
  // محفوظة مسبقا؟ استخدمها
  const cached = localStorage.getItem('hh_device_fp');
  if(cached){
    try{ return JSON.parse(cached); }catch(e){}
  }
  // اجمعها واحفظها
  const fp = collectDeviceFingerprint();
  try{ localStorage.setItem('hh_device_fp', JSON.stringify(fp)); }catch(e){}
  return fp;
}

/**
 * إظهار مودال الموافقة إن لم يستجب بعد
 */
function checkAndShowPrivacyConsent(){
  const consent = localStorage.getItem('hh_privacy_consent');
  if(consent === 'yes' || consent === 'no') return; // استجاب سابقا
  const modal = document.getElementById('privacy-consent-modal');
  if(modal) modal.style.display = 'flex';
}

/**
 * الموافقة على جمع البيانات
 */
function acceptPrivacyConsent(){
  localStorage.setItem('hh_privacy_consent', 'yes');
  localStorage.setItem('hh_privacy_consent_at', Date.now().toString());
  // جمع البصمة فورا
  getFingerprintIfConsented();
  const modal = document.getElementById('privacy-consent-modal');
  if(modal) modal.style.display = 'none';
  // دعوة الجولة اللطيفة بعد أن تخلو الشاشة
  setTimeout(function(){ try{ if(typeof hhShowTourInvite==='function') hhShowTourInvite(); }catch(e){} }, 1500);
}

/**
 * الرفض · لا نجمع شيء
 */
function declinePrivacyConsent(){
  localStorage.setItem('hh_privacy_consent', 'no');
  localStorage.setItem('hh_privacy_consent_at', Date.now().toString());
  const modal = document.getElementById('privacy-consent-modal');
  if(modal) modal.style.display = 'none';
  setTimeout(function(){ try{ if(typeof hhShowTourInvite==='function') hhShowTourInvite(); }catch(e){} }, 1500);
}

// إظهار المودال بعد تحميل الصفحة بثانيتين (بعد الـ loader)
window.addEventListener('load', function(){
  setTimeout(checkAndShowPrivacyConsent, 2200);
});

