// ═══════════════════════════════════════════════════════════════════
// نظام تعديل الأسئلة الأصلية محليا (localStorage)
// ═══════════════════════════════════════════════════════════════════

// ═══════════════════════════════════════════════════════════════════
// نظام تعديل الفئات الخارجية (الخرائط/الأعلام/العواصم/الأساطير/الشركاء)
// هذه الفئات تأتي من ملفات .js كبيرة لذا لا نخزّنها كاملة في localStorage.
// بدلاً من ذلك نخزّن فقط "طبقة تعديلات" (overrides) لكل فئة: الأسئلة المعدّلة/المضافة/المحذوفة.
// تُطبَّق هذه الطبقة فوق الملف الأصلي بعد تحميله.
// ═══════════════════════════════════════════════════════════════════
const _HH_EDITABLE_EXT_CATS = new Set(['خرائط الدول', 'أساطير الخرائط', 'أعلام الدول', 'عواصم الدول', 'بيرف آب · ثقافة قطرية', 'بيرف آب · معلومات دينية', 'بيرف آب · رياضة', 'بيرف آب · مسابقات وألغاز', 'بيرف آب · دول وعواصم', 'بيرف آب · معلومات عامة', 'طموح · ثقافة قطرية', 'طموح · معلومات دينية', 'طموح · رياضة', 'طموح · مسابقات وألغاز', 'طموح · دول وعواصم', 'طموح · معلومات عامة', 'المهني · قنوان', 'القرآني · قنوان', 'الترفيهي · قنوان', 'الاستكشافي · قنوان', 'الهوية · قنوان', 'الأمني · قنوان', 'الرياضي · قنوان', 'ثقافة عامة · قنوان', 'مسابقة أجيال في القرآن الكريم', 'مسابقة مركز أجيال التربوي - يوم الوفاء', 'مسابقة مركز أجيال التربوي', 'مسابقة مركز أجيال التربوي - اليوم الأمني', 'مسابقة مركز أجيال التربوي - ثقافة العمل التطوعي', 'مسابقة بيرف آب - الحفل الختامي', 'مسابقة الشباب']);

function _hhIsExternalCat(cat){ return _HH_EDITABLE_EXT_CATS.has(cat); }

// قراءة طبقة التعديلات من localStorage
function _hhLoadExtOverrides(){
  try{
    const raw = localStorage.getItem('hh_ext_overrides');
    if(raw){ const o = JSON.parse(raw); if(o && typeof o === 'object') return o; }
  }catch(e){ console.warn('ext overrides load error:', e); }
  return {};
}

// حفظ طبقة التعديلات في localStorage (حجمها صغير لأنها تخزّن فقط الأسئلة المعدّلة)
function _hhSaveExtOverrides(ov){
  try{
    localStorage.setItem('hh_ext_overrides', JSON.stringify(ov||{}));
    localStorage.setItem('hh_ext_overrides_at', Date.now().toString());
    return true;
  }catch(e){
    console.error('ext overrides save error:', e);
    if(e && e.name === 'QuotaExceededError'){
      try{ toast('مساحة المتصفح ممتلئة · حاول تصغير الصور','error'); }catch(_){}
    }
    return false;
  }
}

// تطبيق طبقة التعديلات على QDB (للفئات الخارجية فقط)
// ov[cat] = مصفوفة كاملة من الأسئلة تحلّ محل الفئة الخارجية بالكامل عند وجودها
function _hhApplyExtOverrides(qdb){
  try{
    const ov = _hhLoadExtOverrides();
    for(const cat in ov){
      if(_hhIsExternalCat(cat) && Array.isArray(ov[cat])){
        qdb[cat] = JSON.parse(JSON.stringify(ov[cat]));
      }
    }
  }catch(e){ console.warn('apply ext overrides error:', e); }
  return qdb;
}

// حفظ تعديلات فئة خارجية واحدة (محلياً + سحابياً للمستخدمين)
async function _hhSaveExtCatOverride(cat){
  if(!_hhIsExternalCat(cat)) return false;
  const ov = _hhLoadExtOverrides();
  // نخزّن النسخة الحالية الكاملة للفئة كما هي في QDB
  ov[cat] = JSON.parse(JSON.stringify(QDB[cat] || []));

  //  حارس الحجم: مستند Firestore محدود بـ1MB · الفئات المصوّرة (الخرائط/الأعلام) تتجاوزه
  try{
    const _payload = JSON.stringify(ov);
    const _kb = Math.round(_payload.length/1024);
    if(_payload.length > 900*1024){
      // نحلل أي فئة هي الأثقل لإرشاد المستخدم
      let heaviest='', heaviestKB=0;
      Object.keys(ov).forEach(function(c){
        const k=Math.round(JSON.stringify(ov[c]).length/1024);
        if(k>heaviestKB){ heaviestKB=k; heaviest=c; }
      });
      if(typeof toast === 'function'){
        toast(' حجم التعديلات '+_kb+'KB يتجاوز الحد الآمن (900KB). الأثقل: «'+heaviest+'» ('+heaviestKB+'KB) · صغّر صور هذه الفئة أو استعد افتراضيها','error');
      }
      return false;
    }
    if(_payload.length > 700*1024 && typeof toast === 'function'){
      toast('تنبيه: حجم التعديلات '+_kb+'KB · اقتربت من الحد (900KB)','warn');
    }
  }catch(_sg){}

  const okLocal = _hhSaveExtOverrides(ov);

  // الحفظ السحابي ليصل التعديل لكل المستخدمين
  if(OFFLINE_MODE || !db || (typeof isAdminUser === 'function' && !isAdminUser())){
    if(typeof toast === 'function') toast('تم الحفظ محلياً فقط (لن يصل للمستخدمين)','warn');
    return okLocal;
  }
  try{
    await db.collection('admin_qdb').doc('ext_overrides').set({
      data: JSON.stringify(ov),
      updatedAt: firebase.firestore.FieldValue.serverTimestamp(),
      updatedBy: (typeof currentUser!=='undefined' && currentUser && currentUser.email) ? currentUser.email : 'admin' });
    // إشارة نسخة لإجبار العملاء على إعادة التحميل
    await db.collection('admin').doc('qdb_version').set({
      version: Date.now(),
      updatedAt: firebase.firestore.FieldValue.serverTimestamp()
    },{merge:true});
    if(typeof toast === 'function') toast('✓ تم الحفظ · التعديل متاح لكل المستخدمين','success');
    return true;
  }catch(e){
    console.error('ext override cloud save error:', e);
    if(typeof toast === 'function') toast('فشل الحفظ السحابي: '+(e.message||'خطأ'),'error');
    return okLocal;
  }
}

// تحميل طبقة التعديلات من السحابة ودمجها (تُستدعى عند فتح الموقع)
async function _hhLoadExtOverridesFromCloud(){
  if(OFFLINE_MODE || !db) return false;
  try{
    const snap = await db.collection('admin_qdb').doc('ext_overrides').get();
    if(!snap.exists) return false;
    const cloud = JSON.parse(snap.data().data || '{}');
    if(!cloud || typeof cloud !== 'object') return false;
    // ندمج السحابي فوق المحلي (السحابي هو المصدر الموثوق للمستخدمين)
    const local = _hhLoadExtOverrides();
    const merged = Object.assign({}, local, cloud);
    _hhSaveExtOverrides(merged);
    // نطبّق على QDB الحالية
    _hhApplyExtOverrides(QDB);
    return true;
  }catch(e){ console.warn('ext overrides cloud load error:', e); return false; }
}

/**
 * تحميل QDB من localStorage إن وجدت تعديلات، وإلا استخدام الأصلية
 */
function _loadQDB(){
  try{
    // فحص رقم النسخة · إذا تغير، نتجاهل localStorage القديم
    const CURRENT_VERSION = 'v10-2026-06-29-ensure2';
    const savedVersion = localStorage.getItem('hh_qdb_version');
    if(savedVersion !== CURRENT_VERSION){
      // نسخة جديدة! نمسح القديم ونستخدم الأصلية
      localStorage.removeItem('hh_qdb_override');
      localStorage.removeItem('hh_qdb_modified_at');
      localStorage.setItem('hh_qdb_version', CURRENT_VERSION);
      _hhLog('تم تحديث قاعدة الأسئلة للنسخة:', CURRENT_VERSION);
      return _hhApplyExtOverrides(JSON.parse(JSON.stringify(QDB_ORIGINAL)));
    }
    
    const saved = localStorage.getItem('hh_qdb_override');
    if(saved){
      const parsed = JSON.parse(saved);
      if(parsed && typeof parsed === 'object' && Object.keys(parsed).length > 0){
        // دمج: نستخدم التعديلات المحفوظة لكن نضيف أي فئة جديدة من الأصلية
        const merged = JSON.parse(JSON.stringify(QDB_ORIGINAL));
        for(const cat in parsed){
          merged[cat] = parsed[cat];
        }
        return _hhApplyExtOverrides(merged);
      }
    }
  }catch(e){ console.warn('QDB load error:', e); }
  // نسخة عميقة من الأصلية + طبقة تعديلات الفئات الخارجية
  return _hhApplyExtOverrides(JSON.parse(JSON.stringify(QDB_ORIGINAL)));
}

/**
 * حفظ QDB الحالية إلى localStorage
 */
function _saveQDB(){
  try{
    // نستثني فئات الخرائط (تأتي من ملفات .js منفصلة) لتجنب تجاوز حد localStorage
    const _HH_EXTERNAL_CATS = new Set(['خرائط الدول', 'أساطير الخرائط', 'أعلام الدول', 'عواصم الدول', 'بيرف آب · ثقافة قطرية', 'بيرف آب · معلومات دينية', 'بيرف آب · رياضة', 'بيرف آب · مسابقات وألغاز', 'بيرف آب · دول وعواصم', 'بيرف آب · معلومات عامة', 'طموح · ثقافة قطرية', 'طموح · معلومات دينية', 'طموح · رياضة', 'طموح · مسابقات وألغاز', 'طموح · دول وعواصم', 'طموح · معلومات عامة', 'المهني · قنوان', 'القرآني · قنوان', 'الترفيهي · قنوان', 'الاستكشافي · قنوان', 'الهوية · قنوان', 'الأمني · قنوان', 'الرياضي · قنوان', 'ثقافة عامة · قنوان', 'مسابقة أجيال في القرآن الكريم', 'مسابقة مركز أجيال التربوي - يوم الوفاء', 'مسابقة مركز أجيال التربوي', 'مسابقة مركز أجيال التربوي - اليوم الأمني', 'مسابقة مركز أجيال التربوي - ثقافة العمل التطوعي', 'مسابقة بيرف آب - الحفل الختامي', 'مسابقة الشباب']);
    const slim = {};
    for(const cat in QDB){
      if(_HH_EXTERNAL_CATS.has(cat)) continue; // نتخطى الفئات الكبيرة
      if(window._hhPrivateCats && window._hhPrivateCats.has(cat)) continue; // zzzzzzj: الفئات الخاصة لا تُخزَّن محلياً
      slim[cat] = QDB[cat];
    }
    localStorage.setItem('hh_qdb_override', JSON.stringify(slim));
    localStorage.setItem('hh_qdb_modified_at', Date.now().toString());
    return true;
  }catch(e){
    console.error('QDB save error:', e);
    if(e && e.name === 'QuotaExceededError'){
      try{ toast('مساحة المتصفح ممتلئة. حاول حذف بعض البيانات','error'); }catch(_){}
    }
    return false;
  }
}

/**
 * إعادة تعيين QDB إلى الأصلية (حذف التعديلات المحلية)
 */
function _resetQDB(){
  localStorage.removeItem('hh_qdb_override');
  localStorage.removeItem('hh_qdb_modified_at');
  QDB = JSON.parse(JSON.stringify(QDB_ORIGINAL));
}

