let auth, db, currentUser=null, OFFLINE_MODE=false;

function hideLoader(){
  const loader=document.getElementById('app-loader');
  if(loader&&!loader.classList.contains('fade-out')){
    loader.classList.add('fade-out');
    setTimeout(()=>{if(loader.parentNode)loader.remove();},600);
  }
}

// Timeout · أقصى انتظار 4 ثوان ثم يذهب لتسجيل الدخول
// تحريك شريط التحميل
let _barPct = 0;
const _barInterval = setInterval(()=>{
  _barPct = Math.min(_barPct + Math.random()*15, 85);
  const bar = document.getElementById('loader-bar');
  if(bar) bar.style.width = _barPct + '%';
}, 300);

const _loaderTimeout = setTimeout(()=>{
  clearInterval(_barInterval);
  const bar = document.getElementById('loader-bar');
  if(bar) bar.style.width = '100%';
  hideLoader();
  if(!currentUser) showScreen('screen-landing');
}, 3500);

// حد صارم: لو لأي سبب لم يتم إخفاء الـ loader خلال 4 ثوان، نخفيه قسراً
const _hardLoaderCap = setTimeout(()=>{
  try{
    clearInterval(_barInterval);
    const loader = document.getElementById('app-loader');
    if(loader && !loader.classList.contains('fade-out')){
      const bar = document.getElementById('loader-bar');
      if(bar) bar.style.width = '100%';
      hideLoader();
      // إن لم يكن هناك مستخدم بعد، اعرض شاشة الهبوط
      if(!currentUser && typeof showScreen === 'function') showScreen('screen-landing');
    }
  }catch(e){}
}, 3800);

try {
  firebase.initializeApp(FB_CONFIG);
  
  // Firebase App Check · حماية من البوتات والوصول غير المصرح
  // مهم: استبدل 'YOUR_RECAPTCHA_SITE_KEY' بـ Site Key من reCAPTCHA v3
  // خطوات الإعداد: https://www.google.com/recaptcha/admin
  try {
    const APP_CHECK_SITE_KEY = 'YOUR_RECAPTCHA_SITE_KEY'; //  ضع Site Key هنا
    if (APP_CHECK_SITE_KEY && APP_CHECK_SITE_KEY !== 'YOUR_RECAPTCHA_SITE_KEY') {
      const appCheck = firebase.appCheck();
      appCheck.activate(
        new firebase.appCheck.ReCaptchaV3Provider(APP_CHECK_SITE_KEY),
        true // isTokenAutoRefreshEnabled
      );
      _hhLog('App Check مُفعّل');
    }
  } catch(e) {
    console.warn('App Check تعذر تفعيله:', e.message);
  }
  
  auth=firebase.auth();
  db=firebase.firestore();
  // ═══ zzzzzzs: أُزيل enablePersistence نهائياً ═══
  // كان المسبّب الجذري لخطأ FIRESTORE INTERNAL ASSERTION FAILED الذي يُعطّل لوحة التحكم
  // والإعدادات السحابية واللعب المباشر والمسابقات الخاصة عند تعدد الاستعلامات.
  // المنصة تعمل أونلاين مباشرةً؛ لا تخزين محلي لطبقة Firestore (لا حاجة له في بيئة مدرسية متصلة).
  auth.onAuthStateChanged(async user=>{
    try{ if(user) setTimeout(()=>{ try{ hhLoadNotifications(); }catch(_){} }, 2500); }catch(_e){}
    // zzzzzzb: الدور المحفوظ يُطبَّق فوراً ثم يُتحقق منه سحابياً خلال أجزاء من الثانية بدل 1.8 ثانية
    try{ if(user){ var _rc=JSON.parse(localStorage.getItem('hh_role_cache')||'null'); if(_rc && _rc.uid===user.uid && _rc.role && !hhIsAdmin()){ _hhMyRole=_rc.role; } } }catch(_e3){}
    try{ if(user) setTimeout(()=>{ try{ hhLoadMyRole(); }catch(_){} }, 250); }catch(_e2){}
    try{ if(user) setTimeout(()=>{ try{ _hhSeenCloudLoad(); }catch(_){} }, 2200); else { _HH_SEEN_CLOUD=null; _HH_SEEN_CLOUD_LOADED=false; } }catch(_e3){}
    clearTimeout(_loaderTimeout);
    clearInterval(_barInterval);
    const _bar=document.getElementById('loader-bar');
    if(_bar) _bar.style.width='100%';
    const _st=document.getElementById('loader-status');
    if(_st) _st.textContent = user ? 'مرحبا '+((user.displayName||user.email||'').split('@')[0]) + ' ' : 'جاري التحضير...';
    currentUser=user;
    if(user){
      // أنتقل للقائمة فوراً · تفاصيل المستخدم تُجلب في الخلفية
      showScreen('screen-menu');
      hideLoader();

      //  دخول هادئ: لا نوافذ تُفرض على القادم الجديد.
      // بدل الجولة الإجبارية نعرض دعوة صغيرة قابلة للتجاهل (مرة واحدة فقط)
      setTimeout(() => {
        try{ if(typeof hhShowTourInvite === 'function') hhShowTourInvite(); }catch(e){}
      }, 1800);

      // جلب اسم المستخدم وتحديثه (في الخلفية، غير معلِّق)
      (async ()=>{
        try{
          const doc = await db.collection('users').doc(user.uid).get();
          // معافاة ذاتية للمرآة العامة: بيانات العرض فقط
          try{
            if(doc.exists){
              var _d = doc.data();
              hhMirrorLeaderboard({
                name: _d.name || user.displayName || '',
                points: _d.points || 0,
                role: _d.role || null,
                gamesPlayed: _d.gamesPlayed || 0,
                createdAt: _d.createdAt || null
              });
            }
          }catch(e){}
          let displayName = 'أيها الملهم';
          if(doc.exists && doc.data().name){
            displayName = doc.data().name;
          } else if(user.displayName && /[\u0600-\u06FF]/.test(user.displayName)){
            displayName = user.displayName;
          } else if(user.displayName){
            displayName = 'أيها الملهم';
          }
          const ubName = document.getElementById('ub-name');
          if(ubName) ubName.textContent = displayName;

          //  تحديث آخر دخول تلقائيا (في الخلفية بدون انتظار)
          try{
            // zzzzzzu · أمان: لا نُنشئ/نحدّث مستخدماً إلا لمن له هوية حقيقية (ليس مجهولاً وليس فارغاً)
            var _anon = (user.isAnonymous === true);
            var _hasIdentity = doc.exists && (doc.data().name || doc.data().email || doc.data().phone || doc.data().role);
            if(!_anon && _hasIdentity){
              const updateData = { lastSeen: firebase.firestore.FieldValue.serverTimestamp() };
              db.collection('users').doc(user.uid).set(updateData, { merge: true });
            }
            // لاعبو السباق (مجهولون) والحسابات الفارغة لا تُكتب في قائمة المستخدمين
          }catch(e){ console.warn('lastSeen update skipped', e && e.code); }

          //  فحص طلب التقييم · إن طلب الأدمن منه التقييم
          try{
            if(doc.exists){
              const data = doc.data();
              const rr = data.reviewRequest;
              if(rr && rr.requested && !rr.shown){
                db.collection('users').doc(user.uid).set({
                  reviewRequest: { ...rr, shown: true, shownAt: firebase.firestore.FieldValue.serverTimestamp() }
                }, { merge: true });
                // zzzzzzag · أُلغيت نافذة «قيّم المنصة» التلقائية نهائياً بطلب المستخدم
                // setTimeout(()=>showReviewRequestModal(data.name || displayName), 60000);
              }
            }
          }catch(e){ console.warn('review request check failed', e); }
        }catch(e){ console.warn('user data fetch failed', e); }
      })();

      // العمليات الأخرى · كلها async ولا تعلّق
      showAdminBtn(user);
      checkAndShowEditorBtn();
      updatePartnersVisibility(user);
      refreshExclusiveAccess(user);
      loadHomePartnersStrip();
      loadDailyQuote();
      try{ hh_startSession(); }catch(e){}
      loadRoleQuickStart();
      const imgBtn=document.getElementById('nav-img-btn');
      if(imgBtn) imgBtn.style.display=isAdminUser(user)?'flex':'none';
      // جلب الدور وعرض المودال لو لم يختر بعد (في الخلفية)
      (async ()=>{
        try{
          await loadUserRole();
          if(!_currentUserRole){
            setTimeout(()=>showRoleModal(), 400);
          }
        }catch(e){}
      })();
    }else{
      showScreen('screen-landing');
      hideLoader();
    }
  });
}catch(e){
  clearTimeout(_loaderTimeout);
  OFFLINE_MODE=true;
  const sess=localStorage.getItem('hh_sess');
  if(sess){
    const u=JSON.parse(sess);
    currentUser=u;
    document.getElementById('ub-name').textContent=u.name;
    showScreen('screen-menu');
    showAdminBtn();
    updatePartnersVisibility();
    loadUserRole().then(()=>{
      if(!_currentUserRole) setTimeout(()=>showRoleModal(), 400);
    });
  }
  else showScreen('screen-landing');
  hideLoader();
}

async function doLogin(){
  const email=document.getElementById('login-email').value.trim();
  const pass=document.getElementById('login-pass').value;
  const err=document.getElementById('login-err');
  if(!email||!pass){err.textContent='أدخل البريد وكلمة المرور';return;}
  err.textContent='';
  if(OFFLINE_MODE){offlineLogin(email,pass,err);return;}
  try{await auth.signInWithEmailAndPassword(email,pass);}
  catch(e){err.textContent='البريد أو كلمة المرور غير صحيحة';}
}

async function doGoogleLogin(){
  const err=document.getElementById('login-err');
  if(err) err.textContent='';
  if(OFFLINE_MODE){ if(err) err.textContent='الدخول بجوجل يتطلب اتصالاً بالإنترنت'; return; }
  try{
    const provider=new firebase.auth.GoogleAuthProvider();
    const result=await auth.signInWithPopup(provider);
    const user=result.user;
    // إنشاء وثيقة المستخدم إن كان جديداً
    const ref=db.collection('users').doc(user.uid);
    const snap=await ref.get();
    if(!snap.exists){
      await ref.set({
        name: user.displayName || 'مستخدم',
        email: user.email || '',
        phone: '',
        points: 0,
        provider: 'google',
        createdAt: firebase.firestore.FieldValue.serverTimestamp()
      });
    }
  }catch(e){
    if(e.code==='auth/popup-closed-by-user' || e.code==='auth/cancelled-popup-request'){ return; }
    if(err) err.textContent = (e.code==='auth/operation-not-allowed')
      ? 'الدخول بجوجل غير مُفعّل بعد في الإعدادات'
      : 'تعذر الدخول بجوجل · حاول بالبريد';
  }
}

async function doRegister(){
  const name=document.getElementById('reg-name').value.trim();
  const phone=document.getElementById('reg-phone').value.trim();
  const email=document.getElementById('reg-email').value.trim();
  const pass=document.getElementById('reg-pass').value;
  const pass2=document.getElementById('reg-pass2').value;
  const err=document.getElementById('reg-err');
  if(!name||!phone||!email||!pass){err.textContent='يرجى إكمال جميع الحقول';return;}
  if(phone.length!==8){err.textContent='رقم الجوال يجب أن يكون 8 أرقام';return;}
  if(pass!==pass2){err.textContent='كلمتا المرور غير متطابقتين';return;}
  if(pass.length<6){err.textContent='كلمة المرور 6 أحرف على الأقل';return;}
  err.textContent='';
  if(OFFLINE_MODE){offlineRegister(name,email,pass,phone,err);return;}
  try{
    const cred=await auth.createUserWithEmailAndPassword(email,pass);
    await db.collection('users').doc(cred.user.uid).set({name,email,phone:'+974'+phone,points:0,createdAt:firebase.firestore.FieldValue.serverTimestamp()});
    // إرسال بريد التحقق
    try{ await cred.user.sendEmailVerification(); }catch(ev){}
    toast('تم إرسال رابط التحقق لبريدك · تفقد صندوقك','info');
  }catch(e){err.textContent=e.code==='auth/email-already-in-use'?'البريد مستخدم مسبقا':e.code==='auth/invalid-email'?'البريد غير صحيح':'حدث خطأ';}
}

async function doLogout(){
  if(OFFLINE_MODE){localStorage.removeItem('hh_sess');showScreen('screen-login');return;}
  await auth.signOut();
}

// ══════════════════════════════════════════════════
// منطق اختيار الدور (معلم/طالب/عام)
// ══════════════════════════════════════════════════
let _currentUserRole = null;     // 'teacher' | 'student' | 'other' | null
let _currentRoleChangeCount = 0; // عدد المرات اللي غير فيها

// جلب الدور من Firebase (أو localStorage في وضع offline)
async function loadUserRole(){
  if(!currentUser) return null;
  if(OFFLINE_MODE){
    try{
      const users = JSON.parse(localStorage.getItem('hh_users')||'{}');
      const u = users[currentUser.id];
      if(u){
        _currentUserRole = u.role || null;
        _currentRoleChangeCount = u.roleChangeCount || 0;
      }
    }catch(e){}
    if(_currentUserRole){
      try{ localStorage.setItem('hh_user_role', _currentUserRole); }catch(e){}
    }
    return _currentUserRole;
  }
  try{
    const doc = await db.collection('users').doc(currentUser.uid).get();
    if(doc.exists){
      const data = doc.data();
      _currentUserRole = data.role || null;
      _currentRoleChangeCount = data.roleChangeCount || 0;
    }
  }catch(e){}
  //  حفظ الدور محليا ليكون متاحا للشارة فورا عند التحميل
  if(_currentUserRole){
    try{ localStorage.setItem('hh_user_role', _currentUserRole); }catch(e){}
  }
  return _currentUserRole;
}

// عرض مودال اختيار الدور
function showRoleModal(opts){
  //  تحقق: المودال يظهر مرة واحدة فقط في تاريخ المستخدم
  // إلا إذا تم استدعاؤه يدويا من الإعدادات (force:true)
  const isForced = opts && opts.force === true;
  if(!isForced){
    try{
      const seen = localStorage.getItem('hh_role_modal_seen');
      if(seen === '1'){
        // المستخدم رأى المودال من قبل · لا نظهره ثانية
        return;
      }
    }catch(e){}
  }
  const m = document.getElementById('role-modal');
  if(m){
    m.style.display = 'flex';
    const err = document.getElementById('role-err');
    if(err) err.textContent = '';
    // سجل أن المودال ظهر (لن يظهر تلقائيا مرة أخرى)
    try{ localStorage.setItem('hh_role_modal_seen', '1'); }catch(e){}
  }
}

// إخفاء المودال
function hideRoleModal(){
  const m = document.getElementById('role-modal');
  if(m) m.style.display = 'none';
}

// اختيار الدور (تستدعى من أزرار المودال)
async function selectRole(role){
  if(!currentUser){ hideRoleModal(); return; }
  if(!['teacher','student','other'].includes(role)){ return; }

  const err = document.getElementById('role-err');
  if(err) err.textContent = '';

  // حفظ على Firebase أو localStorage
  try{
    if(OFFLINE_MODE){
      const users = JSON.parse(localStorage.getItem('hh_users')||'{}');
      const uid = currentUser.id;
      if(users[uid]){
        users[uid].role = role;
        users[uid].roleChangeCount = (users[uid].roleChangeCount || 0);
        localStorage.setItem('hh_users', JSON.stringify(users));
      }
    } else {
      await db.collection('users').doc(currentUser.uid).set({
        role: role,
        roleSetAt: firebase.firestore.FieldValue.serverTimestamp()
      }, {merge: true});
    }
    _currentUserRole = role;
    try{
      localStorage.setItem('hh_user_role', role);
      //  سجل تاريخ آخر تغيير + زد عداد التغييرات
      localStorage.setItem('hh_role_last_change', String(Date.now()));
      const cnt = parseInt(localStorage.getItem('hh_role_change_count') || '0', 10);
      localStorage.setItem('hh_role_change_count', String(cnt + 1));
      // سجل أن المودال ظهر (لمنع ظهوره التلقائي مرة أخرى)
      localStorage.setItem('hh_role_modal_seen', '1');
    }catch(e){}
    hideRoleModal();
    const label = role==='teacher'?'معلم':(role==='student'?'طالب':'عضو');
    toast('تم حفظ تصنيفك: '+label, 'success');
    // ── إعادة تحميل قسم "ماذا تحب أن تبدأ" بعد تحديد الدور ──
    setTimeout(()=>{
      try{
        if(typeof loadRoleQuickStart === 'function') loadRoleQuickStart();
        // إخفاء/إظهار خانة المعلم في الأدوات السريعة
        const teacherGroup = document.getElementById('teacher-tools-group');
        if(teacherGroup){
          teacherGroup.style.display = (role==='teacher' && isAdminUser(currentUser)) ? 'block' : 'none';
        }
        // لو اختار الدور أثناء محاولة بدء لعبة، نكمل اللعبة تلقائيا
        if(window._hhResumeStartAfterRole){
          window._hhResumeStartAfterRole = false;
          if(typeof startGame === 'function') startGame();
        }
      }catch(e){ console.error('refresh after role:', e); }
    }, 400);
  }catch(e){
    console.error('selectRole error:', e);
    if(err) err.textContent = 'تعذر الحفظ، حاول مرة أخرى';
  }
}

// تغيير الدور من الملف الشخصي (مرة واحدة فقط)
async function changeRole(newRole){
  if(!currentUser) return;
  if(!['teacher','student','other'].includes(newRole)){ return; }

  if(_currentRoleChangeCount >= 1){
    toast('يمكنك تغيير التصنيف مرة واحدة فقط · تواصل مع الدعم', 'error');
    return;
  }

  if(!confirm('تغيير التصنيف مسموح مرة واحدة فقط. هل أنت متأكد؟')) return;

  try{
    if(OFFLINE_MODE){
      const users = JSON.parse(localStorage.getItem('hh_users')||'{}');
      const uid = currentUser.id;
      if(users[uid]){
        users[uid].role = newRole;
        users[uid].roleChangeCount = (users[uid].roleChangeCount || 0) + 1;
        localStorage.setItem('hh_users', JSON.stringify(users));
      }
    } else {
      await db.collection('users').doc(currentUser.uid).set({
        role: newRole,
        roleChangeCount: firebase.firestore.FieldValue.increment(1),
        roleChangedAt: firebase.firestore.FieldValue.serverTimestamp()
      }, {merge: true});
    }
    _currentUserRole = newRole;
    _currentRoleChangeCount += 1;
    toast('تم تغيير التصنيف بنجاح', 'success');
    // حدث الواجهة لو فيها عنصر يعرض الدور
    if(typeof loadProfileData==='function') loadProfileData();
    // ── توجيه تلقائي للتبويب المناسب ──
    if(newRole==='teacher' || newRole==='student'){
      setTimeout(()=>{
        try{
          showScreen('screen-lb');
          currentLBTab = (newRole==='teacher') ? 'teachers' : 'students';
          switchLBTab(currentLBTab);
        }catch(e){ console.error('auto-nav after role change:', e); }
      }, 600);
    }
  }catch(e){
    console.error('changeRole error:', e);
    toast('تعذر الحفظ، حاول مرة أخرى', 'error');
  }
}

// التحقق من وجود الدور قبل بدء أي لعبة
async function ensureRoleBeforeAction(nextAction){
  await loadUserRole();
  if(!_currentUserRole){
    showRoleModal();
    return false;
  }
  if(typeof nextAction === 'function') nextAction();
  return true;
}

async function doResetPass(){
  const emailEl=document.getElementById('reset-email');
  const errEl=document.getElementById('reset-err');
  const succEl=document.getElementById('reset-success');
  if(!emailEl)return;
  const email=emailEl.value.trim();
  if(!email){errEl.textContent='أدخل بريدك الإلكتروني';return;}
  errEl.textContent='';
  if(OFFLINE_MODE){errEl.textContent='غير متاح في الوضع المحلي - تواصل مع المسؤول';return;}
  // تعطيل الزر مؤقتا لمنع الضغط المتكرر
  const btn=document.querySelector('#screen-reset .btn');
  if(btn){btn.disabled=true;btn.textContent='جاري الإرسال...';}
  try{
    await auth.sendPasswordResetEmail(email);
    succEl.style.display='block';
    errEl.textContent='';
    emailEl.value='';
    // تغيير نص الزر
    if(btn){btn.textContent='تم الإرسال';}
  }catch(e){
    if(btn){btn.disabled=false;btn.textContent='إرسال رابط الاسترداد';}
    if(e.code==='auth/user-not-found'||e.code==='auth/invalid-credential')
      errEl.textContent='البريد غير مسجل في النظام';
    else if(e.code==='auth/invalid-email')
      errEl.textContent='البريد غير صحيح';
    else if(e.code==='auth/too-many-requests')
      errEl.textContent='محاولات كثيرة، انتظر قليلا';
    else
      errEl.textContent='حدث خطأ: '+e.message;
  }
}

function offlineLogin(email,pass,err){
  let users={};
  try{ users=JSON.parse(localStorage.getItem('hh_users')||'{}'); }catch(e){ users={}; }
  const user=Object.values(users).find(u=>u.email===email&&u.pass===pass);
  if(!user){err.textContent='بيانات خاطئة';return;}
  try{ localStorage.setItem('hh_sess',JSON.stringify(user)); }catch(e){}
  currentUser=user;document.getElementById('ub-name').textContent=user.name;showScreen('screen-menu');
  // جلب الدور وعرض المودال لو لم يختر بعد · يشمل المستخدمين القدامى في offline
  loadUserRole().then(()=>{
    if(!_currentUserRole) setTimeout(()=>showRoleModal(), 400);
  });
}

function offlineRegister(name,email,pass,phone,err){
  let users={};
  try{ users=JSON.parse(localStorage.getItem('hh_users')||'{}'); }catch(e){ users={}; }
  if(Object.values(users).find(u=>u.email===email)){err.textContent='البريد مستخدم مسبقا';return;}
  const id=Date.now().toString();
  const user={id,name,email,pass,phone:'+974'+(phone||''),pts:0};
  users[id]=user;
  try{
    localStorage.setItem('hh_users',JSON.stringify(users));
    localStorage.setItem('hh_sess',JSON.stringify(user));
  }catch(e){ err.textContent='تعذر حفظ البيانات محليا'; return; }
  currentUser=user;document.getElementById('ub-name').textContent=name;showScreen('screen-menu');
  // مستخدم جديد · اعرض مودال اختيار الدور فورا
  setTimeout(()=>showRoleModal(), 500);
}

let _addPtsInFlight = false;
async function addPts(pts){
  if(!currentUser||pts<=0)return;
  if(_addPtsInFlight){ setTimeout(()=>addPts(pts), 500); return; }
  if(OFFLINE_MODE){
    try{
      const users=JSON.parse(localStorage.getItem('hh_users')||'{}');
      const uid=currentUser.id;
      if(users[uid]){
        users[uid].pts=(users[uid].pts||0)+pts;
        localStorage.setItem('hh_users',JSON.stringify(users));
      }
    }catch(e){}
    return;
  }
  _addPtsInFlight = true;
  try{
    // احفظ المرتبة قبل التحديث
    const before=await db.collection('leaderboard').orderBy('points','desc').limit(6).get();
    const rankBefore=before.docs.findIndex(d=>d.id===currentUser.uid);
    await db.collection('users').doc(currentUser.uid).update({points:firebase.firestore.FieldValue.increment(pts)});
    hhMirrorLeaderboard({ points: firebase.firestore.FieldValue.increment(pts) });
    // تحقق من المرتبة بعد التحديث
    setTimeout(async()=>{
      try{
        const after=await db.collection('leaderboard').orderBy('points','desc').limit(6).get();
        const rankAfter=after.docs.findIndex(d=>d.id===currentUser.uid);
        if(rankAfter>=0 && rankAfter<5 && (rankBefore<0||rankBefore>=5)){
          toast('دخلت قائمة أفضل 5 لاعبين!','success');
          if(navigator.vibrate) navigator.vibrate([80,40,80,40,120]);
        } else if(rankAfter>=0 && rankBefore>rankAfter && rankAfter<5){
          toast('تقدمت للمركز #'+(rankAfter+1)+' في الصدارة!','success');
        }
      }catch(e){}
    },1500);
  }catch(e){}
  finally{ _addPtsInFlight = false; }
}



