const _LEGENDARY_CATS_SET = new Set(['الأساطير','أساطير السيرة','أساطير الحضارة','أساطير القادة','أساطير النساء','أساطير الأمثال','أساطير الطب','أساطير الخرائط']);

// دالة اختيار الـ palette الصحيحة (كل فئة أسطورية لها لونها الخاص الآن)
function getCatPalette(cat, fallbackIdx){
  if(CAT_PALETTE_LEGENDARY_BY_CAT[cat]) return CAT_PALETTE_LEGENDARY_BY_CAT[cat];
  if(_LEGENDARY_CATS_SET.has(cat)) return CAT_PALETTE_LEGENDARY;
  return CAT_PALETTES[fallbackIdx % CAT_PALETTES.length];
}

