function hhOpenGuide(forceRole){
  var role = forceRole || null;
  if(!role){
    try{ role = localStorage.getItem(HH_GUIDE_KEY); }catch(e){}
  }
  if(!role){ hhGuideChooser(); return; }
  hhGuideRender(role);
}

