    +'<div style="color:rgba(255,255,255,.7);font-size:.88rem;font-weight:700;margin-bottom:24px;">لنعرض لك ما يناسبك · من أنت؟</div>'
    +'<div style="display:flex;gap:13px;flex-wrap:wrap;justify-content:center;">'
