function mcRenderQuickGrid(){
  var box=document.getElementById('mc-quick-grid'); if(!box) return;
  box.innerHTML = HH_QUICK_MAP.map(function(G){
    return '<div class="mc-quick-group" data-group="'+esc(G.g)+'" style="margin-bottom:16px;">'
      +'<div style="font-weight:900;font-size:.83rem;color:'+G.c+';margin-bottom:8px;display:flex;align-items:center;gap:7px;">'
      +'<span style="width:8px;height:8px;background:'+G.c+';border-radius:50%;display:inline-block;"></span>'+esc(G.g)+'</div>'
      +'<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(168px,1fr));gap:9px;">'
      + G.items.map(function(it){
          return '<button class="mc-quick-card" data-tab="'+it[0]+'" data-kw="'+esc(it[1]+' '+it[2])+'" '
            +'onclick="mcQuickGo(\''+it[0]+'\')" '
            +'style="background:#fff;border:1.5px solid #E3D9C6;border-radius:13px;padding:12px;cursor:pointer;text-align:right;'
            +'font-family:Cairo,Tajawal,sans-serif;transition:all .15s;display:flex;gap:9px;align-items:flex-start;" '
            +'onmouseover="this.style.borderColor=\''+G.c+'\';this.style.transform=\'translateY(-2px)\';this.style.boxShadow=\'0 6px 16px rgba(0,0,0,.09)\'" '
            +'onmouseout="this.style.borderColor=\'#E3D9C6\';this.style.transform=\'\';this.style.boxShadow=\'\'">'
            +'<svg viewBox="0 0 24 24" fill="'+G.c+'" style="width:19px;height:19px;flex-shrink:0;margin-top:2px;"><path d="'+it[3]+'"/></svg>'
            +'<span style="flex:1;min-width:0;"><span style="display:block;font-weight:900;font-size:.79rem;color:#3D0918;">'+esc(it[1])+'</span>'
            +'<span style="display:block;font-size:.68rem;color:#999;font-weight:700;margin-top:2px;line-height:1.5;">'+esc(it[2])+'</span></span>'
            +'</button>';
        }).join('')
      +'</div></div>';
  }).join('')
  + '<div id="mc-quick-empty" style="display:none;text-align:center;color:#999;font-weight:700;font-size:.83rem;padding:22px;">لا نتائج مطابقة</div>';
}

function mcQuickGo(tab){
  try{
    if(tab==='textedit'){ if(typeof hhOpenTextEditor==='function'){ hhOpenTextEditor(); } else if(typeof toast==='function'){ toast('المحرّر غير متاح','error'); } return; }
    adminTab(tab);
    // إبراز التبويب في الشريط الجانبي
    var btn=document.querySelector('.mc-item[data-tab="'+tab+'"]');
    if(btn && btn.scrollIntoView) btn.scrollIntoView({behavior:'smooth', block:'nearest'});
    var panel=document.getElementById('admin-'+tab+'-panel');
    if(panel && panel.scrollIntoView) setTimeout(function(){ panel.scrollIntoView({behavior:'smooth', block:'start'}); }, 60);
  }catch(e){ if(typeof toast==='function') toast('تعذر الانتقال','error'); }
}

function mcFilterQuick(q){
  q=String(q||'').trim().toLowerCase();
  var groups=document.querySelectorAll('.mc-quick-group');
  var shown=0;
  groups.forEach(function(G){
    var cards=G.querySelectorAll('.mc-quick-card');
    var vis=0;
    cards.forEach(function(c){
      var kw=(c.getAttribute('data-kw')||'').toLowerCase();
      var match = !q || kw.indexOf(q)>=0;
      c.style.display = match ? 'flex' : 'none';
      if(match) vis++;
    });
    G.style.display = vis ? '' : 'none';
    shown += vis;
  });
  var empty=document.getElementById('mc-quick-empty');
  if(empty) empty.style.display = shown ? 'none' : 'block';
}

async function hhLoadTeacherDirectory(){
  var box=document.getElementById('adm-dir-list'); if(!box) return;
  box.innerHTML='<div style="text-align:center;color:#8A6D2E;padding:24px;font-family:Cairo;font-weight:800;">جاري تجميع البيانات...</div>';
  try{
    if(typeof firebase==='undefined' || !firebase.firestore){
      box.innerHTML='<div style="text-align:center;color:#c0392b;padding:20px;font-family:Cairo;font-weight:800;">لا اتصال بالسحابة</div>'; return;
    }
    var db=firebase.firestore();
    // المعلمون المعتمدون
    var tsnap=await db.collection('teacher_requests').where('status','==','approved').limit(100).get();
    var teachers=[]; tsnap.forEach(function(d){ teachers.push(Object.assign({uid:d.id}, d.data())); });
    // الصفوف
    var csnap=await db.collection('classes').limit(200).get();
    var classes=[]; csnap.forEach(function(d){ classes.push(Object.assign({id:d.id}, d.data())); });
    // النشاط
    var asnap=await db.collection('platform_activity').limit(400).get();
    var acts=[]; asnap.forEach(function(d){ acts.push(d.data()); });
    // الشهادات
    var certs=[];
    try{ var ss=await db.collection('certificates').limit(300).get(); ss.forEach(function(d){ certs.push(d.data()); }); }catch(e){}

    var now=Date.now();
    _hhTeacherDir = teachers.map(function(T){
      var myClasses=classes.filter(function(c){ return c.teacherUid===T.uid; });
      var students=myClasses.reduce(function(a,c){ return a+((c.studentUids||[]).length); },0);
      var myActs=acts.filter(function(a){ return a.user===T.email; });
      var myCerts=certs.filter(function(c){ return c.issuedBy===T.email; });
      // آخر نشاط
      var last=null;
      myActs.forEach(function(a){
        var t=a.createdAt&&a.createdAt.seconds? a.createdAt.seconds*1000 : null;
        if(t && (!last || t>last)) last=t;
      });
      var daysIdle = last ? Math.floor((now-last)/86400000) : null;
      // تصنيف النشاط
      var games=myActs.filter(function(a){return a.type==='game_start';}).length;
      var lessons=myActs.filter(function(a){return a.type==='lesson_add';}).length;
      var gens=myActs.filter(function(a){return a.type==='generate';}).length;
      // مؤشر النشاط (0-100)
      var score = Math.min(100, Math.round(
        Math.min(30, myClasses.length*10) +
        Math.min(25, students*1.2) +
        Math.min(20, games*2) +
        Math.min(15, (lessons+gens)*1.5) +
        (daysIdle===null?0 : daysIdle<=7?10 : daysIdle<=30?5 : 0)
      ));
      var state = daysIdle===null ? 'لم يبدأ'
                : daysIdle<=7 ? 'نشط'
                : daysIdle<=30 ? 'متقطّع' : 'خامل';
      return { uid:T.uid, name:T.name||'', email:T.email||'', school:T.school||'', subject:T.subject||'',
        classes:myClasses.length, students:students, games:games, lessons:lessons, gens:gens,
        certs:myCerts.length, acts:myActs.length, daysIdle:daysIdle, score:score, state:state,
        classNames:myClasses.map(function(c){return c.name||'';}).filter(Boolean) };
    }).sort(function(a,b){ return b.score-a.score; });

    hhRenderTeacherDir();
  }catch(e){
    box.innerHTML='<div style="text-align:center;color:#c0392b;padding:20px;font-family:Cairo;font-weight:800;line-height:1.9;">'
      +'تعذر التحميل · تأكد من لصق قواعد Firestore</div>';
  }
}

function hhRenderTeacherDir(){
  var box=document.getElementById('adm-dir-list'); if(!box) return;
  var D=_hhTeacherDir;
  if(!D.length){
    box.innerHTML='<div style="text-align:center;color:#999;padding:22px;font-family:Cairo;font-weight:700;">لا معلمين معتمدين بعد</div>'; return;
  }
  // إحصاءات عامة
  var active=D.filter(function(t){return t.state==='نشط';}).length;
  var idle=D.filter(function(t){return t.state==='خامل'||t.state==='لم يبدأ';}).length;
  var totStudents=D.reduce(function(a,t){return a+t.students;},0);
  var totClasses=D.reduce(function(a,t){return a+t.classes;},0);
  var avgScore=Math.round(D.reduce(function(a,t){return a+t.score;},0)/D.length);

  var cards='<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(110px,1fr));gap:10px;margin-bottom:14px;">'
    +'<div style="background:#E9EEF8;border-radius:12px;padding:11px;text-align:center;">'
    +'<div style="font-size:1.5rem;font-weight:900;color:#1F4E79;">'+D.length+'</div><div style="font-size:.68rem;color:#666;font-weight:800;">معلم معتمد</div></div>'
    +'<div style="background:#EBF2EE;border-radius:12px;padding:11px;text-align:center;">'
    +'<div style="font-size:1.5rem;font-weight:900;color:#3D6B53;">'+active+'</div><div style="font-size:.68rem;color:#666;font-weight:800;">نشط هذا الأسبوع</div></div>'
    +'<div style="background:#F7ECEF;border-radius:12px;padding:11px;text-align:center;">'
    +'<div style="font-size:1.5rem;font-weight:900;color:#c0392b;">'+idle+'</div><div style="font-size:.68rem;color:#666;font-weight:800;">خامل / لم يبدأ</div></div>'
    +'<div style="background:#FDF3DD;border-radius:12px;padding:11px;text-align:center;">'
    +'<div style="font-size:1.5rem;font-weight:900;color:#B8924A;">'+totStudents+'</div><div style="font-size:.68rem;color:#666;font-weight:800;">طالب</div></div>'
    +'<div style="background:#F5E9EE;border-radius:12px;padding:11px;text-align:center;">'
    +'<div style="font-size:1.5rem;font-weight:900;color:#8A1538;">'+totClasses+'</div><div style="font-size:.68rem;color:#666;font-weight:800;">صف</div></div>'
    +'<div style="background:#fff;border:1.5px solid #E3D9C6;border-radius:12px;padding:11px;text-align:center;">'
    +'<div style="font-size:1.5rem;font-weight:900;color:#8A6D2E;">'+avgScore+'</div><div style="font-size:.68rem;color:#666;font-weight:800;">متوسط النشاط</div></div>'
    +'</div>';

  // تنبيهات ذكية
  var alerts=[];
  var noClass=D.filter(function(t){return t.classes===0;});
  if(noClass.length) alerts.push({c:'#b5801f', t:noClass.length+' معلم لم ينشئ صفاً بعد', d:'قد يحتاجون تدريباً على إنشاء الصفوف · '+noClass.slice(0,3).map(function(t){return t.name;}).join(' · ')});
  var stale=D.filter(function(t){return t.daysIdle!==null && t.daysIdle>30;});
  if(stale.length) alerts.push({c:'#c0392b', t:stale.length+' معلم خامل أكثر من شهر', d:'تواصل معهم لمعرفة العائق · '+stale.slice(0,3).map(function(t){return t.name;}).join(' · ')});
  var stars=D.filter(function(t){return t.score>=70;});
  if(stars.length) alerts.push({c:'#3D6B53', t:stars.length+' معلم متميز في الاستخدام', d:'مرشّحون لتقديم تجاربهم أو قيادة تدريب الزملاء · '+stars.slice(0,3).map(function(t){return t.name;}).join(' · ')});
  var alertHTML = alerts.length ? '<div style="font-weight:900;font-size:.86rem;color:#5E0E26;margin-bottom:7px;">قراءة تحليلية</div>'
    + alerts.map(function(a){
        return '<div style="background:#fff;border:1.5px solid #E3D9C6;border-right:4px solid '+a.c+';border-radius:11px;padding:10px 13px;margin-bottom:7px;">'
          +'<div style="font-weight:900;font-size:.81rem;color:'+a.c+';">'+esc(a.t)+'</div>'
          +'<div style="font-size:.76rem;color:#666;line-height:1.8;margin-top:3px;">'+esc(a.d)+'</div></div>';
      }).join('') + '<div style="height:8px;"></div>' : '';

  // الجدول
  var rows=D.map(function(t,i){
    var col = t.state==='نشط'?'#3D6B53' : t.state==='متقطّع'?'#b5801f' : t.state==='خامل'?'#c0392b':'#999';
    var bar = '<div style="background:#eee;border-radius:5px;height:7px;width:60px;display:inline-block;vertical-align:middle;">'
      +'<div style="background:'+col+';border-radius:5px;height:7px;width:'+t.score+'%;"></div></div>';
    return '<tr style="background:'+(i%2?'#F7FBFF':'#fff')+';">'
      +'<td style="padding:7px 9px;"><div style="font-weight:900;font-size:.79rem;color:#5E0E26;">'+esc(t.name)+'</div>'
      +'<div style="font-size:.68rem;color:#aaa;">'+esc(t.email)+'</div></td>'
      +'<td style="padding:6px;font-size:.72rem;color:#888;">'+esc(t.school)+'<br><span style="color:#bbb;">'+esc(t.subject)+'</span></td>'
      +'<td style="padding:6px;text-align:center;font-weight:900;font-size:.78rem;color:#1F4E79;">'+t.classes+'</td>'
      +'<td style="padding:6px;text-align:center;font-weight:900;font-size:.78rem;color:#3D6B53;">'+t.students+'</td>'
      +'<td style="padding:6px;text-align:center;font-size:.74rem;">'+t.games+'</td>'
      +'<td style="padding:6px;text-align:center;font-size:.74rem;">'+t.certs+'</td>'
      +'<td style="padding:6px;text-align:center;">'+bar+' <span style="font-size:.72rem;font-weight:900;color:'+col+';">'+t.score+'</span></td>'
      +'<td style="padding:6px;text-align:center;"><span style="background:'+col+';color:#fff;border-radius:7px;padding:2px 9px;font-size:.64rem;font-weight:900;">'+esc(t.state)+'</span></td>'
      +'<td style="padding:4px;text-align:center;"><button onclick="hhTeacherProfile('+i+')" style="background:#E9EEF8;color:#1F4E79;border:1px solid #1F4E79;border-radius:7px;padding:3px 9px;font-family:Cairo;font-weight:900;font-size:.65rem;cursor:pointer;">تحليل</button></td></tr>';
  }).join('');

  box.innerHTML = cards + alertHTML
    +'<div style="overflow-x:auto;"><table style="width:100%;border-collapse:collapse;font-family:Cairo,Tajawal,sans-serif;">'
    +'<thead><tr style="background:#1F4E79;color:#fff;font-size:.7rem;font-weight:900;">'
    +'<th style="padding:7px 9px;text-align:right;">المعلم</th><th style="padding:7px;text-align:right;">المدرسة</th>'
    +'<th style="padding:7px;">صفوف</th><th style="padding:7px;">طلاب</th><th style="padding:7px;">ألعاب</th>'
    +'<th style="padding:7px;">شهادات</th><th style="padding:7px;">مؤشر النشاط</th><th style="padding:7px;">الحالة</th><th style="padding:7px;"></th></tr></thead>'
    +'<tbody>'+rows+'</tbody></table></div>'
    +'<div style="display:flex;gap:8px;margin-top:13px;flex-wrap:wrap;">'
    +'<button onclick="hhDirExportCSV()" style="background:linear-gradient(135deg,#8A6D2E,#B8924A);color:#fff;border:none;border-radius:11px;padding:10px 20px;font-family:Cairo;font-weight:900;font-size:.82rem;cursor:pointer;">تصدير الدليل CSV</button>'
    +'<button onclick="hhDirNotifyIdle()" style="background:#E9EEF8;color:#1F4E79;border:1.5px solid #1F4E79;border-radius:11px;padding:10px 18px;font-family:Cairo;font-weight:900;font-size:.82rem;cursor:pointer;">تنبيه الخاملين</button>'
    +'</div>';
}

function hhTeacherProfile(i){
  var t=_hhTeacherDir[i]; if(!t) return;
  var col = t.state==='نشط'?'#3D6B53' : t.state==='متقطّع'?'#b5801f' : t.state==='خامل'?'#c0392b':'#999';
  // توصيات
  var recs=[];
  if(t.classes===0) recs.push('لم ينشئ صفاً · أرسل له دليل إنشاء الصف وكود الانضمام.');
  else if(t.students===0) recs.push('أنشأ صفوفاً بلا طلاب · ذكّره بمشاركة كود الصف أو استيراد القائمة.');
  if(t.games===0) recs.push('لم يشغّل لعبة بعد · التجربة الأولى هي مفتاح الاستمرار.');
  if(t.daysIdle!==null && t.daysIdle>30) recs.push('خامل منذ '+t.daysIdle+' يوماً · تواصل شخصي قد يعيده.');
  if(t.score>=70) recs.push('من أنشط المعلمين · مرشّح لعرض تجربته أو تدريب زملائه.');
  if(t.lessons>0 && t.gens>0) recs.push('يستخدم مركز المنهج فعلياً · نموذج جيد للاقتداء.');
  if(!recs.length) recs.push('الاستخدام متوازن · واصل المتابعة الدورية.');

  var html='<div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:13px;">'
    +'<div style="background:'+col+';color:#fff;border-radius:13px;padding:14px;text-align:center;flex:1;min-width:110px;">'
    +'<div style="font-size:1.8rem;font-weight:900;">'+t.score+'</div><div style="font-size:.68rem;opacity:.9;">مؤشر النشاط</div>'
    +'<div style="font-size:.72rem;font-weight:900;margin-top:3px;">'+esc(t.state)+'</div></div>'
    +'<div style="background:#E9EEF8;border-radius:13px;padding:14px;text-align:center;flex:1;min-width:90px;">'
    +'<div style="font-size:1.6rem;font-weight:900;color:#1F4E79;">'+t.students+'</div><div style="font-size:.68rem;color:#666;font-weight:800;">طالباً</div></div>'
    +'<div style="background:#FDF3DD;border-radius:13px;padding:14px;text-align:center;flex:1;min-width:90px;">'
    +'<div style="font-size:1.6rem;font-weight:900;color:#B8924A;">'+t.acts+'</div><div style="font-size:.68rem;color:#666;font-weight:800;">نشاطاً</div></div>'
    +'</div>'
    +'<div style="background:#fff;border:1.5px solid #E3D9C6;border-radius:12px;padding:12px;margin-bottom:12px;">'
    +'<div style="font-size:.74rem;color:#888;margin-bottom:6px;">'+esc(t.school)+' · '+esc(t.subject)+' · '+esc(t.email)+'</div>'
    + [['الصفوف',t.classes],['الألعاب المشغّلة',t.games],['الدروس المضافة',t.lessons],
       ['عمليات التوليد',t.gens],['الشهادات الصادرة',t.certs],
       ['آخر نشاط', t.daysIdle===null?'لم يبدأ':(t.daysIdle===0?'اليوم':'منذ '+t.daysIdle+' يوماً')]]
      .map(function(r){
        return '<div style="display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px dashed #f0e8d8;">'
          +'<span style="font-size:.77rem;color:#555;font-weight:700;">'+esc(r[0])+'</span>'
          +'<span style="font-size:.79rem;font-weight:900;color:#5E0E26;">'+esc(String(r[1]))+'</span></div>';
      }).join('')
    + (t.classNames.length ? '<div style="margin-top:8px;font-size:.73rem;color:#888;">صفوفه: '+t.classNames.map(esc).join(' · ')+'</div>' : '')
    +'</div>'
    +'<div style="font-weight:900;font-size:.84rem;color:#5E0E26;margin-bottom:7px;">توصيات المتابعة</div>'
    + recs.map(function(r){
        return '<div style="background:#FDF8EC;border-right:3px solid #B8924A;border-radius:10px;padding:9px 12px;margin-bottom:6px;font-size:.78rem;color:#555;line-height:1.85;">'+esc(r)+'</div>';
      }).join('')
    +'<button onclick="hhDirNotifyOne(\''+t.uid+'\',\''+esc(t.name)+'\')" style="width:100%;background:linear-gradient(135deg,#1F4E79,#173A5A);color:#fff;border:none;border-radius:11px;padding:10px;font-family:Cairo;font-weight:900;font-size:.82rem;cursor:pointer;margin-top:9px;">إرسال رسالة تشجيع</button>';
  if(typeof hhSchModal==='function') hhSchModal('تحليل: '+t.name, html, col);
}

async function hhDirNotifyOne(uid, name){
  try{
    await firebase.firestore().collection('user_notifications').add({
      toUid:uid, title:'رسالة من إدارة المُلهِم',
      body:'مرحباً '+name+'، نشكرك على انضمامك لمنصة المُلهِم. إن احتجت أي مساعدة في إنشاء صفوفك أو استخدام الأدوات فنحن معك.',
      from:'إدارة المُلهِم', read:false, createdAt:new Date().toISOString()
    });
    if(typeof toast==='function') toast('أُرسلت الرسالة','success');
  }catch(e){ if(typeof toast==='function') toast('تعذر الإرسال','error'); }
}
async function hhDirNotifyIdle(){
  var idle=_hhTeacherDir.filter(function(t){ return t.state==='خامل'||t.state==='لم يبدأ'; });
  if(!idle.length){ if(typeof toast==='function') toast('لا معلمين خاملين','info'); return; }
  if(!confirm('إرسال رسالة تشجيع لـ'+idle.length+' معلم؟')) return;
  var sent=0;
  for(var i=0;i<idle.length;i++){
    try{
      await firebase.firestore().collection('user_notifications').add({
        toUid:idle[i].uid, title:'نفتقد نشاطك في المُلهِم',
        body:'مرحباً '+idle[i].name+'، لاحظنا أنك لم تستخدم المنصة مؤخراً. إن واجهتك أي صعوبة فنحن جاهزون لمساعدتك.',
        from:'إدارة المُلهِم', read:false, createdAt:new Date().toISOString()
      });
      sent++;
    }catch(e){}
  }
  if(typeof toast==='function') toast('أُرسلت '+sent+' رسالة','success');
}
function hhDirExportCSV(){
  var rows=[['المعلم','البريد','المدرسة','المادة','الصفوف','الطلاب','الألعاب','الدروس','التوليد','الشهادات','مؤشر النشاط','الحالة','آخر نشاط (يوم)']];
  _hhTeacherDir.forEach(function(t){
    rows.push([t.name,t.email,t.school,t.subject,t.classes,t.students,t.games,t.lessons,t.gens,t.certs,t.score,t.state,t.daysIdle==null?'·':t.daysIdle]);
  });
  var csv=rows.map(function(r){return r.map(function(c){return '"'+String(c).replace(/"/g,'""')+'"';}).join(',');}).join('\n');
  var bl=new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'});
  var a=document.createElement('a'); a.href=URL.createObjectURL(bl);
  a.download='teachers_directory_'+new Date().toISOString().slice(0,10)+'.csv'; a.click();
}

async function hhAdmLoadTeachers(filter){
  var box=document.getElementById('adm-teachers-list'); if(!box) return;
  box.innerHTML='<div style="text-align:center;color:#8A6D2E;padding:22px;font-family:Cairo;font-weight:800;">جاري التحميل...</div>';
  try{
    if(typeof firebase==='undefined' || !firebase.firestore){
      box.innerHTML='<div style="text-align:center;color:#c0392b;padding:20px;font-family:Cairo;font-weight:800;">لا اتصال بالسحابة</div>'; return;
    }
    var snap=await firebase.firestore().collection('teacher_requests').limit(100).get();
    var items=[]; snap.forEach(function(d){ items.push(Object.assign({id:d.id}, d.data())); });
    if(filter && filter!=='all') items=items.filter(function(t){ return (t.status||'pending')===filter; });
    if(!items.length){
      box.innerHTML='<div style="text-align:center;color:#999;padding:22px;font-family:Cairo;font-weight:700;">لا نتائج</div>'; return;
    }
    box.innerHTML=items.map(function(t){
      var st=t.status||'pending';
      var col=st==='approved'?'#3D6B53':st==='rejected'?'#c0392b':'#b5801f';
      var lbl=st==='approved'?'معتمد':st==='rejected'?'مرفوض':'قيد المراجعة';
      return '<div style="background:#fff;border:1.5px solid #E3D9C6;border-right:4px solid '+col+';border-radius:12px;padding:13px 15px;margin-bottom:9px;font-family:Cairo,Tajawal,sans-serif;">'
        +'<div style="display:flex;justify-content:space-between;gap:10px;align-items:flex-start;flex-wrap:wrap;">'
        +'<div style="flex:1;min-width:0;">'
        +'<div style="font-weight:900;font-size:.9rem;color:#5E0E26;">'+esc(t.name||'')
        +' <span style="background:'+col+';color:#fff;border-radius:7px;padding:2px 9px;font-size:.63rem;">'+lbl+'</span></div>'
        +'<div style="font-size:.75rem;color:#777;margin-top:3px;">'+esc(t.school||'')+' · '+esc(t.subject||'')+'</div>'
        +'<div style="font-size:.7rem;color:#aaa;margin-top:1px;">'+esc(t.email||'')+'</div>'
        +(t.note?'<div style="font-size:.74rem;color:#666;margin-top:5px;background:#FDF8EC;border-radius:8px;padding:6px 9px;">'+esc(t.note)+'</div>':'')
        +'</div>'
        +'<div style="display:flex;gap:6px;flex-wrap:wrap;">'
        +(st!=='approved'?'<button onclick="hhSetTeacherStatus(\''+t.id+'\',\'approved\');setTimeout(function(){hhAdmLoadTeachers(\'all\');},900)" style="background:#3D6B53;color:#fff;border:none;border-radius:9px;padding:6px 14px;font-family:Cairo;font-weight:900;font-size:.72rem;cursor:pointer;">اعتماد</button>':'')
        +(st!=='rejected'?'<button onclick="hhSetTeacherStatus(\''+t.id+'\',\'rejected\');setTimeout(function(){hhAdmLoadTeachers(\'all\');},900)" style="background:#fff;color:#c0392b;border:1.5px solid #e0c0c0;border-radius:9px;padding:6px 14px;font-family:Cairo;font-weight:900;font-size:.72rem;cursor:pointer;">رفض</button>':'')
        +'</div></div></div>';
    }).join('');
  }catch(e){
    box.innerHTML='<div style="text-align:center;color:#c0392b;padding:20px;font-family:Cairo;font-weight:800;">تعذر التحميل · تحقق من قواعد Firestore</div>';
  }
}

async function hhAdmLoadClasses(){
  var box=document.getElementById('adm-classes-list'); if(!box) return;
  box.innerHTML='<div style="text-align:center;color:#1F4E79;padding:22px;font-family:Cairo;font-weight:800;">جاري التحميل...</div>';
  try{
    var snap=await firebase.firestore().collection('classes').limit(100).get();
    var items=[]; snap.forEach(function(d){ items.push(Object.assign({id:d.id}, d.data())); });
    if(!items.length){
      box.innerHTML='<div style="text-align:center;color:#999;padding:22px;font-family:Cairo;font-weight:700;">لا صفوف بعد</div>'; return;
    }
    var totalStudents=items.reduce(function(a,c){ return a+((c.studentUids||[]).length); },0);
    box.innerHTML='<div style="display:flex;gap:10px;margin-bottom:12px;flex-wrap:wrap;">'
      +'<div style="background:#E9EEF8;border-radius:12px;padding:11px 16px;text-align:center;flex:1;min-width:110px;font-family:Cairo;">'
      +'<div style="font-size:1.5rem;font-weight:900;color:#1F4E79;">'+items.length+'</div><div style="font-size:.7rem;color:#666;font-weight:800;">صف</div></div>'
      +'<div style="background:#EBF2EE;border-radius:12px;padding:11px 16px;text-align:center;flex:1;min-width:110px;font-family:Cairo;">'
      +'<div style="font-size:1.5rem;font-weight:900;color:#3D6B53;">'+totalStudents+'</div><div style="font-size:.7rem;color:#666;font-weight:800;">طالب منضم</div></div>'
      +'</div>'
      + items.map(function(C){
        var n=(C.studentUids||[]).length;
        var names=(C.students||[]).slice(0,6).map(function(s){return esc(s.name||s.email||'طالب');}).join(' · ');
        return '<div style="background:#fff;border:1.5px solid #E3D9C6;border-right:4px solid #1F4E79;border-radius:12px;padding:13px 15px;margin-bottom:9px;font-family:Cairo,Tajawal,sans-serif;">'
          +'<div style="display:flex;justify-content:space-between;gap:10px;align-items:center;flex-wrap:wrap;">'
          +'<div style="flex:1;min-width:0;">'
          +'<div style="font-weight:900;font-size:.88rem;color:#1F4E79;">'+esc(C.name||'صف')+'</div>'
          +'<div style="font-size:.74rem;color:#777;margin-top:2px;">'+esc(C.subject||'')+' · المعلم: '+esc(C.teacherName||'')+'</div>'
          +'<div style="font-size:.72rem;color:#3D6B53;font-weight:800;margin-top:3px;">'+n+' طالباً'+(names?' · '+names+(n>6?' ...':''):'')+'</div>'
          +'</div>'
          +'<div style="text-align:center;">'
          +'<div style="background:#FDF3DD;border:1.5px dashed #B8924A;border-radius:9px;padding:5px 14px;font-family:monospace;font-weight:900;font-size:1rem;color:#8A6D2E;letter-spacing:2px;">'+esc(C.code||'')+'</div>'
          +'<div style="font-size:.6rem;color:#aaa;margin-top:2px;">كود الصف</div></div>'
          +'</div></div>';
      }).join('');
  }catch(e){
    box.innerHTML='<div style="text-align:center;color:#c0392b;padding:20px;font-family:Cairo;font-weight:800;">تعذر التحميل</div>';
  }
}

async function hhAdmLoadActivity(){
  var box=document.getElementById('adm-activity-list'); if(!box) return;
  box.innerHTML='<div style="text-align:center;color:#3D6B53;padding:22px;font-family:Cairo;font-weight:800;">جاري التحميل...</div>';
  try{
    var snap=await firebase.firestore().collection('platform_activity')
      .orderBy('createdAt','desc').limit(80).get();
    var items=[]; snap.forEach(function(d){ items.push(d.data()); });
    if(!items.length){
      box.innerHTML='<div style="text-align:center;color:#999;padding:22px;font-family:Cairo;font-weight:700;">لا نشاط مسجّل بعد</div>'; return;
    }
    var names={lesson_add:'درس مضاف', generate:'توليد محتوى', game_start:'بدء لعبة'};
    var byType={}; items.forEach(function(x){ byType[x.type]=(byType[x.type]||0)+1; });
    box.innerHTML='<div style="display:flex;gap:9px;flex-wrap:wrap;margin-bottom:12px;">'
      + Object.keys(byType).map(function(k){
          return '<div style="background:#EBF2EE;border-radius:11px;padding:10px 15px;text-align:center;flex:1;min-width:100px;font-family:Cairo;">'
            +'<div style="font-size:1.4rem;font-weight:900;color:#3D6B53;">'+byType[k]+'</div>'
            +'<div style="font-size:.68rem;color:#666;font-weight:800;">'+esc(names[k]||k)+'</div></div>';
        }).join('')
      +'</div>'
      +'<div style="overflow-x:auto;"><table style="width:100%;border-collapse:collapse;font-family:Cairo,Tajawal,sans-serif;">'
      +'<thead><tr style="background:#3D6B53;color:#fff;font-size:.74rem;font-weight:900;">'
      +'<th style="padding:7px 10px;text-align:right;">النوع</th><th style="padding:7px 10px;text-align:right;">التفصيل</th>'
      +'<th style="padding:7px;text-align:right;">المستخدم</th><th style="padding:7px;">التاريخ</th></tr></thead><tbody>'
      + items.map(function(x,i){
          var d=x.createdAt&&x.createdAt.seconds? new Date(x.createdAt.seconds*1000) : null;
          return '<tr style="background:'+(i%2?'#F7FBFF':'#fff')+';">'
            +'<td style="padding:6px 10px;font-size:.74rem;font-weight:800;">'+esc(names[x.type]||x.type||'')+'</td>'
            +'<td style="padding:6px 10px;font-size:.74rem;">'+esc(x.detail||'')+'</td>'
            +'<td style="padding:6px;font-size:.7rem;color:#777;">'+esc(x.user||'')+'</td>'
            +'<td style="padding:6px;font-size:.68rem;color:#aaa;white-space:nowrap;">'+(d?d.toLocaleDateString('ar-QA',{month:'short',day:'numeric'}):'·')+'</td></tr>';
        }).join('')
      +'</tbody></table></div>';
  }catch(e){
    box.innerHTML='<div style="text-align:center;color:#c0392b;padding:20px;font-family:Cairo;font-weight:800;">تعذر التحميل · تحقق من قواعد Firestore</div>';
  }
}

