// ── تحليل CSV/Excel نصياً ──
function hhParseStudentRows(text){
  var lines = String(text||'').split(/\r?\n/).map(function(l){return l.trim();}).filter(Boolean);
  if(!lines.length) return [];
  // كشف الفاصل تلقائياً
  var first=lines[0];
  var sep = (first.split('\t').length > first.split(',').length) ? '\t'
          : (first.split(';').length > first.split(',').length) ? ';' : ',';
  var out=[], startIdx=0;
  // تخطي صف العناوين إن وُجد
  var hdr=lines[0].toLowerCase();
  if(/اسم|name|الطالب|student|رقم|id|بريد|email/.test(hdr) && !/^\d/.test(lines[0])) startIdx=1;
  for(var i=startIdx;i<lines.length;i++){
    var cells=lines[i].split(sep).map(function(c){ return c.replace(/^["']|["']$/g,'').trim(); });
    var name = cells[0]||'';
    if(!name) continue;
    var rec={ name:name };
    // البحث عن بريد ورقم في بقية الأعمدة
    for(var k=1;k<cells.length;k++){
      var v=cells[k]; if(!v) continue;
      if(/@/.test(v) && !rec.email) rec.email=v.toLowerCase();
      else if(/^\d{4,}$/.test(v) && !rec.sid) rec.sid=v;
      else if(!rec.cls) rec.cls=v;
    }
    out.push(rec);
  }
  return out;
}

