function hhCloseBulk(){ var e=document.getElementById('hh-bulk'); if(e) e.remove(); }

function hhBulkSample(){
  var csv='الاسم,البريد الإلكتروني,الرقم\nأحمد محمد الكواري,ahmed@example.com,10201\nسارة علي المري,,10202\nخالد يوسف,khalid@example.com,10203\n';
  var bl=new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'});
  var a=document.createElement('a'); a.href=URL.createObjectURL(bl);
  a.download='قالب_الطلاب.csv'; a.click();
}

function hhBulkFile(input){
  var f=input.files&&input.files[0]; if(!f) return;
  var isXlsx=/\.xlsx?$/i.test(f.name);
  if(isXlsx){
    var box=document.getElementById('bulk-preview');
    if(box) box.innerHTML='<div style="background:#FDF3DD;border:1.5px solid #B8924A;border-radius:11px;padding:12px;font-size:.79rem;color:#8A6D2E;font-weight:800;line-height:1.9;">'
      +'ملفات Excel تحتاج تحويلاً بسيطاً:<br>افتح الملف في Excel ← <b>ملف</b> ← <b>حفظ باسم</b> ← اختر <b>CSV UTF-8</b> ← ثم ارفعه هنا.<br>'
      +'<span style="font-size:.73rem;color:#aaa;">أو انسخ عمود الأسماء والصقه في المربع أدناه مباشرة.</span></div>';
    return;
  }
  var r=new FileReader();
  r.onload=function(e){
    var ta=document.getElementById('bulk-text');
    if(ta) ta.value=String(e.target.result||'');
    hhBulkPreview();
  };
  r.readAsText(f,'utf-8');
}

