      +'<td style="padding:6px 9px;font-weight:800;font-size:.78rem;">'+esc(r.name)+(dup?' <span style="color:#b5801f;font-size:.66rem;">(مكرر)</span>':'')+'</td>'
      +'<td style="padding:6px;font-size:.72rem;color:#888;">'+esc(r.email||'·')+'</td>'
      +'<td style="padding:6px;font-size:.72rem;color:#888;">'+esc(r.sid||'·')+'</td></tr>';
