async function hhSaveIssuer(){
  if(!(typeof hhIsAdmin==='function' && hhIsAdmin())) return;
  var st=document.getElementById('iss-status');
  var org=((document.getElementById('iss-org')||{}).value||'').trim();
  var sub=((document.getElementById('iss-sub')||{}).value||'').trim();
  if(!org){ if(st){st.textContent='اكتب اسم الجهة'; st.style.color='#c0392b';} return; }
  try{
    await firebase.firestore().collection('platform_settings').doc('cert_issuer')
      .set({ org:org, sub:sub, updatedBy:currentUser.email, updatedAt:new Date().toISOString() }, {merge:true});
    _hhCertIssuer={org:org, sub:sub, locked:true};
    try{ localStorage.setItem(_HH_CERT_ISSUER_KEY, JSON.stringify(_hhCertIssuer)); }catch(e){}
    if(st){ st.textContent='حُفظت الجهة وسرت على كل الشهادات'; st.style.color='#3D6B53'; }
    if(typeof toast==='function') toast('حُدّثت الجهة المُصدِرة','success');
    setTimeout(function(){ var e=document.getElementById('hh-issuer'); if(e) e.remove(); }, 1400);
  }catch(e){
    if(st){ st.textContent='تعذر الحفظ · تحقق من قواعد Firestore'; st.style.color='#c0392b'; }
  }
}

