// ═══ حفظ نقاط الفرق في Firestore ═══
async function saveTeamScores(sortedTeams){
  if(OFFLINE_MODE||!db) return;
  try{
    var batch=db.batch();
    sortedTeams.forEach(function(t){
      if(!t.name||!t.pts) return;
      if(typeof t.pts!=='number' || t.pts<0 || t.pts>=10000000) return;
      var ref=db.collection('team_scores').doc(
        t.name.replace(/[^a-zA-Z؀-ۿ0-9]/g,'_').substring(0,80)
      );
      batch.set(ref,{name:t.name,pts:firebase.firestore.FieldValue.increment(t.pts)},{merge:true});
    });
    await batch.commit();
  }catch(e){console.error('saveTeamScores',e);}
}
