// ═══ مرآة الصدارة العامة: تعكس بيانات العرض فقط (بلا هواتف أو بريد) ═══
async function hhMirrorLeaderboard(fields){
  try{
    if(OFFLINE_MODE || !db || typeof currentUser==='undefined' || !currentUser) return;
    var payload = Object.assign({ uid: currentUser.uid,
      updatedAt: firebase.firestore.FieldValue.serverTimestamp() }, fields||{});
    await db.collection('leaderboard').doc(currentUser.uid).set(payload, {merge:true});
  }catch(e){}
}

// ═══ تعبئة المرآة دفعة واحدة (يشغلها الأدمن تلقائياً مرة لكل إصدار) ═══
async function hhAdminBackfillLeaderboard(){
  try{
    if(!hhIsAdmin() || OFFLINE_MODE || !db) return;
    var FLAG='hh_lb_backfill_zs';
    if(localStorage.getItem(FLAG)==='1') return;
    var snap = await db.collection('users').get();
    var batch = db.batch(), n=0, total=0;
    for(var i=0;i<snap.docs.length;i++){
      var d=snap.docs[i], u=d.data();
      if(!(u.points>0) && !(u.gamesPlayed>0)) continue;
      batch.set(db.collection('leaderboard').doc(d.id), {
        uid:d.id, name:u.name||'', points:u.points||0,
        role:u.role||null, gamesPlayed:u.gamesPlayed||0,
        createdAt:u.createdAt||null,
        updatedAt:firebase.firestore.FieldValue.serverTimestamp()
      }, {merge:true});
      n++; total++;
      if(n>=400){ await batch.commit(); batch=db.batch(); n=0; }
    }
    if(n>0) await batch.commit();
    localStorage.setItem(FLAG,'1');
    if(typeof toast==='function' && total>0) toast('مرآة الصدارة عُبّئت: '+total+' لاعباً','success');
  }catch(e){ console.error('backfill leaderboard', e); }
}

