async function loadProfileData(){
  let name='مستخدم',email='',phone='',photoURL='',emailVerified=false;
  if(OFFLINE_MODE){
    const u=currentUser||{};
    name=u.name||'مستخدم';email=u.email||'';phone=u.phone||'';
  }else if(currentUser){
    try{
      const doc=await db.collection('users').doc(currentUser.uid).get();
      const d=doc.exists?doc.data():{};
      name=d.name||currentUser.displayName||'مستخدم';
      email=currentUser.email||'';
      phone=d.phone||'';
      photoURL=currentUser.photoURL||d.photoURL||'';
      emailVerified=currentUser.emailVerified||false;
    }catch(e){}
  }
  // تعيين البيانات
  document.getElementById('profile-greeting').textContent='أهلا، '+name;
  document.getElementById('profile-email-small').textContent=email;
  document.getElementById('pf-name-val').textContent=name;
  document.getElementById('pf-phone-val').textContent=phone||'لم يضف بعد';
  document.getElementById('pf-email-val').textContent=email||'·';
  // شارة التحقق
  const badge=document.getElementById('pf-email-badge');
  if(email){
    if(emailVerified){badge.textContent='موثق';badge.className='profile-verify-badge verified';}
    else{badge.textContent='غير موثق - أرسل رابط';badge.className='profile-verify-badge unverified';badge.onclick=sendVerification;}
  }
  // الصورة
  const initials=(name||'م').charAt(0).toUpperCase();
  setAvatarInitials(initials);
  updateNavAvatar(name,photoURL);
  if(photoURL)setAvatarPhoto(photoURL);
  // عرض التصنيف الحالي
  await loadUserRole();
  const roleEl=document.getElementById('pf-role-val');
  const editBtn=document.getElementById('pf-role-edit-btn');
  if(roleEl){
    const map={
      'teacher':{label:'معلم',color:'#8A1538',icon:'<svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M5 13.18v4L12 21l7-3.82v-4L12 17l-7-3.82zM12 3L1 9l11 6 9-4.91V17h2V9L12 3z"/></svg>'},
      'student':{label:'طالب',color:'#3D6B53',icon:'<svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M21 5c-1.11-.35-2.33-.5-3.5-.5-1.95 0-4.05.4-5.5 1.5-1.45-1.1-3.55-1.5-5.5-1.5S2.45 4.9 1 6v14.65c0 .25.25.5.5.5.1 0 .15-.05.25-.05C3.1 20.45 5.05 20 6.5 20c1.95 0 4.05.4 5.5 1.5 1.35-.85 3.8-1.5 5.5-1.5 1.65 0 3.35.3 4.75 1.05.1.05.15.05.25.05.25 0 .5-.25.5-.5V6c-.6-.45-1.25-.75-2-1z"/></svg>'},
      'other':  {label:'أخرى',color:'#b5801f',icon:'<svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z"/></svg>'}
    };
    const info=map[_currentUserRole];
    roleEl.innerHTML='';
    if(info){
      const span=document.createElement('span');
      span.style.cssText='display:inline-flex;align-items:center;gap:6px;background:'+info.color+';color:#fff;padding:3px 12px;border-radius:20px;font-size:.82rem;font-weight:900;';
      span.innerHTML=info.icon+' '+info.label;
      roleEl.appendChild(span);
      if(_currentRoleChangeCount>=1 && editBtn){
        editBtn.style.opacity='.35';
        editBtn.title='تم استخدام تغيير التصنيف · تواصل مع الدعم';
      }
    } else {
      roleEl.textContent='لم يحدد بعد';
    }
  }
}

function toggleRoleChange(){
  const form=document.getElementById('pf-role-form');
  if(!form)return;
  if(_currentRoleChangeCount>=1){
    toast('تم استخدام تغيير التصنيف مسبقا · تواصل مع الدعم','error');
    return;
  }
  form.style.display = form.style.display==='none' ? 'block' : 'none';
}

function setAvatarInitials(letter){
  const lg=document.getElementById('profile-avatar-lg');
  const img=document.getElementById('profile-img');
  if(img)img.style.display='none';
  if(lg)lg.childNodes[0].textContent=letter;
}

function setAvatarPhoto(url){
  const img=document.getElementById('profile-img');
  if(img){img.src=url;img.style.display='block';}
}

function updateNavAvatar(name,photoURL){
  const av=document.getElementById('nav-avatar');
  if(!av)return;
  if(photoURL){av.innerHTML='<img src="'+photoURL+'" alt="الصورة الشخصية" style="width:100%;height:100%;object-fit:cover;border-radius:50%;">';}
  else{av.textContent=(name||'م').charAt(0).toUpperCase();}
}

function editField(field){
  const input=document.getElementById('pf-'+field+'-input');
  const save=document.getElementById('pf-'+field+'-save');
  const val=document.getElementById('pf-'+field+'-val');
  if(field==='phone'){
    const prefix=document.getElementById('pf-phone-prefix');
    if(prefix)prefix.style.display='flex';
    const current=(val.textContent||'').replace('+974','').replace('لم يضف بعد','').trim();
    input.value=current;
  }else{
    input.value=val.textContent==='·'?'':val.textContent;
  }
  input.classList.add('show');
  save.classList.add('show');
  input.focus();
}

async function saveField(field){
  const input=document.getElementById('pf-'+field+'-input');
  const val=document.getElementById('pf-'+field+'-val');
  const save=document.getElementById('pf-'+field+'-save');
  let value=input.value.trim();
  if(field==='phone'){
    if(value&&(value.length!==8||!/^[5-7]/.test(value))){toast('رقم غير صحيح - يجب 8 أرقام يبدأ بـ 5 أو 6 أو 7','error');return;}
    value=value?'+974'+value:'';
    document.getElementById('pf-phone-val').textContent=value||'لم يضف بعد';
    document.getElementById('pf-phone-prefix').style.display='none';
  }else if(field==='name'){
    if(!value){toast('الاسم لا يمكن أن يكون فارغا','error');return;}
    document.getElementById('pf-name-val').textContent=value;
    document.getElementById('profile-greeting').textContent='أهلا، '+value;
    document.getElementById('ub-name').textContent=value;
    updateNavAvatar(value,'');
  }
  input.classList.remove('show');
  save.classList.remove('show');
  // حفظ في Firebase أو localStorage
  if(!OFFLINE_MODE&&currentUser){
    try{
      const update={};
      if(field==='name')update.name=value;
      if(field==='phone')update.phone=value;
      await db.collection('users').doc(currentUser.uid).update(update);
      toast('تم الحفظ بنجاح','success');
    }catch(e){toast('لم يتم الحفظ','error');}
  }else if(OFFLINE_MODE&&currentUser){
    const users=JSON.parse(localStorage.getItem('hh_users')||'{}');
    if(users[currentUser.id]){
      if(field==='name')users[currentUser.id].name=value;
      if(field==='phone')users[currentUser.id].phone=value;
      localStorage.setItem('hh_users',JSON.stringify(users));
      const sess=JSON.parse(localStorage.getItem('hh_sess')||'{}');
      if(field==='name')sess.name=value;
      if(field==='phone')sess.phone=value;
      localStorage.setItem('hh_sess',JSON.stringify(sess));
      currentUser=sess;
    }
    toast('تم الحفظ بنجاح','success');
  }
}

async function sendVerification(){
  if(OFFLINE_MODE){toast('غير متاح في الوضع المحلي','error');return;}
  try{
    await auth.currentUser.sendEmailVerification();
    toast('تم إرسال رابط التحقق على بريدك','success');
    document.getElementById('pf-email-badge').textContent='تم الإرسال';
  }catch(e){toast('حاول لاحقا','error');}
}

// رفع الصورة
function triggerAvatarUpload(){
  document.getElementById('avatar-input').click();
}

async function handleAvatarChange(e){
  const file=e.target.files[0];
  if(!file)return;
  if(typeof toast==='function') toast('جار معالجة الصورة...', 'info');
  let dataUrl;
  try{
    dataUrl = await hhCompressImage(file, 300, 600);
  }catch(err){
    toast('فشل معالجة الصورة', 'error');
    return;
  }
  const reader = { onload: ()=>{} }; // dummy
  // محاكاة سلوك FileReader.onload
  (async ()=>{
    const ev = { target: { result: dataUrl } };
    setAvatarPhoto(dataUrl);
    updateNavAvatar('',dataUrl);
    // حفظ في localStorage (Firebase Storage يحتاج خطة مدفوعة)
    try{
      if(!OFFLINE_MODE&&currentUser){
        await db.collection('users').doc(currentUser.uid).update({photoURL:dataUrl});
      }else if(OFFLINE_MODE&&currentUser){
        const users=JSON.parse(localStorage.getItem('hh_users')||'{}');
        if(users[currentUser.id])users[currentUser.id].photoURL=dataUrl;
        localStorage.setItem('hh_users',JSON.stringify(users));
        const sess=JSON.parse(localStorage.getItem('hh_sess')||'{}');
        sess.photoURL=dataUrl;localStorage.setItem('hh_sess',JSON.stringify(sess));
      }
      toast('تم تحديث الصورة','success');
    }catch(ex){toast('لم يحفظ','error');}
  })();
}
