/**
 * توليد رمز فصل فريد
 * تنسيق: HH-ABCD12 (8 أحرف: HH- + 4 أحرف + 2 أرقام)
 */
function _generateClassCode(){
  const letters = 'ABCDEFGHJKLMNPQRSTUVWXYZ'; // بدون I و O لتجنب الالتباس
  const digits = '123456789'; // بدون 0
  let code = 'HH-';
  for(let i=0; i<4; i++) code += letters[Math.floor(Math.random()*letters.length)];
  for(let i=0; i<2; i++) code += digits[Math.floor(Math.random()*digits.length)];
  return code;
}

