/**
 * إنشاء فصل جديد في Firebase
 */
async function createClassroom(){
  if(!currentUser || !db){
    toast('تعذر الاتصال بالخادم', 'error');
    return;
  }
  const className = document.getElementById('cc-class-name').value.trim();
  const schoolName = document.getElementById('cc-school-name').value.trim();

  if(!className){
    toast('اكتب اسم الفصل', 'error');
    document.getElementById('cc-class-name').focus();
    return;
  }
  if(className.length < 2){
    toast('اسم الفصل قصير جدا', 'error');
    return;
  }
  if(!schoolName){
    toast('اكتب اسم المدرسة', 'error');
    document.getElementById('cc-school-name').focus();
    return;
  }

  try{
    // توليد رمز فريد (نحاول حتى 5 مرات)
    let code = null;
    for(let i=0; i<5; i++){
      const candidate = _generateClassCode();
      const doc = await db.collection('classrooms').doc(candidate).get();
      if(!doc.exists){ code = candidate; break; }
    }
    if(!code){
      toast('تعذر توليد رمز فريد، حاول مرة أخرى', 'error');
      return;
    }

    // إنشاء الفصل
    await db.collection('classrooms').doc(code).set({
      code: code,
      className: className,
      schoolName: schoolName,
      teacherId: currentUser.uid,
      teacherName: currentUser.displayName || currentUser.email || '',
      teacherEmail: currentUser.email || '',
      studentCount: 0,
      quizCount: 0,
      createdAt: firebase.firestore.FieldValue.serverTimestamp(),
      active: true
    });

    closeCreateClassroomModal();
    toast('تم إنشاء الفصل بنجاح · رمزك: ' + code, 'success');
    await loadMyClassrooms();
  }catch(e){
    console.error('Create classroom error:', e);
    toast('تعذر إنشاء الفصل', 'error');
  }
}

/**
 * تحميل قائمة فصول المعلم الحالي
 */
async function loadMyClassrooms(){
  const container = document.getElementById('classrooms-list-container');
  if(!container || !db || !currentUser) return;

  container.innerHTML = '<div class="classrooms-empty"><div class="classrooms-empty-text">جاري التحميل...</div></div>';

  try{
    const snap = await db.collection('classrooms')
      .where('teacherId', '==', currentUser.uid)
      .where('active', '==', true)
      .get();

    const classrooms = snap.docs.map(d => ({id:d.id, ...d.data()}));

    // ترتيب محليا (الأحدث أولا)
    classrooms.sort((a,b)=>{
      const aTime = a.createdAt?.toMillis?.() || 0;
      const bTime = b.createdAt?.toMillis?.() || 0;
      return bTime - aTime;
    });

    if(classrooms.length === 0){
      container.innerHTML = `
        <div class="classrooms-empty">
          <svg viewBox="0 0 24 24"><path d="M12 3L1 9l11 6 9-4.91V17h2V9M5 13.18v4L12 21l7-3.82v-4L12 17l-7-3.82z"/></svg>
          <div class="classrooms-empty-text">لا توجد فصول بعد</div>
          <div class="classrooms-empty-sub">اضغط "إنشاء فصل جديد" للبدء</div>
        </div> `;
      return;
    }

    container.innerHTML = '<div class="classrooms-list">' +
      classrooms.map(c => _renderClassroomCard(c)).join('') +
      '</div>';

  }catch(e){
    console.error('Load classrooms error:', e);
    container.innerHTML = '<div class="classrooms-empty"><div class="classrooms-empty-text" style="color:#c0392b;">تعذر تحميل الفصول</div></div>';
  }
}

function _renderClassroomCard(c){
  const created = c.createdAt?.toDate?.() 
    ? c.createdAt.toDate().toLocaleDateString('ar-QA', {year:'numeric',month:'short',day:'numeric'})
    : '·';
  const safeCode = esc(c.code);
  const safeName = esc(c.className || '');
  const safeSchool = esc(c.schoolName || '');

  return `
    <div class="classroom-card" data-code="${safeCode}">
      <div class="cc-header">
        <div class="cc-icon">
          <svg viewBox="0 0 24 24"><path d="M12 3L1 9l11 6 9-4.91V17h2V9M5 13.18v4L12 21l7-3.82v-4L12 17l-7-3.82z"/></svg>
        </div>
        <div class="cc-info">
          <div class="cc-name">${safeName}</div>
          <div class="cc-school">${safeSchool}</div>
        </div>
        <button class="cc-delete-btn" onclick="deleteClassroom('${safeCode}', '${safeName.replace(/'/g,"\\'")}')" title="حذف">
          <svg viewBox="0 0 24 24"><path d="M6 19c0 1.1.9 2 2 2h8c1.1 0 2-.9 2-2V7H6v12zM19 4h-3.5l-1-1h-5l-1 1H5v2h14V4z"/></svg>
        </button>
      </div>
      <div class="cc-code-row">
        <span class="cc-code-label">رمز الفصل:</span>
        <span class="cc-code-value">${safeCode}</span>
        <button class="cc-copy-btn" onclick="copyClassCode('${safeCode}', this)">
          <svg viewBox="0 0 24 24"><path d="M16 1H4c-1.1 0-2 .9-2 2v14h2V3h12V1zm3 4H8c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h11c1.1 0 2-.9 2-2V7c0-1.1-.9-2-2-2zm0 16H8V7h11v14z"/></svg> نسخ
        </button>
      </div>
      <div class="cc-meta">
        <div class="cc-meta-item">
          <svg viewBox="0 0 24 24"><path d="M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z"/></svg>
          <span>${c.studentCount || 0} طالب</span>
        </div>
        <div class="cc-meta-item">
          <svg viewBox="0 0 24 24"><path d="M9 11H7v2h2v-2zm4 0h-2v2h2v-2zm4 0h-2v2h2v-2zm2-7h-1V2h-2v2H8V2H6v2H5c-1.11 0-1.99.9-1.99 2L3 20c0 1.1.89 2 2 2h14c1.1 0 2-.9 2-2V6c0-1.1-.9-2-2-2zm0 16H5V9h14v11z"/></svg>
          <span>${created}</span>
        </div>
      </div>
      <button class="cc-manage-btn" onclick="openManageStudents('${safeCode}', '${safeName.replace(/'/g,"\\'")}')">
        <svg viewBox="0 0 24 24" fill="currentColor"><path d="M16 11c1.66 0 2.99-1.34 2.99-3S17.66 5 16 5c-1.66 0-3 1.34-3 3s1.34 3 3 3zm-8 0c1.66 0 2.99-1.34 2.99-3S9.66 5 8 5C6.34 5 5 6.34 5 8s1.34 3 3 3zm0 2c-2.33 0-7 1.17-7 3.5V19h14v-2.5c0-2.33-4.67-3.5-7-3.5zm8 0c-.29 0-.62.02-.97.05 1.16.84 1.97 1.97 1.97 3.45V19h6v-2.5c0-2.33-4.67-3.5-7-3.5z"/></svg> إدارة الطلاب
      </button>
    </div> `;
}

/**
 * نسخ رمز الفصل للحافظة
 */
function copyClassCode(code, btnEl){
  if(navigator.clipboard){
    navigator.clipboard.writeText(code).then(()=>{
      btnEl.classList.add('copied');
      btnEl.innerHTML = '<svg viewBox="0 0 24 24"><path d="M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41L9 16.17z"/></svg>تم النسخ';
      setTimeout(()=>{
        btnEl.classList.remove('copied');
        btnEl.innerHTML = '<svg viewBox="0 0 24 24"><path d="M16 1H4c-1.1 0-2 .9-2 2v14h2V3h12V1zm3 4H8c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h11c1.1 0 2-.9 2-2V7c0-1.1-.9-2-2-2zm0 16H8V7h11v14z"/></svg>نسخ';
      }, 1800);
    }).catch(()=>{
      toast('تعذر النسخ', 'error');
    });
  } else {
    // Fallback: طريقة قديمة
    const ta = document.createElement('textarea');
    ta.value = code;
    document.body.appendChild(ta);
    ta.select();
    try{ document.execCommand('copy'); toast('تم نسخ الرمز', 'success'); }
    catch(e){ toast('تعذر النسخ', 'error'); }
    document.body.removeChild(ta);
  }
}

/**
 * حذف فصل (مع تأكيد)
 */
async function deleteClassroom(code, name){
  if(!confirm('هل تريد حذف فصل "' + name + '"؟\n\nسيتم إخفاؤه من قائمتك ولن يستطيع الطلاب استخدام رمزه.\nلكن البيانات تبقى محفوظة.')){
    return;
  }
  if(!db || !currentUser) return;

  try{
    // حذف "ناعم" · نجعله غير نشط بدل الحذف الفعلي
    await db.collection('classrooms').doc(code).update({
      active: false,
      deletedAt: firebase.firestore.FieldValue.serverTimestamp()
    });
    toast('تم حذف الفصل', 'success');
    await loadMyClassrooms();
  }catch(e){
    console.error('Delete classroom error:', e);
    toast('تعذر الحذف', 'error');
  }
}

// ═══════════════════════════════════════════════════════════════════
// نظام إدارة طلاب الفصل · Students Management
// ═══════════════════════════════════════════════════════════════════

// الفصل النشط حاليا في شاشة الطلاب
let _currentManagedClass = null;

/**
 * فتح شاشة إدارة طلاب فصل معين
 */
async function openManageStudents(classCode, className){
  if(!currentUser || !db){
    toast('تعذر الاتصال','error');
    return;
  }
  try{
    const doc = await db.collection('classrooms').doc(classCode).get();
    if(!doc.exists){
      toast('الفصل غير موجود','error');
      return;
    }
    const data = doc.data();
    if(data.teacherId !== currentUser.uid && !isAdminUser(currentUser)){
      toast('لا تملك صلاحية إدارة هذا الفصل','error');
      return;
    }
    _currentManagedClass = {code:classCode, ...data};
    // حفظ اسم الفصل لاستخدامه في اقتراح اسم اللعبة
    try{ localStorage.setItem('hh_last_class_name', data.className || ''); }catch(e){}
    document.getElementById('sh-class-name').textContent = data.className;
    document.getElementById('sh-school-name').textContent = data.schoolName;
    document.getElementById('sh-class-code').textContent = classCode;
    showScreen('screen-students');
    await loadClassStudents();
  }catch(e){
    console.error(e);
    toast('تعذر فتح الفصل','error');
  }
}

/**
 * تحميل قائمة طلاب الفصل الحالي
 */
async function loadClassStudents(){
  const container = document.getElementById('students-list-container');
  const countEl = document.getElementById('students-total-count');
  if(!container || !_currentManagedClass) return;

  container.innerHTML = '<div class="students-empty"><div class="students-empty-text">جاري التحميل...</div></div>';

  try{
    const snap = await db.collection('classroom_students')
      .where('classCode','==',_currentManagedClass.code)
      .where('active','==',true)
      .get();

    const students = snap.docs.map(d => ({id:d.id, ...d.data()}));
    // ترتيب حسب تاريخ الإضافة (الأحدث أولا)
    students.sort((a,b)=>{
      const aT = a.addedAt?.toMillis?.() || 0;
      const bT = b.addedAt?.toMillis?.() || 0;
      return bT - aT;
    });

    if(countEl) countEl.textContent = students.length;

    if(students.length === 0){
      container.innerHTML = `
        <div class="students-empty">
          <svg viewBox="0 0 24 24"><path d="M16 11c1.66 0 2.99-1.34 2.99-3S17.66 5 16 5c-1.66 0-3 1.34-3 3s1.34 3 3 3zm-8 0c1.66 0 2.99-1.34 2.99-3S9.66 5 8 5C6.34 5 5 6.34 5 8s1.34 3 3 3zm0 2c-2.33 0-7 1.17-7 3.5V19h14v-2.5c0-2.33-4.67-3.5-7-3.5z"/></svg>
          <div class="students-empty-text">لا يوجد طلاب في هذا الفصل</div>
          <div class="students-empty-sub">اضغط "إضافة طالب" لبدء تكوين القائمة</div>
        </div> `;
      return;
    }

    container.innerHTML = '<div class="students-list">' + students.map(s => {
      const safeName = esc(s.studentName || 'بدون اسم');
      const firstLetter = (s.studentName || '?').trim().charAt(0);
      const joined = !!s.userId;
      const added = s.addedAt?.toDate?.()
        ? s.addedAt.toDate().toLocaleDateString('ar-QA',{month:'short',day:'numeric'})
        : '';
      return `
        <div class="student-item" data-id="${esc(s.id)}">
          <div class="student-avatar">${esc(firstLetter)}</div>
          <div class="student-info">
            <div class="student-name">${safeName}</div>
            <div class="student-meta">
              <span class="student-badge ${joined?'joined':'pending'}">${joined?'منضم':'بانتظار الانضمام'}</span> ${added?'<span>أضيف '+added+'</span>':''}
            </div>
          </div>
          <button class="student-delete" onclick="removeStudentFromClass('${esc(s.id)}','${safeName.replace(/'/g,"\\'")}')" title="حذف">
            <svg viewBox="0 0 24 24"><path d="M6 19c0 1.1.9 2 2 2h8c1.1 0 2-.9 2-2V7H6v12zM19 4h-3.5l-1-1h-5l-1 1H5v2h14V4z"/></svg>
          </button>
        </div> `;
    }).join('') + '</div>';
  }catch(e){
    console.error('Load students error:',e);
    container.innerHTML = '<div class="students-empty"><div class="students-empty-text" style="color:#c0392b;">تعذر تحميل القائمة</div></div>';
  }
}

/**
 * فتح مودال إضافة طالب
 */
function openAddStudentModal(){
  if(!_currentManagedClass){ toast('اختر فصلا أولا','error'); return; }
  document.getElementById('new-student-name').value = '';
  document.getElementById('add-student-modal').classList.add('active');
  document.body.style.overflow = 'hidden';
  setTimeout(()=>document.getElementById('new-student-name').focus(), 100);
}

function closeAddStudentModal(){
  document.getElementById('add-student-modal').classList.remove('active');
  document.body.style.overflow = '';
}

/**
 * إضافة طالب للفصل الحالي
 */
async function addStudentToClass(){
  if(!_currentManagedClass || !db) return;
  const name = document.getElementById('new-student-name').value.trim();
  if(!name){ toast('اكتب اسم الطالب','error'); return; }
  if(name.length < 5){ toast('الاسم قصير · أدخل الاسم الثلاثي','error'); return; }

  try{
    await db.collection('classroom_students').add({
      classCode: _currentManagedClass.code,
      className: _currentManagedClass.className,
      schoolName: _currentManagedClass.schoolName || '',
      teacherId: _currentManagedClass.teacherId,
      studentName: name,
      userId: null, // يملأ عند انضمام الطالب فعليا
      active: true,
      addedAt: firebase.firestore.FieldValue.serverTimestamp()
    });
    // تحديث عدد الطلاب في الفصل
    try{
      await db.collection('classrooms').doc(_currentManagedClass.code).update({
        studentCount: firebase.firestore.FieldValue.increment(1)
      });
    }catch(e){}
    closeAddStudentModal();
    toast('تمت إضافة الطالب','success');
    await loadClassStudents();
  }catch(e){
    console.error(e);
    toast('تعذر الإضافة','error');
  }
}

/**
 * حذف طالب من الفصل
 */
async function removeStudentFromClass(studentDocId, name){
  if(!confirm('هل تريد حذف "'+name+'" من الفصل؟')) return;
  try{
    await db.collection('classroom_students').doc(studentDocId).update({
      active:false,
      removedAt: firebase.firestore.FieldValue.serverTimestamp()
    });
    // تقليل العدد
    try{
      await db.collection('classrooms').doc(_currentManagedClass.code).update({
        studentCount: firebase.firestore.FieldValue.increment(-1)
      });
    }catch(e){}
    toast('تم الحذف','success');
    await loadClassStudents();
  }catch(e){
    console.error(e);
    toast('تعذر الحذف','error');
  }
}

/**
 * نسخ رمز الفصل الحالي للحافظة (من داخل شاشة إدارة الطلاب)
 */
function copyCurrentClassCode(){
  if(!_currentManagedClass) return;
  const code = _currentManagedClass.code;
  if(navigator.clipboard){
    navigator.clipboard.writeText(code).then(()=>{
      toast('تم نسخ الرمز: '+code,'success');
    });
  }
}

// ═══════════════════════════════════════════════════════════════════
// الطالب ينضم لفصل
// ═══════════════════════════════════════════════════════════════════

function openJoinClassModal(){
  if(!currentUser){
    toast('سجل الدخول أولا','error');
    return;
  }
  document.getElementById('join-class-code').value = '';
  document.getElementById('join-class-modal').classList.add('active');
  document.body.style.overflow = 'hidden';
  setTimeout(()=>document.getElementById('join-class-code').focus(), 100);
}

function closeJoinClassModal(){
  document.getElementById('join-class-modal').classList.remove('active');
  document.body.style.overflow = '';
}

/**
 * الطالب يدخل رمز الفصل ويرتبط به
 */
async function joinClassroom(){
  if(!currentUser || !db) return;
  const codeInput = document.getElementById('join-class-code').value.trim().toUpperCase();
  if(!codeInput){ toast('أدخل رمز الفصل','error'); return; }

  try{
    const classDoc = await db.collection('classrooms').doc(codeInput).get();
    if(!classDoc.exists || !classDoc.data().active){
      toast('رمز الفصل غير صحيح','error');
      return;
    }
    const classData = classDoc.data();

    // هل الطالب مسجل سابقا من قبل المعلم (بالاسم)؟
    // نربط userId بسجله إن وجد
    const studentName = currentUser.displayName || (await _getUserName(currentUser.uid)) || '';
    
    // البحث عن سجل قائم بنفس userId
    const existing = await db.collection('classroom_students')
      .where('classCode','==',codeInput)
      .where('userId','==',currentUser.uid)
      .where('active','==',true)
      .limit(1).get();
    
    if(!existing.empty){
      toast('أنت بالفعل في هذا الفصل','info');
      closeJoinClassModal();
      return;
    }

    // إنشاء سجل انضمام جديد
    await db.collection('classroom_students').add({
      classCode: codeInput,
      className: classData.className,
      schoolName: classData.schoolName || '',
      teacherId: classData.teacherId,
      teacherName: classData.teacherName || '',
      studentName: studentName || 'طالب',
      userId: currentUser.uid,
      userEmail: currentUser.email || '',
      active: true,
      joinedAt: firebase.firestore.FieldValue.serverTimestamp(),
      addedAt: firebase.firestore.FieldValue.serverTimestamp()
    });

    // تحديث حقل الطالب بأنه انضم لفصل
    try{
      await db.collection('users').doc(currentUser.uid).update({
        currentClassCode: codeInput,
        currentClassName: classData.className
      });
    }catch(e){}

    closeJoinClassModal();
    toast('تم الانضمام لفصل "'+classData.className+'" بنجاح!','success');
    await loadMyClass();
  }catch(e){
    console.error('Join class error:',e);
    toast('تعذر الانضمام','error');
  }
}

async function _getUserName(uid){
  try{
    const d = await db.collection('users').doc(uid).get();
    return d.exists ? (d.data().name || '') : '';
  }catch(e){ return ''; }
}

/**
 * تحميل معلومات فصل الطالب الحالي (إن وجد)
 */
async function loadMyClass(){
  if(!currentUser || !db) return null;
  try{
    const snap = await db.collection('classroom_students')
      .where('userId','==',currentUser.uid)
      .where('active','==',true)
      .limit(1).get();
    if(snap.empty) return null;
    const data = snap.docs[0].data();
    return {docId:snap.docs[0].id, ...data};
  }catch(e){
    console.warn('loadMyClass error:',e);
    return null;
  }
}

/**
 * مغادرة الفصل (للطالب)
 */
async function leaveMyClass(){
  if(!confirm('هل تريد مغادرة فصلك الحالي؟')) return;
  const myClass = await loadMyClass();
  if(!myClass) return;
  try{
    await db.collection('classroom_students').doc(myClass.docId).update({
      active:false,
      leftAt: firebase.firestore.FieldValue.serverTimestamp()
    });
    try{
      await db.collection('users').doc(currentUser.uid).update({
        currentClassCode: firebase.firestore.FieldValue.delete(),
        currentClassName: firebase.firestore.FieldValue.delete()
      });
    }catch(e){}
    toast('تمت المغادرة','success');
    // إعادة تحميل واجهة الطالب إن كانت مفتوحة
    const card = document.getElementById('my-class-card-wrap');
    if(card) card.innerHTML = '';
  }catch(e){
    console.error(e);
    toast('تعذر المغادرة','error');
  }
}

// ═══════════════════════════════════════════════════════════════════

async function canAccessExclusive(u){
  // الأساطير صارت متاحة للجميع · لا تحتاج صلاحية ولا تسجيل دخول
  return true;
}

// متغير عالمي لتخزين حالة الصلاحية (الأساطير متاحة للجميع الآن)
window._hasExclusiveAccess = true;

// تحديث حالة الصلاحية عند تسجيل الدخول / تغير المستخدم
async function refreshExclusiveAccess(u){
  window._hasExclusiveAccess = await canAccessExclusive(u);
  // تحديث زر الشخصيات المؤثرة
  updateInfluencersBtn(u);
}
// ═══════════════════════════════════════════════════════════════════

function showAdminBtn(u){
  const btn=document.getElementById('admin-menu-btn');
  if(btn){
    const restricted = (typeof _hhIsRestrictedPartner === 'function') && _hhIsRestrictedPartner(u);
    btn.style.display = (isAdminUser(u) || restricted) ? 'block' : 'none';
  }
  updateRoyalToolsVisibility();
}

// تحديث زر الأسئلة المخصصة بناء على الصلاحية
async function updateEditorBtn(u){
  const can = await isQuestionEditor(u);
  //  خانة "للمعلم" الجديدة (تتضمن: مولد الأنشطة + الحقيبة + فصولي + أسئلتي)
  const teacherGroup = document.getElementById('teacher-tools-group');
  if(teacherGroup) teacherGroup.style.display = can ? 'block' : 'none';
  updateRoyalToolsVisibility();
}

// تحديث زر الشخصيات المؤثرة (ظاهر للجميع الآن)
function updateInfluencersBtn(u){
  // الزر ظاهر دائما · الفلترة داخل الشاشة تتم حسب حالة النشر
  updateRoyalToolsVisibility();
}

// تحديث ظهور قسم "أدوات المعلم" الرئيسي
function updateRoyalToolsVisibility(){
  // قسم "إدارة المنصة" يظهر للأدمن أو للشريك المقيّد (الذي يحتاج محرّر الأسئلة)
  const section = document.getElementById('royal-tools-section');
  if(!section) return;
  const adminBtn = document.getElementById('admin-menu-btn');
  const hasAdmin = adminBtn && adminBtn.style.display !== 'none';
  section.style.display = hasAdmin ? 'block' : 'none';
}

// ═══════════════ شخصيات مؤثرة (Influencers) ═══════════════
// قائمة الشخصيات الافتراضية (غير منشورة افتراضيا · الأدمن يقرر النشر)
const DEFAULT_INFLUENCERS = [
  {
    id: 'afrah',
    name: 'أ. أفراح الرياشي',
    role: 'رئيس قسم التوجيه التربوي · دراسات اجتماعية',
    desc: 'قيادة تربوية متميزة',
    initials: 'أ.ر',
    published: false
  },
  {
    id: 'jaber',
    name: 'أ. جابر المري',
    role: 'موجه تربوي · دراسات اجتماعية',
    desc: 'خبرة ميدانية عميقة',
    initials: 'ج.م',
    published: false
  }
];

// تحميل الشخصيات من localStorage (مع fallback للافتراضية)
function getInfluencers(){
  try{
    const saved = localStorage.getItem('hh_influencers');
    if(saved){
      const parsed = JSON.parse(saved);
      if(Array.isArray(parsed) && parsed.length > 0) return parsed;
    }
  }catch(e){}
  return [...DEFAULT_INFLUENCERS];
}

// حفظ الشخصيات
function saveInfluencers(list){
  try{
    localStorage.setItem('hh_influencers', JSON.stringify(list));
  }catch(e){ toast('تعذر الحفظ · الذاكرة ممتلئة', 'error'); }
}

// عرض الشخصيات في الشاشة
function loadInfluencers(){
  const allList = getInfluencers();
  const listEl = document.getElementById('influencers-list');
  const addBtn = document.getElementById('influencer-add-btn');
  if(!listEl) return;
  const isAdmin = isAdminUser(currentUser);
  // إظهار زر الإضافة للأدمن فقط
  if(addBtn) addBtn.style.display = isAdmin ? 'block' : 'none';

  // فلترة حسب الصلاحية:
  // - الأدمن: يرى الجميع (منشور وغير منشور)
  // - الزائر العادي: يرى المنشور فقط
  const visibleList = isAdmin
    ? allList
    : allList.filter(p => p.published === true);

  // إذا لا توجد شخصيات منشورة (للزائر) → رسالة جميلة
  if(!isAdmin && visibleList.length === 0){
    listEl.innerHTML = `
      <div style="background:linear-gradient(135deg,#fff8e8 0%,#fdfaf0 100%);border:2px solid #B8924A;border-radius:16px;padding:32px 24px;text-align:center;box-shadow:0 4px 16px rgba(184,146,74,.15);">
        <div style="width:70px;height:70px;margin:0 auto 16px;background:linear-gradient(135deg,#B8924A,#e8c968);border-radius:50%;display:flex;align-items:center;justify-content:center;box-shadow:0 4px 12px rgba(184,146,74,.35);">
          <svg width="36" height="36" viewBox="0 0 24 24" fill="#fff"><path d="M12 2l2.39 7.36H22l-6.19 4.5L18.18 22 12 17.27 5.82 22l2.37-8.14L2 9.36h7.61z"/></svg>
        </div>
        <div style="font-family:Cairo,sans-serif;font-weight:900;color:#8A6D2E;font-size:1.05rem;margin-bottom:10px;line-height:1.6;"> هذه الشخصيات داعمة للمنصة
        </div>
        <div style="font-family:Tajawal,sans-serif;font-weight:500;color:#96771a;font-size:.92rem;line-height:1.8;"> دعمهم سبب في نجاحها وتميزها<br>
          <span style="font-weight:900;color:#8A6D2E;">بإذن الله</span>
        </div>
        <div style="margin-top:18px;padding:10px;background:rgba(184,146,74,.1);border-radius:10px;border:1px dashed #B8924A;">
          <span style="font-size:.78rem;color:#8A6D2E;font-weight:700;">قريبا · أسماء تضاء بها صفحة الشكر</span>
        </div>
      </div> `;
    return;
  }

  // عرض البطاقات
  listEl.innerHTML = visibleList.map((p, visibleIdx) => {
    // نحتاج الـ original index (من القائمة الكاملة) لتمريره للمحرر
    const origIdx = allList.findIndex(x => x.id === p.id);
    const savedImg = localStorage.getItem('influencer_img_' + p.id);
    const imgHtml = savedImg
      ? `<img src="${savedImg}" alt="${esc(p.name)}" style="width:100%;height:100%;object-fit:cover;">`
      : `<span style="font-family:Cairo;font-weight:900;font-size:1.5rem;color:#8A6D2E;">${esc(p.initials || p.name.charAt(0))}</span>`;

    // للأدمن: أزرار التحكم (تعديل + تبديل النشر + حذف)
    let adminControls = '';
    if(isAdmin){
      const published = p.published === true;
      adminControls = `
        <div style="position:absolute;top:8px;left:8px;display:flex;gap:6px;z-index:5;">
          <button onclick="event.stopPropagation();toggleInfluencerPublish(${origIdx})" title="${published?'مخفي عن النشر':'نشر للجمهور'}"
            style="width:34px;height:34px;border-radius:50%;background:${published?'#3D6B53':'#888'};color:#fff;border:2px solid #fff;cursor:pointer;display:flex;align-items:center;justify-content:center;box-shadow:0 2px 6px rgba(0,0,0,.2);transition:transform .15s;" onmouseover="this.style.transform='scale(1.1)'" onmouseout="this.style.transform=''"> ${published
              ? '<svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor"><path d="M12 4.5C7 4.5 2.73 7.61 1 12c1.73 4.39 6 7.5 11 7.5s9.27-3.11 11-7.5c-1.73-4.39-6-7.5-11-7.5zM12 17c-2.76 0-5-2.24-5-5s2.24-5 5-5 5 2.24 5 5-2.24 5-5 5zm0-8a3 3 0 100 6 3 3 0 000-6z"/></svg>' : '<svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor"><path d="M12 7c2.76 0 5 2.24 5 5 0 .65-.13 1.26-.36 1.83l2.92 2.92c1.51-1.26 2.7-2.89 3.43-4.75-1.73-4.39-6-7.5-11-7.5-1.4 0-2.74.25-3.98.7l2.16 2.16C10.74 7.13 11.35 7 12 7zM2 4.27l2.28 2.28.46.46C3.08 8.3 1.78 10.02 1 12c1.73 4.39 6 7.5 11 7.5 1.55 0 3.03-.3 4.38-.84l.42.42L19.73 22 21 20.73 3.27 3 2 4.27zM7.53 9.8l1.55 1.55c-.05.21-.08.43-.08.65 0 1.66 1.34 3 3 3 .22 0 .44-.03.65-.08l1.55 1.55c-.67.33-1.41.53-2.2.53-2.76 0-5-2.24-5-5 0-.79.2-1.53.53-2.2zm4.31-.78l3.15 3.15.02-.16c0-1.66-1.34-3-3-3l-.17.01z"/></svg>' }
          </button>
          <button onclick="event.stopPropagation();openInfluencerEditor(${origIdx})" title="تعديل"
            style="width:34px;height:34px;border-radius:50%;background:rgba(184,146,74,.95);color:#fff;border:2px solid #fff;cursor:pointer;display:flex;align-items:center;justify-content:center;box-shadow:0 2px 6px rgba(0,0,0,.2);transition:transform .15s;" onmouseover="this.style.transform='scale(1.1)'" onmouseout="this.style.transform=''">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor"><path d="M3 17.25V21h3.75L17.81 9.94l-3.75-3.75L3 17.25zM20.71 7.04c.39-.39.39-1.02 0-1.41l-2.34-2.34c-.39-.39-1.02-.39-1.41 0l-1.83 1.83 3.75 3.75 1.83-1.83z"/></svg>
          </button>
          <button onclick="event.stopPropagation();deleteInfluencerDirect(${origIdx})" title="حذف نهائي"
            style="width:34px;height:34px;border-radius:50%;background:#c0392b;color:#fff;border:2px solid #fff;cursor:pointer;display:flex;align-items:center;justify-content:center;box-shadow:0 2px 6px rgba(0,0,0,.2);transition:transform .15s;" onmouseover="this.style.transform='scale(1.1)'" onmouseout="this.style.transform=''">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor"><path d="M6 19c0 1.1.9 2 2 2h8c1.1 0 2-.9 2-2V7H6v12zM19 4h-3.5l-1-1h-5l-1 1H5v2h14V4z"/></svg>
          </button>
        </div> `;
    }

    // شارة "مخفي" للأدمن (ليعرف أن هذه الشخصية غير منشورة)
    const hiddenBadge = (isAdmin && p.published !== true)
      ? '<div style="position:absolute;bottom:8px;left:10px;background:#888;color:#fff;font-size:.6rem;font-weight:900;padding:2px 8px;border-radius:10px;font-family:Cairo;letter-spacing:.3px;">مخفي</div>' : '';

    // إذا الشخصية مخفية (ويرى الأدمن)، نخفف الشكل قليلا
    const hiddenStyle = (isAdmin && p.published !== true) ? 'opacity:.7;' : '';

    return `
    <div style="background:#fff;border:2px solid #e0e8f0;border-right:4px solid #B8924A;border-radius:14px;padding:18px;margin-bottom:14px;display:flex;align-items:center;gap:14px;box-shadow:0 3px 12px rgba(184,146,74,.08);position:relative;transition:all .2s;${hiddenStyle}"> ${adminControls}
      ${hiddenBadge}
      <div style="position:absolute;top:10px;right:14px;width:26px;height:26px;border-radius:50%;background:#8A1538;color:#fff;display:flex;align-items:center;justify-content:center;font-family:Cairo;font-weight:900;font-size:.72rem;">${visibleIdx+1}</div>
      <div style="width:72px;height:72px;border-radius:50%;background:linear-gradient(135deg,#fff8e8,#f5e9a8);border:3px solid #B8924A;display:flex;align-items:center;justify-content:center;flex-shrink:0;overflow:hidden;box-shadow:0 3px 10px rgba(184,146,74,.25);"> ${imgHtml}
      </div>
      <div style="flex:1;min-width:0;padding-top:4px;">
        <div style="font-family:Cairo,sans-serif;font-weight:900;color:#8A1538;font-size:1rem;margin-bottom:4px;">${esc(p.name)}</div>
        <div style="display:inline-flex;align-items:center;gap:5px;padding:3px 10px;background:linear-gradient(135deg,#fff8e8,#fdfaf0);border:1.5px solid #B8924A;border-radius:20px;margin-bottom:5px;">
          <svg width="11" height="11" viewBox="0 0 24 24" fill="#B8924A"><path d="M12 2l2.39 7.36H22l-6.19 4.5L18.18 22 12 17.27 5.82 22l2.37-8.14L2 9.36h7.61z"/></svg>
          <span style="font-size:.72rem;font-weight:800;color:#8A6D2E;">${esc(p.role)}</span>
        </div>
        <div style="display:flex;align-items:center;gap:5px;">
          <svg width="11" height="11" viewBox="0 0 24 24" fill="#888"><path d="M12 2L2 8.5v7L12 22l10-6.5v-7L12 2zm0 2.311L19.764 9 12 13.689 4.236 9 12 4.311z"/></svg>
          <span style="font-size:.76rem;color:#777;font-weight:500;">${esc(p.desc)}</span>
        </div>
      </div>
    </div>`;
  }).join('');
}

// تبديل حالة النشر (أدمن فقط)
function toggleInfluencerPublish(idx){
  if(!isAdminUser(currentUser)){ toast('صلاحية مقتصرة على الأدمن', 'warn'); return; }
  const list = getInfluencers();
  if(!list[idx]) return;
  list[idx].published = !(list[idx].published === true);
  saveInfluencers(list);
  loadInfluencers();
  toast(list[idx].published ? 'تم نشر "'+list[idx].name+'" للجمهور' : 'تم إخفاء "'+list[idx].name+'" عن الجمهور', 'success');
}

// فتح محرر الشخصية
function openInfluencerEditor(idx){
  if(!isAdminUser(currentUser)){ toast('صلاحية مقتصرة على الأدمن', 'warn'); return; }
  const modal = document.getElementById('influencer-editor');
  const list = getInfluencers();
  const titleEl = document.getElementById('influencer-editor-title');
  const delBtn = document.getElementById('influencer-delete-btn');
  const preview = document.getElementById('influencer-img-preview');
  const removeBtn = document.getElementById('influencer-img-remove');

  if(idx !== undefined && list[idx]){
    const p = list[idx];
    document.getElementById('influencer-edit-idx').value = idx;
    document.getElementById('influencer-name').value = p.name;
    document.getElementById('influencer-role').value = p.role;
    document.getElementById('influencer-desc').value = p.desc || '';
    titleEl.textContent = 'تعديل: ' + p.name;
    delBtn.style.display = 'block';
    // استعراض الصورة الحالية إن وجدت
    const savedImg = localStorage.getItem('influencer_img_' + p.id);
    if(savedImg){
      preview.innerHTML = `<img src="${savedImg}" alt="" style="width:100%;height:100%;object-fit:cover;">`;
      removeBtn.style.display = 'inline-block';
    } else {
      preview.innerHTML = `<span>${esc(p.initials || p.name.charAt(0))}</span>`;
      removeBtn.style.display = 'none';
    }
  } else {
    document.getElementById('influencer-edit-idx').value = '';
    document.getElementById('influencer-name').value = '';
    document.getElementById('influencer-role').value = '';
    document.getElementById('influencer-desc').value = '';
    titleEl.textContent = 'إضافة شخصية جديدة';
    delBtn.style.display = 'none';
    preview.innerHTML = '<span>؟</span>';
    removeBtn.style.display = 'none';
  }
  modal.style.display = 'flex';
}

// ضغط الصورة تلقائيا قبل الحفظ (يقبل أي حجم، يضغط لـ ~400KB)
window.hhCompressImage = window.hhCompressImage || function(file, maxSizeKB, maxDimension){
  return new Promise((resolve, reject) => {
    if(!file || !file.type.startsWith('image/')){
      reject(new Error('ليس صورة'));
      return;
    }
    maxSizeKB = maxSizeKB || 400;
    maxDimension = maxDimension || 1200;
    const reader = new FileReader();
    reader.onload = e => {
      const img = new Image();
      img.onload = () => {
        // حساب الأبعاد الجديدة
        let w = img.width, h = img.height;
        if(w > maxDimension || h > maxDimension){
          if(w > h){ h = h * maxDimension / w; w = maxDimension; }
          else    { w = w * maxDimension / h; h = maxDimension; }
        }
        const canvas = document.createElement('canvas');
        canvas.width = Math.round(w);
        canvas.height = Math.round(h);
        const ctx = canvas.getContext('2d');
        ctx.fillStyle = '#fff';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        // ضغط متدرج: نبدأ بجودة 0.85 وننزل حتى نصل للحجم المطلوب
        let quality = 0.85;
        let dataUrl = canvas.toDataURL('image/jpeg', quality);
        const targetBytes = maxSizeKB * 1024 * 1.37; // base64 overhead
        while(dataUrl.length > targetBytes && quality > 0.4){
          quality -= 0.1;
          dataUrl = canvas.toDataURL('image/jpeg', quality);
        }
        resolve(dataUrl);
      };
      img.onerror = () => reject(new Error('فشل تحميل الصورة'));
      img.src = e.target.result;
    };
    reader.onerror = () => reject(new Error('فشل قراءة الملف'));
    reader.readAsDataURL(file);
  });
};

// معاينة الصورة المرفوعة
function previewInfluencerImg(event){
  const file = event.target.files[0];
  if(!file) return;
  if(typeof toast==='function') toast('جار معالجة الصورة...', 'info');
  hhCompressImage(file, 400, 800).then(dataUrl => {
    const preview = document.getElementById('influencer-img-preview');
    preview.innerHTML = `<img src="${dataUrl}" alt="" style="width:100%;height:100%;object-fit:cover;">`;
    document.getElementById('influencer-img-remove').style.display = 'inline-block';
    preview.dataset.newImg = dataUrl;
    if(typeof toast==='function') toast('تم تحميل الصورة', 'success');
  }).catch(err => {
    if(typeof toast==='function') toast('فشل معالجة الصورة', 'error');
    console.error(err);
  });
}

// إزالة الصورة
function removeInfluencerImg(){
  const preview = document.getElementById('influencer-img-preview');
  const idx = document.getElementById('influencer-edit-idx').value;
  const list = getInfluencers();
  const initials = idx !== '' && list[parseInt(idx)] ? list[parseInt(idx)].initials : '؟';
  preview.innerHTML = `<span>${esc(initials)}</span>`;
  preview.dataset.removeImg = '1';
  delete preview.dataset.newImg;
  document.getElementById('influencer-img-remove').style.display = 'none';
}

// حفظ الشخصية
function saveInfluencer(){
  const name = document.getElementById('influencer-name').value.trim();
  const role = document.getElementById('influencer-role').value.trim();
  const desc = document.getElementById('influencer-desc').value.trim();
  if(!name || !role){ toast('الاسم والمنصب مطلوبان', 'warn'); return; }
  const editIdx = document.getElementById('influencer-edit-idx').value;
  const list = getInfluencers();
  // استخراج الأحرف الأولى (initials) من الاسم
  const extractInitials = (fullName) => {
    const parts = fullName.replace(/^أ\.\s*/,'').trim().split(/\s+/);
    if(parts.length >= 2) return parts[0].charAt(0) + '.' + parts[parts.length-1].charAt(0);
    return parts[0].substring(0,2);
  };
  let targetId;
  if(editIdx !== ''){
    // تعديل · spread operator يحافظ على published تلقائيا
    const i = parseInt(editIdx);
    targetId = list[i].id;
    list[i] = { ...list[i], name, role, desc, initials: extractInitials(name) };
  } else {
    // إضافة · إنشاء id جديد (مخفي افتراضيا)
    targetId = 'p_' + Date.now();
    list.push({ id: targetId, name, role, desc, initials: extractInitials(name), published: false });
  }
  // معالجة الصورة
  const preview = document.getElementById('influencer-img-preview');
  if(preview.dataset.newImg){
    try{ localStorage.setItem('influencer_img_' + targetId, preview.dataset.newImg);
      if(typeof _hh_saveInfluencerImgToCloud === 'function') _hh_saveInfluencerImgToCloud(targetId, preview.dataset.newImg);
    }catch(e){ toast('الذاكرة ممتلئة · لم تحفظ الصورة','warn'); }
    delete preview.dataset.newImg;
  } else if(preview.dataset.removeImg === '1'){
    localStorage.removeItem('influencer_img_' + targetId);
    delete preview.dataset.removeImg;
  }
  saveInfluencers(list);
  closeInfluencerEditor();
  loadInfluencers();
  toast(editIdx !== '' ? 'تم التعديل' : 'تمت الإضافة', 'success');
}

// حذف شخصية
function deleteInfluencer(){
  const editIdx = document.getElementById('influencer-edit-idx').value;
  if(editIdx === '') return;
  const i = parseInt(editIdx);
  const list = getInfluencers();
  if(!list[i]) return;
  if(!confirm('حذف "'+list[i].name+'" نهائيا؟')) return;
  localStorage.removeItem('influencer_img_' + list[i].id);
  list.splice(i, 1);
  saveInfluencers(list);
  closeInfluencerEditor();
  loadInfluencers();
  toast('تم الحذف', 'info');
}

function closeInfluencerEditor(){
  const modal = document.getElementById('influencer-editor');
  if(modal) modal.style.display = 'none';
  // مسح البيانات المؤقتة
  const preview = document.getElementById('influencer-img-preview');
  if(preview){ delete preview.dataset.newImg; delete preview.dataset.removeImg; }
  const fileInput = document.getElementById('influencer-img-input');
  if(fileInput) fileInput.value = '';
}

// ═══ حذف شخصية مباشرة من البطاقة (للأدمن) ═══
function deleteInfluencerDirect(idx){
  if(!isAdminUser(currentUser)){ toast('للأدمن فقط', 'warn'); return; }
  const list = getInfluencers();
  if(!list[idx]) return;
  if(!confirm('حذف "'+list[idx].name+'" نهائيا؟ لا يمكن التراجع.')) return;
  localStorage.removeItem('influencer_img_' + list[idx].id);
  const name = list[idx].name;
  list.splice(idx, 1);
  saveInfluencers(list);
  loadInfluencers();
  toast('تم حذف "'+name+'"', 'info');
}

// تعريف الدوال في النطاق العام
window.openInfluencerEditor = openInfluencerEditor;
window.closeInfluencerEditor = closeInfluencerEditor;
window.toggleInfluencerPublish = toggleInfluencerPublish;
window.saveInfluencer = saveInfluencer;
window.deleteInfluencer = deleteInfluencer;
window.deleteInfluencerDirect = deleteInfluencerDirect;
window.loadInfluencers = loadInfluencers;
window.previewInfluencerImg = (typeof previewInfluencerImg === 'function') ? previewInfluencerImg : window.previewInfluencerImg;
window.removeInfluencerImg = (typeof removeInfluencerImg === 'function') ? removeInfluencerImg : window.removeInfluencerImg;
// ═══════════════ نهاية شخصيات مؤثرة ═══════════════


// ════ إدارة الأسئلة من لوحة التحكم ════
let _aqCurrentDiff = 'easy';
let _aqCurrentCat = '';

function setAQDiff(d){
  _aqCurrentDiff = d;
  ['easy','med','hard','elite','legend'].forEach(x=>{
    const btn = document.getElementById('aq-diff-'+x);
    if(btn){ btn.style.background = x===d?'#8A1538':'#fff'; btn.style.color = x===d?'#fff':'#8A1538'; }
  });
}

function populateAQCatSelect(){
  const sel = document.getElementById('aq-cat-select');
  if(!sel) return;
  //  ضمان أسئلة الشركاء في QDB قبل بناء القائمة (وإلا تغيب فئاتها من «اختر فئة»)
  try{
    if(typeof _HH_PARTNER_QUESTIONS === 'object' && _HH_PARTNER_QUESTIONS){
      for(var _pcB in _HH_PARTNER_QUESTIONS){
        if(!Array.isArray(QDB[_pcB]) || QDB[_pcB].length === 0){
          QDB[_pcB] = JSON.parse(JSON.stringify(_HH_PARTNER_QUESTIONS[_pcB]));
        }
      }
    }
  }catch(_eB){}
  sel.innerHTML = '<option value="">-- اختر فئة --</option>';
  // الشريك المقيّد يرى فئاته فقط؛ الأدمن يرى كل الفئات
  let allowed = null;
  try{
    if(typeof _hhIsRestrictedPartner === 'function' && _hhIsRestrictedPartner()){
      allowed = new Set(_hhGetPartnerEditableCats(currentUser && currentUser.email));
    }
  }catch(e){}
  Object.keys(QDB).sort().forEach(cat=>{
    if(allowed && !allowed.has(cat)) return; // نُخفي فئات غير مخصصة للشريك
    const opt = document.createElement('option');
    opt.value = cat; opt.textContent = cat;
    sel.appendChild(opt);
  });
}

// ═══════════════════════════════════════════════════════════
// إنشاء فئة جديدة من لوحة التحكم
// ═══════════════════════════════════════════════════════════
function hhOpenNewCategoryModal(){
  // نبني قائمة المجموعات المتاحة + خيار إنشاء جديد
  let groupOptions = '';
  if(typeof CAT_GROUPS !== 'undefined'){
    CAT_GROUPS.forEach(g => {
      if(g.id.includes('_soon')) return;
      groupOptions += `<option value="${g.id}">${g.label}</option>`;
    });
  }
  groupOptions += `<option value="__new__" style="font-weight:900;color:#8A1538;background:#F7EBEE;">+ إنشاء مجموعة جديدة</option>`;

  // ألوان مقترحة احترافية (بدون فاقع)
  const suggestedColors = [
    {label:'عنابي',c:'#8A1538'},
    {label:'عنابي داكن',c:'#5E0E26'},
    {label:'ذهبي مطفي',c:'#B8924A'},
    {label:'كحلي',c:'#1F4E79'},
    {label:'أخضر هادئ',c:'#3D6B53'},
    {label:'بنفسجي رصين',c:'#3D4A7A'},
    {label:'بني فاخر',c:'#A67C4A'}
  ];
  const colorBtns = suggestedColors.map(co => `<button type="button" onclick="document.getElementById('hh-newcat-color').value='${co.c}';document.getElementById('hh-newcat-color-preview').style.background='${co.c}';return false;" title="${co.label}" style="width:34px;height:34px;background:${co.c};border:2px solid #fff;border-radius:50%;cursor:pointer;box-shadow:0 2px 6px rgba(0,0,0,.15);"></button>`
  ).join('');

  const modal = document.createElement('div');
  modal.id = 'hh-newcat-modal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(43,11,30,.65);backdrop-filter:blur(4px);z-index:99999;display:flex;align-items:center;justify-content:center;padding:16px;';
  modal.innerHTML = `
    <div style="background:#fff;border-radius:16px;max-width:520px;width:100%;max-height:90vh;overflow-y:auto;box-shadow:0 20px 60px rgba(0,0,0,.4);border:2px solid #8A1538;">
      <!-- header -->
      <div style="background:linear-gradient(135deg,#8A1538,#5E0E26);color:#fff;padding:16px 20px;border-radius:14px 14px 0 0;display:flex;justify-content:space-between;align-items:center;">
        <div style="font-family:Cairo,sans-serif;font-weight:900;font-size:1.05rem;">إنشاء فئة جديدة</div>
        <button onclick="hhCloseNewCategoryModal()" style="background:rgba(255,255,255,.15);border:none;color:#fff;width:30px;height:30px;border-radius:50%;cursor:pointer;font-size:1.1rem;font-weight:900;">✕</button>
      </div>

      <!-- body -->
      <div style="padding:20px;font-family:Tajawal,sans-serif;">
        
        <!-- اسم الفئة -->
        <div style="margin-bottom:14px;">
          <label style="font-family:Cairo;font-weight:800;font-size:.85rem;color:#8A1538;display:block;margin-bottom:6px;">اسم الفئة <span style="color:#c0392b;">*</span></label>
          <input id="hh-newcat-name" type="text" placeholder="مثال: التاريخ الإسلامي" 
            style="width:100%;padding:11px;border:1.5px solid #B8924A;border-radius:8px;font-family:Tajawal;font-size:.92rem;outline:none;" autocomplete="off">
          <div style="font-size:.7rem;color:#8A6D2E;margin-top:4px;">سيظهر هذا الاسم في قائمة الفئات</div>
        </div>

        <!-- المجموعة -->
        <div style="margin-bottom:14px;">
          <label style="font-family:Cairo;font-weight:800;font-size:.85rem;color:#8A1538;display:block;margin-bottom:6px;">المجموعة <span style="color:#c0392b;">*</span></label>
          <select id="hh-newcat-group" onchange="hhHandleGroupChange(this)" style="width:100%;padding:11px;border:1.5px solid #B8924A;border-radius:8px;font-family:Cairo,sans-serif;font-size:.9rem;background:#fff;">
            <option value="">-- اختر المجموعة --</option> ${groupOptions}
          </select>
          <div style="font-size:.7rem;color:#8A6D2E;margin-top:4px;">المجموعة تحدد أين ستظهر الفئة في القائمة</div>

          <!-- نموذج إنشاء مجموعة جديدة (يظهر عند اختيار "+ إنشاء مجموعة") -->
          <div id="hh-newgroup-form" style="display:none;margin-top:10px;padding:12px;background:#F7EBEE;border:1.5px dashed #8A1538;border-radius:10px;">
            <label style="font-family:Cairo;font-weight:800;font-size:.78rem;color:#5E0E26;display:block;margin-bottom:5px;">اسم المجموعة الجديدة</label>
            <input id="hh-newgroup-name" type="text" placeholder="مثال: التراث والفنون"
              style="width:100%;padding:9px;border:1.5px solid #8A1538;border-radius:8px;font-family:Tajawal;font-size:.9rem;outline:none;background:#fff;" autocomplete="off">
            <div style="font-size:.68rem;color:#8A1538;margin-top:5px;">ستصبح مجموعة جديدة في قائمة الفئات تحتوي على هذه الفئة وأي فئات تُنشئها لاحقاً</div>
          </div>
        </div>

        <!-- اللون -->
        <div style="margin-bottom:14px;">
          <label style="font-family:Cairo;font-weight:800;font-size:.85rem;color:#8A1538;display:block;margin-bottom:6px;">لون الفئة</label>
          <div style="display:flex;align-items:center;gap:10px;">
            <input id="hh-newcat-color" type="text" value="#8A1538" 
              style="flex:1;padding:11px;border:1.5px solid #B8924A;border-radius:8px;font-family:monospace;font-size:.92rem;outline:none;">
            <div id="hh-newcat-color-preview" style="width:44px;height:44px;background:#8A1538;border:2px solid #fff;border-radius:8px;box-shadow:0 2px 8px rgba(0,0,0,.15);"></div>
          </div>
          <div style="margin-top:8px;display:flex;flex-wrap:wrap;gap:6px;"> ${colorBtns}
          </div>
        </div>

        <!-- الوصف -->
        <div style="margin-bottom:18px;">
          <label style="font-family:Cairo;font-weight:800;font-size:.85rem;color:#8A1538;display:block;margin-bottom:6px;">وصف مختصر (اختياري)</label>
          <input id="hh-newcat-desc" type="text" placeholder="وصف يظهر تحت اسم الفئة" 
            style="width:100%;padding:11px;border:1.5px solid #B8924A;border-radius:8px;font-family:Tajawal;font-size:.88rem;outline:none;">
        </div>

        <!-- الأزرار -->
        <div style="display:flex;gap:10px;">
          <button onclick="hhCloseNewCategoryModal()" 
            style="flex:1;padding:12px;background:#fff;color:#8A1538;border:1.5px solid #8A1538;border-radius:10px;font-family:Cairo;font-weight:900;font-size:.92rem;cursor:pointer;"> إلغاء
          </button>
          <button onclick="hhCreateNewCategory()" 
            style="flex:2;padding:12px;background:linear-gradient(135deg,#8A1538,#5E0E26);color:#fff;border:none;border-radius:10px;font-family:Cairo;font-weight:900;font-size:.92rem;cursor:pointer;box-shadow:0 4px 12px rgba(138,21,56,.3);display:inline-flex;align-items:center;justify-content:center;gap:6px;">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor"><path d="M19 13h-6v6h-2v-6H5v-2h6V5h2v6h6v2z"/></svg> إنشاء الفئة
          </button>
        </div>

      </div>
    </div> `;
  document.body.appendChild(modal);

  modal.addEventListener('click', (e) => {
    if(e.target === modal) hhCloseNewCategoryModal();
  });

  setTimeout(() => {
    const nameInput = document.getElementById('hh-newcat-name');
    if(nameInput) nameInput.focus();
  }, 100);

  setTimeout(() => {
    const colorInput = document.getElementById('hh-newcat-color');
    if(colorInput){
      colorInput.oninput = () => {
        const preview = document.getElementById('hh-newcat-color-preview');
        if(preview) preview.style.background = colorInput.value;
      };
    }
  }, 100);
}

// معالجة تغيير المجموعة (إظهار نموذج إنشاء مجموعة جديدة)
function hhHandleGroupChange(sel){
  const form = document.getElementById('hh-newgroup-form');
  if(!form) return;
  if(sel.value === '__new__'){
    form.style.display = 'block';
    setTimeout(() => {
      const input = document.getElementById('hh-newgroup-name');
      if(input) input.focus();
    }, 50);
  } else {
    form.style.display = 'none';
  }
}

function hhCloseNewCategoryModal(){
  const modal = document.getElementById('hh-newcat-modal');
  if(modal) modal.remove();
}

//  حذف فئة مخصصة (للفئات التي أنشأها الأدمن فقط)
async function hhDeleteCurrentCategory(){
  const cat = _aqCurrentCat;
  if(!cat){
    if(typeof toast === 'function') toast('اختر فئة أولاً', 'error');
    return;
  }

  // التحقق: هل هذه فئة مخصصة (في hh_custom_cats)؟
  let customCats = {};
  try{ customCats = JSON.parse(localStorage.getItem('hh_custom_cats') || '{}'); }catch(e){}
  
  if(!customCats[cat]){
    if(typeof toast === 'function') toast('لا يمكن حذف الفئات الأصلية · فقط الفئات التي أنشأتها', 'error');
    return;
  }

  // تأكيد الحذف
  const confirmMsg = `هل أنت متأكد من حذف فئة "${cat}"؟\n\nسيتم حذف:\n• الفئة من القائمة\n• جميع أسئلتها (${(QDB[cat]||[]).length} سؤال)\n\nهذا الإجراء لا يمكن التراجع عنه!`;
  if(!confirm(confirmMsg)) return;

  try{
    // 1) حذف من QDB
    if(QDB[cat]) delete QDB[cat];

    // 2) حذف من CAT_INFO
    if(typeof CAT_INFO !== 'undefined' && CAT_INFO[cat]) delete CAT_INFO[cat];

    // 3) حذف من CAT_GROUPS
    if(typeof CAT_GROUPS !== 'undefined'){
      CAT_GROUPS.forEach(g => {
        if(Array.isArray(g.cats)){
          g.cats = g.cats.filter(c => c !== cat);
        }
      });
    }

    // 4) حذف من localStorage
    delete customCats[cat];
    localStorage.setItem('hh_custom_cats', JSON.stringify(customCats));
    if(typeof _hh_saveCustomizationsToCloud === 'function') _hh_saveCustomizationsToCloud();

    // 5) حذف من Firestore
    if(typeof db !== 'undefined' && db){
      try{
        await db.collection('admin_qdb').doc(cat).delete();
      }catch(e){
        console.warn('حذف السحابي تعذر:', e);
      }
    }

    // 6) إعادة بناء الواجهة
    _aqCurrentCat = '';
    if(typeof populateAQCatSelect === 'function') populateAQCatSelect();
    if(typeof buildCatSelect === 'function') buildCatSelect();
    
    // مسح قائمة الأسئلة المعروضة
    const listEl = document.getElementById('aq-questions-list');
    if(listEl) listEl.innerHTML = '';
    const filterWrap = document.getElementById('aq-filter-wrap');
    if(filterWrap) filterWrap.style.display = 'none';

    if(typeof toast === 'function') toast(' تم حذف فئة "' + cat + '"', 'success');

  }catch(e){
    console.error('خطأ في حذف الفئة:', e);
    if(typeof toast === 'function') toast('تعذر الحذف: ' + e.message, 'error');
  }
}

async function hhCreateNewCategory(){
  const name = (document.getElementById('hh-newcat-name')?.value || '').trim();
  let groupId = document.getElementById('hh-newcat-group')?.value || '';
  const color = (document.getElementById('hh-newcat-color')?.value || '#8A1538').trim();
  const desc = (document.getElementById('hh-newcat-desc')?.value || '').trim();

  // التحقق من اسم الفئة
  if(!name){
    if(typeof toast === 'function') toast('يجب إدخال اسم الفئة', 'error');
    document.getElementById('hh-newcat-name')?.focus();
    return;
  }
  if(!groupId){
    if(typeof toast === 'function') toast('يجب اختيار المجموعة', 'error');
    document.getElementById('hh-newcat-group')?.focus();
    return;
  }

  // إذا اختار "إنشاء مجموعة جديدة"
  if(groupId === '__new__'){
    const newGroupName = (document.getElementById('hh-newgroup-name')?.value || '').trim();
    if(!newGroupName){
      if(typeof toast === 'function') toast('يجب إدخال اسم المجموعة الجديدة', 'error');
      document.getElementById('hh-newgroup-name')?.focus();
      return;
    }
    // ننشئ ID للمجموعة (بسيط من الاسم)
    const newGroupId = 'custom_' + Date.now();
    
    if(typeof CAT_GROUPS !== 'undefined'){
      // التحقق من عدم وجود مجموعة بنفس الاسم
      if(CAT_GROUPS.some(g => g.label === newGroupName)){
        if(typeof toast === 'function') toast('هذه المجموعة موجودة بالفعل', 'error');
        return;
      }
      // نضيف المجموعة الجديدة
      CAT_GROUPS.push({
        id: newGroupId,
        label: newGroupName,
        icon: `<svg viewBox="0 0 100 100" width="36" height="36" xmlns="http://www.w3.org/2000/svg"><rect width="100" height="100" rx="14" fill="${color}"/><text x="50" y="62" text-anchor="middle" font-size="40" font-family="Cairo,Arial" fill="#fff" font-weight="900">${newGroupName.charAt(0)}</text></svg>`,
        cats: []
      });
      
      // نضيف المجموعة لمستوى "العامة" تلقائياً
      if(typeof CAT_LEVELS !== 'undefined'){
        const generalLevel = CAT_LEVELS.find(l => l.id === 'general');
        if(generalLevel && !generalLevel.groupIds.includes(newGroupId)){
          generalLevel.groupIds.push(newGroupId);
        }
      }
      
      // حفظ المجموعة المخصصة في localStorage
      try{
        const customGroups = JSON.parse(localStorage.getItem('hh_custom_groups') || '{}');
        customGroups[newGroupId] = { label: newGroupName, color: color };
        localStorage.setItem('hh_custom_groups', JSON.stringify(customGroups));
        if(typeof _hh_saveCustomizationsToCloud === 'function') _hh_saveCustomizationsToCloud();
      }catch(e){}
      
      // حفظ المجموعة المخصصة في Firestore (لتظهر لكل المستخدمين)
      if(typeof db !== 'undefined' && db){
        try{
          await db.collection('platform_settings').doc('custom_groups').set({
            [newGroupId]: {
              label: newGroupName,
              color: color,
              createdAt: firebase.firestore.FieldValue.serverTimestamp(),
              createdBy: currentUser ? (currentUser.email || currentUser.uid) : 'admin' }
          }, { merge: true });
        }catch(e){ console.warn('حفظ المجموعة سحابياً تعذر:', e); }
      }
      
      groupId = newGroupId;
    }
  }

  // التحقق من عدم وجود فئة بنفس الاسم
  if(QDB[name] || (typeof CAT_INFO !== 'undefined' && CAT_INFO[name])){
    if(typeof toast === 'function') toast('هذه الفئة موجودة بالفعل', 'error');
    return;
  }

  try{
    // 1) إضافة الفئة لـ QDB (فارغة)
    QDB[name] = [];

    // 2) إضافة الفئة لـ CAT_INFO (بدون إيموجي)
    if(typeof CAT_INFO !== 'undefined'){
      const bgColor = color + '15';
      CAT_INFO[name] = {
        emoji:'',
        label: name,
        color: color,
        bg: bgColor
      };
    }

    // 3) إضافة الفئة للمجموعة المختارة
    if(typeof CAT_GROUPS !== 'undefined'){
      const grp = CAT_GROUPS.find(g => g.id === groupId);
      if(grp && Array.isArray(grp.cats)){
        if(!grp.cats.includes(name)){
          grp.cats.push(name);
        }
      }
    }

    // 4) حفظ في Firestore
    if(typeof db !== 'undefined' && db && typeof currentUser !== 'undefined' && currentUser){
      try{
        await db.collection('admin_qdb').doc(name).set({
          questions: [],
          meta: {
            color: color,
            bg: color + '15',
            groupId: groupId,
            desc: desc,
            createdAt: firebase.firestore.FieldValue.serverTimestamp(),
            createdBy: currentUser.email || currentUser.uid
          }
        }, { merge: true });
      }catch(e){
        console.warn('حفظ السحابي تعذر:', e);
      }
    }

    // 5) حفظ محلي
    try{
      const customCats = JSON.parse(localStorage.getItem('hh_custom_cats') || '{}');
      customCats[name] = {
        color: color,
        bg: color + '15',
        groupId: groupId,
        desc: desc
      };
      localStorage.setItem('hh_custom_cats', JSON.stringify(customCats));
      if(typeof _hh_saveCustomizationsToCloud === 'function') _hh_saveCustomizationsToCloud();
    }catch(e){}

    // 6) إعادة بناء الواجهة (إجبار كامل)
    if(typeof populateAQCatSelect === 'function') populateAQCatSelect();
    // إعادة بناء شاشة اختيار الفئات (لو كان المستخدم فيها)
    if(typeof buildCatSelect === 'function'){
      try{ buildCatSelect(); }catch(e){ console.warn(e); }
    }
    // مسح أي كاش للفئات
    try{ localStorage.removeItem('hh_saved_cats'); }catch(e){}

    // 7) اختيار الفئة الجديدة
    setTimeout(() => {
      const sel = document.getElementById('aq-cat-select');
      if(sel){
        sel.value = name;
        if(typeof loadAdminCatQuestions === 'function') loadAdminCatQuestions();
      }
    }, 100);

    // إغلاق النموذج
    hhCloseNewCategoryModal();

    // رسالة نجاح
    if(typeof toast === 'function'){
      toast('تم إنشاء فئة "' + name + '" بنجاح! ابدأ بإضافة الأسئلة', 'success');
    }
    // تتبع الإنجازات
    if(window.hhTrackActivity) hhTrackActivity('new_category');

  }catch(e){
    console.error('خطأ في إنشاء الفئة:', e);
    if(typeof toast === 'function') toast('تعذر إنشاء الفئة: ' + e.message, 'error');
  }
}

function loadAdminCatQuestions(){
  const cat = document.getElementById('aq-cat-select').value;
  _aqCurrentCat = cat;
  const listEl = document.getElementById('aq-questions-list');
  const formEl = document.getElementById('aq-add-form');
  const filterWrap = document.getElementById('aq-filter-wrap');
  if(!cat){ listEl.innerHTML=''; formEl.style.display='none'; if(filterWrap)filterWrap.style.display='none'; return; }
  if(filterWrap){ filterWrap.style.display='block'; document.getElementById('aq-filter').value=''; }
  // نمرر مع origIdx ليعرف الزر أي سؤال يعدل
  const all = QDB[cat] || [];
  renderQuestionsList(all.map((q,idx)=>({q_obj:q, origIdx:idx})), cat);
}

// عرض قائمة الأسئلة (يستخدم من loadAdminCatQuestions و filterCurrentCategory)
function renderQuestionsList(qs, cat, highlight){
  const listEl = document.getElementById('aq-questions-list');
  const diffLabels = {easy:'سهل 200', med:'متوسط 400', hard:'صعب 600', elite:'نخبة 800', legend:'أسطوري 1000'};
  const diffColors = {easy:'#3D6B53', med:'#8A6D2E', hard:'#8A1538', elite:'#5E0E26', legend:'#2A0810'};
  // دالة لتلوين الكلمة المبحوث عنها
  const hl = (text) => {
    if(!highlight) return esc(text);
    try{
      const safe = highlight.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
      const re = new RegExp('('+safe+')', 'gi');
      return esc(text).replace(re, '<mark style="background:#fff3a8;color:#8A6D2E;padding:0 2px;border-radius:3px;">$1</mark>');
    }catch(e){ return esc(text); }
  };
  listEl.innerHTML = qs.length ? qs.map(item=>{
    const q = item.q_obj || item;
    const i = (item.origIdx !== undefined) ? item.origIdx : item.idx;
    const imgThumb = q.img ? `<img src="${q.img}" style="width:40px;height:40px;object-fit:cover;border-radius:6px;border:1.5px solid #B8924A;flex-shrink:0;cursor:pointer;" onclick="hhPreviewImg('${q.img}')" title="انقر لعرض الصورة كاملة">` : '';
    return `
    <div style="background:#fff;border:1.5px solid #e0e8f0;border-radius:10px;padding:10px 12px;margin-bottom:8px;display:flex;align-items:flex-start;gap:8px;">
      <span style="font-size:.68rem;font-weight:900;color:${diffColors[q.diff]||'#555'};background:#f0f4f8;border-radius:6px;padding:2px 7px;flex-shrink:0;margin-top:2px;">${diffLabels[q.diff]||q.diff}</span>${(function(){ try{ var _sb=_hhAQSubsFor(cat); if(_sb && q.sub!==undefined && _sb[q.sub]) return '<span style="font-size:.66rem;font-weight:800;color:#8A6D2E;background:#FDF3DD;border:1px solid #EAD9B0;border-radius:6px;padding:2px 7px;flex-shrink:0;margin-top:2px;">'+esc(_sb[q.sub].label||'')+'</span>'; }catch(e){} return ''; })()} ${imgThumb}
      <div style="flex:1;min-width:0;">
        <div style="font-size:.82rem;font-weight:700;color:#1a1a2e;margin-bottom:3px;">${hl(q.q)} ${q.img?'<span style="font-size:.65rem;color:#B8924A;font-weight:700;"></span>':''}</div>
        <div style="font-size:.75rem;color:#3D6B53;">✓ ${hl(q.a)}</div>
      </div>
      <div style="display:flex;gap:4px;flex-shrink:0;">
        <button onclick="editAdminQuestion(${i})" style="padding:4px 8px;background:#e8f2ec;border:1.5px solid #8A1538;border-radius:6px;font-family:Cairo;font-size:.72rem;font-weight:700;color:#8A1538;cursor:pointer;">تعديل</button>
        <button onclick="deleteAdminQuestion(${i})" style="padding:4px 8px;background:#fde8e8;border:1.5px solid #c0392b;border-radius:6px;font-family:Cairo;font-size:.72rem;font-weight:700;color:#c0392b;cursor:pointer;">حذف</button>
      </div>
    </div>`;
  }).join('') : '<p style="text-align:center;color:#aaa;padding:20px;">لا توجد أسئلة مطابقة</p>';
}

// معاينة الصورة بحجم كامل
function hhPreviewImg(src){
  const overlay = document.createElement('div');
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.9);z-index:99999;display:flex;align-items:center;justify-content:center;cursor:zoom-out;padding:20px;';
  overlay.innerHTML = `<img src="${src}" style="max-width:100%;max-height:100%;border-radius:10px;box-shadow:0 10px 40px rgba(0,0,0,.5);">`;
  overlay.onclick = () => overlay.remove();
  document.body.appendChild(overlay);
}

// فلترة داخل الفئة المختارة
function filterCurrentCategory(){
  if(!_aqCurrentCat) return;
  const term = (document.getElementById('aq-filter').value||'').trim().toLowerCase();
  const all = QDB[_aqCurrentCat] || [];
  const countEl = document.getElementById('aq-filter-count');
  if(!term){
    renderQuestionsList(all.map((q,idx)=>({q_obj:q, origIdx:idx})), _aqCurrentCat);
    if(countEl) countEl.textContent = `${all.length} سؤال`;
    return;
  }
  const filtered = all.map((q,idx)=>({q_obj:q, origIdx:idx}))
    .filter(item => (item.q_obj.q||'').toLowerCase().includes(term) || (item.q_obj.a||'').toLowerCase().includes(term));
  renderQuestionsList(filtered, _aqCurrentCat, term);
  if(countEl) countEl.textContent = `${filtered.length} من ${all.length}`;
}

//  بحث شامل عبر كل الفئات
function globalSearchQuestions(){
  const term = (document.getElementById('aq-global-search').value||'').trim().toLowerCase();
  const resultsEl = document.getElementById('aq-global-results');
  if(!term){ resultsEl.innerHTML = ''; return; }
  if(term.length < 2){ resultsEl.innerHTML = '<div style="font-size:.75rem;color:#888;padding:6px;">اكتب حرفين على الأقل...</div>'; return; }
  const results = [];
  const catNames = Object.keys(QDB);
  catNames.forEach(cat=>{
    const arr = QDB[cat] || [];
    arr.forEach((q,idx)=>{
      if((q.q||'').toLowerCase().includes(term) || (q.a||'').toLowerCase().includes(term)){
        results.push({cat, idx, q});
      }
    });
  });
  const diffLabels = {easy:'س', med:'م', hard:'ص'};
  const diffColors = {easy:'#1a5fa8', med:'#b86a00', hard:'#b01c1c', elite:'#5E0E26'};
  // تمييز الكلمة
  const hl = (text) => {
    try{
      const safe = term.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
      const re = new RegExp('('+safe+')', 'gi');
      return esc(text).replace(re, '<mark style="background:#fff3a8;color:#8A6D2E;padding:0 2px;border-radius:3px;">$1</mark>');
    }catch(e){ return esc(text); }
  };
  if(!results.length){
    resultsEl.innerHTML = `<div style="font-size:.8rem;color:#888;padding:10px;text-align:center;background:#fafafa;border-radius:8px;">لا نتائج مطابقة لـ "<strong>${esc(term)}</strong>"</div>`;
    return;
  }
  // عرض عداد + النتائج
  const header = `<div style="font-size:.78rem;font-weight:900;color:#8A1538;margin-bottom:8px;background:#e8f2ec;padding:6px 10px;border-radius:6px;">
    <svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M12 2a10 10 0 100 20 10 10 0 000-20zm0 18a8 8 0 110-16 8 8 0 010 16zm0-14a6 6 0 100 12 6 6 0 000-12zm0 10a4 4 0 110-8 4 4 0 010 8zm0-6a2 2 0 100 4 2 2 0 000-4z"/></svg> ${results.length} نتيجة في ${new Set(results.map(r=>r.cat)).size} فئة
  </div>`;
  // تحديد أقصى 30 نتيجة لتجنب الإبطاء
  const maxDisplay = 30;
  const shown = results.slice(0, maxDisplay);
  const more = results.length > maxDisplay ? `<div style="text-align:center;font-size:.72rem;color:#888;padding:6px;">عرض أول ${maxDisplay} من ${results.length} · ضع كلمة أدق للتصفية</div>` : '';
  resultsEl.innerHTML = header + shown.map(r=>`
    <div style="background:#fff;border:1.5px solid #e0e8f0;border-radius:8px;padding:8px 10px;margin-bottom:6px;">
      <div style="display:flex;align-items:center;gap:6px;margin-bottom:4px;">
        <span style="font-size:.62rem;font-weight:900;color:${diffColors[r.q.diff]||'#555'};background:#f0f4f8;border-radius:4px;padding:1px 5px;">${diffLabels[r.q.diff]||r.q.diff}</span>
        <span style="font-size:.7rem;font-weight:700;color:#8A1538;background:#e8f2ec;padding:2px 7px;border-radius:10px;">${esc(r.cat)}</span>
      </div>
      <div style="font-size:.78rem;font-weight:700;color:#1a1a2e;margin-bottom:2px;">${hl(r.q.q)}</div>
      <div style="font-size:.72rem;color:#3D6B53;margin-bottom:6px;">✓ ${hl(r.q.a)}</div>
      <div style="display:flex;gap:4px;">
        <button onclick="jumpToEditQuestion('${esc(r.cat).replace(/'/g,"\\'")}',${r.idx})"
          style="flex:1;padding:4px 6px;background:#e8f2ec;border:1.5px solid #8A1538;border-radius:5px;font-family:Cairo;font-size:.7rem;font-weight:700;color:#8A1538;cursor:pointer;">تعديل</button>
        <button onclick="jumpToDeleteQuestion('${esc(r.cat).replace(/'/g,"\\'")}',${r.idx})"
          style="padding:4px 10px;background:#fde8e8;border:1.5px solid #c0392b;border-radius:5px;font-family:Cairo;font-size:.7rem;font-weight:700;color:#c0392b;cursor:pointer;">حذف</button>
      </div>
    </div> `).join('') + more;
}

// الانتقال لتعديل سؤال من نتائج البحث الشامل
function jumpToEditQuestion(cat, idx){
  document.getElementById('aq-cat-select').value = cat;
  loadAdminCatQuestions();
  setTimeout(()=>{
    editAdminQuestion(idx);
    // قم بالتمرير إلى نموذج التعديل
    const form = document.getElementById('aq-add-form');
    if(form) form.scrollIntoView({behavior:'smooth', block:'center'});
  }, 100);
}

// الحذف مباشرة من نتائج البحث الشامل
function jumpToDeleteQuestion(cat, idx){
  const q = (QDB[cat]||[])[idx];
  if(!q) return;
  if(!confirm('حذف هذا السؤال من فئة "'+cat+'"؟\n\n"'+q.q+'"')) return;
  QDB[cat].splice(idx, 1);
  saveAdminQuestion_persist(cat);
  toast('تم حذف السؤال من '+cat, 'info');
  // إعادة البحث لتحديث النتائج
  globalSearchQuestions();
  // إذا كانت الفئة المختارة حاليا، حدثها
  if(_aqCurrentCat === cat){
    loadAdminCatQuestions();
  }
}

function showAQAddForm(){
  document.getElementById('aq-edit-idx').value = '';
  document.getElementById('aq-question-text').value = '';
  document.getElementById('aq-answer-text').value = '';
  document.getElementById('aq-image-data').value = '';
  hhRemoveQuestionImage();
  setAQDiff('easy');
  document.getElementById('aq-add-form').style.display = 'block';
  document.getElementById('aq-question-text').focus();
}


// ═══ رفع صورة سؤال إلى Firebase Storage · يعيد رابط التحميل أو null ═══
async function hhUploadQImageToStorage(dataUrl){
  if(typeof firebase === 'undefined' || !firebase.storage) return null;
  if(typeof OFFLINE_MODE !== 'undefined' && OFFLINE_MODE) return null;
  const uid = (typeof currentUser !== 'undefined' && currentUser) ? currentUser.uid : 'anon';
  const path = 'question_images/' + uid + '_' + Date.now() + '.jpg';
  const ref = firebase.storage().ref(path);
  const snap = await ref.putString(dataUrl, 'data_url');
  return await snap.ref.getDownloadURL();
}

// معالجة رفع الصورة (مع ضغط تلقائي)
async function hhHandleImageUpload(event){
  const file = event.target.files[0];
  if(!file) return;
  
  // التحقق من النوع
  if(!file.type.startsWith('image/')){
    if(typeof toast === 'function') toast('يرجى اختيار ملف صورة', 'error');
    return;
  }
  
  // التحقق من الحجم (max 10MB قبل الضغط)
  if(file.size > 10 * 1024 * 1024){
    if(typeof toast === 'function') toast('حجم الصورة كبير جداً (الحد الأقصى 10MB)', 'error');
    return;
  }
  
  if(typeof toast === 'function') toast('جاري معالجة الصورة...', 'info');
  
  try{
    // ضغط الصورة وتحويلها لـ Base64
    // ضغط تكيّفي: نبدأ بجودة عالية ونشدّ إن كانت النتيجة ثقيلة (حماية حد المزامنة)
    let compressed = await hhCompressImage(file, 1000, 0.75);
    if(compressed.length > 220*1024){ compressed = await hhCompressImage(file, 800, 0.62); }
    if(compressed.length > 220*1024){ compressed = await hhCompressImage(file, 640, 0.55); }
    
    // ═══ الرفع إلى Firebase Storage أولاً (يُحفظ الرابط الصغير بدل base64) ═══
    let finalImg = compressed, viaStorage = false;
    try{
      const url = await hhUploadQImageToStorage(compressed);
      if(url){ finalImg = url; viaStorage = true; }
    }catch(eSt){ console.warn('Storage غير متاح، الإبقاء على base64:', eSt && eSt.message); }

    // عرض المعاينة
    document.getElementById('aq-image-data').value = finalImg;
    document.getElementById('aq-image-preview').src = finalImg;
    document.getElementById('aq-image-preview-wrap').style.display = 'block';
    document.getElementById('aq-image-upload-btn').style.display = 'none';
    
    // عرض الحجم
    const sizeKB = Math.round(compressed.length * 0.75 / 1024);
    document.getElementById('aq-image-size').textContent = viaStorage ? ('✓ Storage · '+sizeKB+' KB') : (sizeKB + ' KB');
    
    if(typeof toast === 'function') toast(viaStorage ? 'رُفعت الصورة إلى Storage · حُفظ الرابط فقط' : 'تم حفظ الصورة (مضغوطة محلياً · فعّل Storage للأفضل)', 'success');
  }catch(e){
    console.error('خطأ في معالجة الصورة:', e);
    if(typeof toast === 'function') toast('تعذرت معالجة الصورة: ' + e.message, 'error');
  }
  
  // مسح القيمة لإمكان رفع نفس الصورة مرة أخرى
  event.target.value = '';
}

//  ضغط الصورة لتقليل حجمها
function hhCompressImage(file, maxDim = 1000, quality = 0.75){
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        // حساب الأبعاد الجديدة (الحفاظ على النسبة)
        let width = img.width;
        let height = img.height;
        
        if(width > maxDim || height > maxDim){
          if(width > height){
            height = Math.round(height * (maxDim / width));
            width = maxDim;
          } else {
            width = Math.round(width * (maxDim / height));
            height = maxDim;
          }
        }
        
        // رسم على canvas
        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        ctx.fillStyle = '#fff';
        ctx.fillRect(0, 0, width, height);
        ctx.drawImage(img, 0, 0, width, height);
        
        // تحويل إلى JPEG (أصغر حجماً من PNG)
        const dataUrl = canvas.toDataURL('image/jpeg', quality);
        resolve(dataUrl);
      };
      img.onerror = () => reject(new Error('فشل تحميل الصورة'));
      img.src = e.target.result;
    };
    reader.onerror = () => reject(new Error('فشل قراءة الملف'));
    reader.readAsDataURL(file);
  });
}

// إزالة الصورة
function hhRemoveQuestionImage(){
  document.getElementById('aq-image-data').value = '';
  document.getElementById('aq-image-preview').src = '';
  document.getElementById('aq-image-preview-wrap').style.display = 'none';
  document.getElementById('aq-image-upload-btn').style.display = 'inline-flex';
  const sz = document.getElementById('aq-image-size');
  if(sz) sz.textContent = '';
}

// إلغاء النموذج
function hhCancelAQForm(){
  document.getElementById('aq-add-form').style.display = 'none';
  hhRemoveQuestionImage();
}

