let _aiGeneratedQuestions = [];

async function hhAIGenerate(){
  const topic = document.getElementById('hh-ai-topic')?.value.trim();
  const count = parseInt(document.getElementById('hh-ai-count')?.value || '9');
  const style = document.getElementById('hh-ai-style')?.value || 'general';
  
  if(!topic){
    if(typeof toast === 'function') toast('اكتب الموضوع أولاً', 'warn');
    document.getElementById('hh-ai-topic')?.focus();
    return;
  }
  
  if(topic.length < 10){
    if(typeof toast === 'function') toast('الوصف قصير جداً. اكتب وصفاً أوضح', 'warn');
    return;
  }
  
  // إظهار شريط التحميل
  document.getElementById('hh-ai-buttons').style.display = 'none';
  document.getElementById('hh-ai-loading').style.display = 'block';
  document.getElementById('hh-ai-preview').style.display = 'none';
  
  const styleMap = {
    general: 'متنوعة في الصياغة، شاملة لعدة جوانب من الموضوع',
    elite: 'نخبوية ومتعمقة، تتطلب معرفة عميقة بالتفاصيل والأرقام والتواريخ الدقيقة',
    qatari: 'تركز على دولة قطر وتاريخها وثقافتها بشكل خاص، باللهجة الفصحى',
    islamic: 'دينية إسلامية، تتعلق بالقرآن والسنة والتاريخ الإسلامي',
    educational: 'مدرسية مناسبة للمنهج التعليمي القطري، واضحة ومباشرة' };
  
  const easyCount = Math.ceil(count/3);
  const medCount = Math.ceil(count/3);
  const hardCount = count - easyCount - medCount;
  
  const prompt = `أنت معلم خبير في الموضوعات التعليمية القطرية والعربية. ولّد ${count} أسئلة احترافية عن الموضوع التالي:

الموضوع: "${topic}"
الفئة: "${_aqCurrentCat}"
النمط: ${styleMap[style]}

التوزيع المطلوب:
- ${easyCount} أسئلة سهلة (easy) · للمعلومات الأساسية الواضحة
- ${medCount} أسئلة متوسطة (med) · تتطلب معرفة أعمق
- ${hardCount} أسئلة صعبة (hard) · للنخبة، تفاصيل دقيقة وأرقام محددة

قواعد صارمة:
1. كل سؤال = معلومة واحدة فقط (قاعدة 1-1-1)
2. الأسئلة قصيرة وواضحة (لا تتجاوز 15 كلمة لكل سؤال)
3. الإجابات قصيرة جداً (كلمة أو رقم أو عبارة واحدة)
4. لا تكرار بين الأسئلة
5. باللغة العربية الفصحى
6. لا تستخدم علامات الترقيم العربية مثل ؛ ، في الإجابات
7. الإجابة يجب أن تكون نهائية ودقيقة (لا "حوالي" أو "تقريباً" إلا للضرورة)

أرجع الإجابة بصيغة JSON صرف فقط (بدون أي نص آخر، بدون markdown، بدون شرح):
{
  "questions": [
    {"diff": "easy", "q": "السؤال؟", "a": "الإجابة"},
    {"diff": "med", "q": "...", "a": "..."},
    {"diff": "hard", "q": "...", "a": "..."}
  ]
}`;
  
  try{
    const response = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        model: "claude-sonnet-4-6",
        max_tokens: 3000,
        messages: [{ role: "user", content: prompt }]
      })
    });
    
    if(!response.ok){
      throw new Error('فشل الاتصال بـ API: ' + response.status);
    }
    
    const data = await response.json();
    let text = (data.content || [])
      .filter(b => b.type === 'text')
      .map(b => b.text)
      .join('\n');
    
    // تنظيف النص من markdown
    text = text.replace(/```json/g, '').replace(/```/g, '').trim();
    
    // محاولة استخراج JSON
    let parsed;
    try{
      parsed = JSON.parse(text);
    }catch(e){
      // محاولة استخراج JSON من النص
      const match = text.match(/\{[\s\S]*\}/);
      if(match) parsed = JSON.parse(match[0]);
      else throw new Error('لم يتمكن من قراءة الإجابة');
    }
    
    const questions = parsed.questions || [];
    
    if(!questions.length){
      throw new Error('لم يولّد الذكاء الاصطناعي أي أسئلة');
    }
    
    // فلترة وتنظيف
    _aiGeneratedQuestions = questions.filter(q => q.diff && q.q && q.a && 
      ['easy','med','hard'].includes(q.diff) &&
      q.q.length > 3 && q.a.length > 0
    );
    
    if(!_aiGeneratedQuestions.length){
      throw new Error('الأسئلة المولّدة غير صالحة');
    }
    
    // عرض المعاينة
    hhAIShowPreview();
    
  }catch(e){
    console.error('خطأ AI:', e);
    document.getElementById('hh-ai-loading').style.display = 'none';
    document.getElementById('hh-ai-buttons').style.display = 'flex';
    if(typeof toast === 'function') toast('' + e.message, 'error');
  }
}

function hhAIShowPreview(){
  const previewContent = document.getElementById('hh-ai-preview-content');
  const stats = { easy:0, med:0, hard:0 };
  _aiGeneratedQuestions.forEach(q => stats[q.diff]++);
  
  let html = `
    <div style="font-family:Cairo;font-weight:900;color:#8A1538;margin-bottom:10px;border-bottom:2px solid #B8924A;padding-bottom:6px;"> تم توليد ${_aiGeneratedQuestions.length} سؤال · راجعها وإن أعجبتك اضغط "قبول"
    </div>
    <div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:10px;">
      <span style="background:#3D6B53;color:#fff;padding:3px 10px;border-radius:6px;font-weight:900;font-size:.78rem;"> سهل: ${stats.easy}</span>
      <span style="background:#B8924A;color:#fff;padding:3px 10px;border-radius:6px;font-weight:900;font-size:.78rem;"> متوسط: ${stats.med}</span>
      <span style="background:#8A1538;color:#fff;padding:3px 10px;border-radius:6px;font-weight:900;font-size:.78rem;"> صعب: ${stats.hard}</span>
    </div> `;
  
  _aiGeneratedQuestions.forEach((q, i) => {
    const diffColor = q.diff === 'easy' ? '#3D6B53' : q.diff === 'med' ? '#B8924A' : '#8A1538';
    const diffLabel = q.diff === 'easy' ? 'سهل' : q.diff === 'med' ? 'متوسط' : 'صعب';
    html += `
      <div style="background:#fff;border-right:3px solid ${diffColor};padding:8px 12px;margin-bottom:6px;border-radius:6px;font-size:.85rem;">
        <div style="display:flex;justify-content:space-between;align-items:start;gap:8px;">
          <div style="flex:1;">
            <div style="color:#1a1a2e;font-weight:700;margin-bottom:3px;">${i+1}. ${escapeHTML(q.q)}</div>
            <div style="color:${diffColor};font-weight:900;">→ ${escapeHTML(q.a)}</div>
          </div>
          <span style="background:${diffColor};color:#fff;padding:1px 8px;border-radius:5px;font-size:.7rem;font-weight:900;flex-shrink:0;">${diffLabel}</span>
        </div>
      </div> `;
  });
  
  previewContent.innerHTML = html;
  document.getElementById('hh-ai-preview').style.display = 'block';
  document.getElementById('hh-ai-loading').style.display = 'none';
  document.getElementById('hh-ai-after-buttons').style.display = 'flex';
}

function escapeHTML(s){
  return String(s||'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

async function hhAIRegenerate(){
  document.getElementById('hh-ai-after-buttons').style.display = 'none';
  document.getElementById('hh-ai-preview').style.display = 'none';
  await hhAIGenerate();
}

async function hhAIAccept(){
  if(!_aiGeneratedQuestions.length){
    if(typeof toast === 'function') toast('لا توجد أسئلة للحفظ', 'warn');
    return;
  }
  
  try{
    if(!QDB[_aqCurrentCat]) QDB[_aqCurrentCat] = [];
    
    let added = 0;
    _aiGeneratedQuestions.forEach(q => {
      QDB[_aqCurrentCat].push({ diff: q.diff, q: q.q, a: q.a });
      added++;
    });
    
    if(typeof saveQDBToCloud === 'function') await saveQDBToCloud();
    if(typeof loadAdminCatQuestions === 'function') loadAdminCatQuestions();
    
    document.getElementById('hh-ai-modal')?.remove();
    
    if(typeof toast === 'function'){
      toast(`تم حفظ ${added} سؤال توليدها بالذكاء الاصطناعي`, 'success');
    }
    
    // تتبع
    if(window.hhTrackActivity){
      for(let i=0;i<added;i++) hhTrackActivity('question_added');
    }
    if(window.hhSoundWin) hhSoundWin();
    
  }catch(e){
    console.error('خطأ في حفظ أسئلة AI:', e);
    if(typeof toast === 'function') toast('تعذر الحفظ: ' + e.message, 'error');
  }
}

// إضافة keyframe للـspinner
(function(){
  if(document.getElementById('hh-ai-spin-style')) return;
  const s = document.createElement('style');
  s.id = 'hh-ai-spin-style';
  s.textContent = '@keyframes spin { from{transform:rotate(0)} to{transform:rotate(360deg)} }';
  document.head.appendChild(s);
})();

