// ════════════════════════════════════════════════════════════════════
//  تبويب إدارة المسابقات · تعديل الاسم والشخصية والصورة والفئات والأسئلة
// ════════════════════════════════════════════════════════════════════
var _compAdminSel = 'wafa';
function _compCfg(){ try{ return JSON.parse(localStorage.getItem('hh_comp_config')||'{}')||{}; }catch(e){ return {}; } }

function _compAdminList(){
  // كل المسابقات: الوفاء ثم بقية لوحات الشخصية من السجل ثم القرآن
  const out=[['wafa', (CAT_INFO[_HH_WAFA_CAT]&&CAT_INFO[_HH_WAFA_CAT].label)||'يوم الوفاء']];
  try{
    if(typeof _HH_CHAR_COMPS!=='undefined'){
      Object.keys(_HH_CHAR_COMPS).forEach(cat=>{
        if(cat===_HH_WAFA_CAT) return;
        out.push([cat, (CAT_INFO[cat]&&CAT_INFO[cat].label)||cat]);
      });
    }
  }catch(_e){}
  out.push(['quran','مسابقة القرآن']);
  return out;
}
function renderCompAdmin(){
  _hhSnapshotCompDefaults();
  const box=document.getElementById('comp-admin-body'); if(!box) return;
  const isWafa=_compAdminSel==='wafa';
  const isQuran=_compAdminSel==='quran';
  const isChar=!isWafa && !isQuran;
  const cat = isWafa? _HH_WAFA_CAT : (isQuran? _HH_AJYAL_QURAN_COMP_CAT : _compAdminSel);
  const label = (CAT_INFO[cat]&&CAT_INFO[cat].label)||cat;
  const charOvr=(typeof _HH_COMP_OVR!=='undefined'&&_HH_COMP_OVR[cat])||{};
  const charCC=isChar&&_HH_CHAR_COMPS[cat]?_HH_CHAR_COMPS[cat]:null;
  box.innerHTML='';

  const mk=(tag,css,txt)=>{const e=document.createElement(tag); if(css)e.style.cssText=css; if(txt!=null)e.textContent=txt; return e;};
  const fld=(lab,val,id)=>{
    const w=mk('div','margin-bottom:10px;');
    w.appendChild(mk('div','font-family:Cairo;font-weight:800;font-size:.8rem;color:#5E0E26;margin-bottom:4px;',lab));
    const inp=document.createElement('input'); inp.type='text'; inp.id=id; inp.value=val||'';
    inp.style.cssText='width:100%;padding:9px 12px;border:1.5px solid #d8cfd3;border-radius:10px;font-family:Cairo;font-size:.85rem;box-sizing:border-box;';
    w.appendChild(inp); return w;
  };

  // اختيار المسابقة · ديناميكي من السجل: أي مسابقة جديدة تظهر تلقائياً
  const selWrap=mk('div','display:flex;gap:8px;margin-bottom:14px;flex-wrap:wrap;');
  _compAdminList().forEach(([k,t])=>{
    const b=mk('button','padding:8px 14px;border-radius:10px;font-family:Cairo;font-weight:900;font-size:.78rem;cursor:pointer;border:2px solid #8A1538;'+(k===_compAdminSel?'background:#8A1538;color:#fff;':'background:#fff;color:#8A1538;'),t);
    b.onclick=()=>{ _compAdminSel=k; renderCompAdmin(); };
    selWrap.appendChild(b);
  });
  box.appendChild(selWrap);

  const card=mk('div','background:#fff;border:1.5px solid #e6dde1;border-radius:14px;padding:16px;');

  // ─── الإظهار / الإخفاء للمسابقة الحالية · يستعمل آلية hh_hidden_cats والمزامنة السحابية ───
  (function(){
    const hid = (typeof _hh_isCatHidden==='function') && _hh_isCatHidden(cat);
    const vis=mk('div','display:flex;align-items:center;gap:12px;flex-wrap:wrap;background:linear-gradient(170deg,#4A0B1E,#5E0E26);border:1.5px solid #B8924A;border-radius:12px;padding:10px 14px;margin-bottom:14px;');
    const txt=mk('div','flex:1;min-width:180px;font-family:Cairo;color:#F5E6C4;');
    txt.innerHTML='<div style="font-weight:900;font-size:.9rem;">حالة الظهور</div><div id="ca-vis-state" style="font-size:.72rem;color:#EAD9B0;">'+(hid?'مخفية · لا تظهر في شاشة الإعداد لأحد سواك':'ظاهرة · متاحة للجميع في خانة المسابقات')+'</div>';
    const sw=mk('div','width:52px;height:28px;border-radius:99px;position:relative;cursor:pointer;flex-shrink:0;background:'+(hid?'#8A7A63':'#B8924A')+';');
    sw.innerHTML='<i style="position:absolute;top:3px;'+(hid?'right:27px;':'right:3px;')+'width:22px;height:22px;border-radius:50%;background:#fff;box-shadow:0 1px 3px rgba(0,0,0,.3);"></i>';
    sw.title='إظهار / إخفاء هذه المسابقة';
    sw.onclick=function(){
      if(typeof toggleCatHidden==='function') toggleCatHidden(cat);
      const nh=(typeof _hh_isCatHidden==='function') && _hh_isCatHidden(cat);
      sw.style.background=nh?'#8A7A63':'#B8924A';
      sw.querySelector('i').style.right=nh?'27px':'3px';
      const st=document.getElementById('ca-vis-state');
      if(st) st.textContent=nh?'مخفية · لا تظهر في شاشة الإعداد لأحد سواك':'ظاهرة · متاحة للجميع في خانة المسابقات';
    };
    vis.appendChild(txt); vis.appendChild(sw); card.appendChild(vis);
  })();

  card.appendChild(fld('اسم المسابقة (يظهر في رأس اللوحة وبطاقة الاختيار)', label, 'ca-label'));

  if(isChar && charCC){
    card.appendChild(fld('لوحة الاسم · السطر الأول', charOvr.name1||charCC.name1||'', 'ca-n1'));
    card.appendChild(fld('لوحة الاسم · السطر الثاني (اختياري)', (charOvr.name2!==undefined?charOvr.name2:(charCC.name2||'')), 'ca-n2'));
    const imgW2=mk('div','display:flex;align-items:center;gap:14px;margin:12px 0;');
    const prev2=document.createElement('img'); prev2.id='ca-img-prev'; prev2.src=charOvr.img||charCC.img||'';
    prev2.style.cssText='width:84px;height:84px;border-radius:12px;border:2px solid #B8924A;object-fit:contain;background:#fff;';
    const up2=document.createElement('input'); up2.type='file'; up2.accept='image/*'; up2.id='ca-img-file';
    up2.style.cssText='font-family:Cairo;font-size:.78rem;';
    up2.onchange=function(){ const f=this.files&&this.files[0]; if(!f) return;
      const r=new FileReader(); r.onload=ev=>{
        const img=new Image(); img.onload=()=>{
          const c=document.createElement('canvas'); c.width=520; c.height=520;
          const x=c.getContext('2d'); x.fillStyle='#fff'; x.fillRect(0,0,520,520);
          const rr=Math.min(464/img.width,464/img.height);
          const nw=img.width*rr, nh=img.height*rr;
          x.drawImage(img,(520-nw)/2,(520-nh)/2,nw,nh);
          prev2.src=c.toDataURL('image/jpeg',.85);
        }; img.src=ev.target.result;
      }; r.readAsDataURL(f);
    };
    const lab3=mk('div','font-family:Cairo;font-weight:800;font-size:.8rem;color:#5E0E26;','صورة الوسط (تُهيّأ 520×520 على أبيض تلقائياً)');
    const col2=mk('div',''); col2.appendChild(lab3); col2.appendChild(up2);
    imgW2.appendChild(prev2); imgW2.appendChild(col2); card.appendChild(imgW2);
    const subsW2=mk('div','display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:6px;');
    (charCC.subs||[]).forEach((sb,i)=>{ subsW2.appendChild(fld('الفئة الفرعية '+(i+1), (charOvr.subs&&charOvr.subs[i])||sb.label, 'ca-sub-'+i)); });
    card.appendChild(mk('div','font-family:Cairo;font-weight:900;font-size:.85rem;color:#8A1538;margin:8px 0;','الفئات الفرعية الأربع'));
    card.appendChild(subsW2);
  }

  if(isWafa){
    card.appendChild(fld('اسم الشخصية · السطر الأول', _HH_WAFA_NAME1, 'ca-n1'));
    card.appendChild(fld('اسم الشخصية · السطر الثاني', _HH_WAFA_NAME2, 'ca-n2'));
    // الصورة
    const imgW=mk('div','display:flex;align-items:center;gap:14px;margin:12px 0;');
    const prev=document.createElement('img'); prev.id='ca-img-prev'; prev.src=_HH_WAFA_IMG;
    prev.style.cssText='width:84px;height:84px;border-radius:12px;border:2px solid #B8924A;object-fit:cover;';
    const up=document.createElement('input'); up.type='file'; up.accept='image/*'; up.id='ca-img-file';
    up.style.cssText='font-family:Cairo;font-size:.78rem;';
    up.onchange=function(){ const f=this.files&&this.files[0]; if(!f) return;
      const r=new FileReader(); r.onload=ev=>{
        const img=new Image(); img.onload=()=>{
          const c=document.createElement('canvas'); c.width=520; c.height=520;
          const x=c.getContext('2d'); const side=Math.min(img.width,img.height);
          x.drawImage(img,(img.width-side)/2,(img.height-side)/2,side,side,0,0,520,520);
          prev.src=c.toDataURL('image/jpeg',.85);
        }; img.src=ev.target.result;
      }; r.readAsDataURL(f);
    };
    const lab2=mk('div','font-family:Cairo;font-weight:800;font-size:.8rem;color:#5E0E26;','صورة الشخصية (تُقصّ مربعة 520×520 تلقائياً)');
    const col=mk('div',''); col.appendChild(lab2); col.appendChild(up);
    imgW.appendChild(prev); imgW.appendChild(col); card.appendChild(imgW);
    // الفئات الفرعية
    const subsW=mk('div','display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:6px;');
    _HH_WAFA_SUBS.forEach((sb,i)=>{ subsW.appendChild(fld('الفئة الفرعية '+(i+1), sb.label, 'ca-sub-'+i)); });
    card.appendChild(mk('div','font-family:Cairo;font-weight:900;font-size:.85rem;color:#8A1538;margin:8px 0;','الفئات الفرعية الأربع'));
    card.appendChild(subsW);
  }

  // الأسئلة
  card.appendChild(mk('div','font-family:Cairo;font-weight:900;font-size:.85rem;color:#8A1538;margin:14px 0 8px;','الأسئلة ('+((_HH_PARTNER_QUESTIONS[cat]||[]).length)+' سؤالاً) · عدّل النص والإجابة'));
  const list=mk('div','display:flex;flex-direction:column;gap:8px;max-height:420px;overflow:auto;border:1.5px solid #eee;border-radius:10px;padding:10px;background:#fbfafa;');
  const qs=_HH_PARTNER_QUESTIONS[cat]||[];
  const diffLab={easy:'200',med:'400',hard:'600',elite:'800'};
  qs.forEach((qq,i)=>{
    const row=mk('div','background:#fff;border:1px solid #e8e0e3;border-radius:10px;padding:8px 10px;');
    const meta=mk('div','display:flex;gap:6px;margin-bottom:6px;align-items:center;');
    meta.appendChild(mk('span','background:#8A1538;color:#fff;border-radius:6px;padding:1px 8px;font-family:Cairo;font-weight:800;font-size:.68rem;',diffLab[qq.diff]||qq.diff));
    const _subsSrc = isWafa ? _HH_WAFA_SUBS : (charCC ? charCC.subs : null);
    if(_subsSrc && typeof qq.sub==='number') meta.appendChild(mk('span','background:#f5ecd7;color:#8A6D2E;border-radius:6px;padding:1px 8px;font-family:Cairo;font-weight:800;font-size:.68rem;',_subsSrc[qq.sub]?_subsSrc[qq.sub].label:''));
    row.appendChild(meta);
    const qi=document.createElement('input'); qi.type='text'; qi.value=qq.q; qi.className='ca-q'; qi.dataset.i=i;
    qi.style.cssText='width:100%;padding:7px 10px;border:1px solid #ddd;border-radius:8px;font-family:Cairo;font-size:.8rem;box-sizing:border-box;margin-bottom:5px;';
    const ai=document.createElement('input'); ai.type='text'; ai.value=qq.a; ai.className='ca-a'; ai.dataset.i=i;
    ai.style.cssText='width:100%;padding:7px 10px;border:1px solid #cfe0d6;border-radius:8px;font-family:Cairo;font-size:.8rem;box-sizing:border-box;background:#f4faf6;';
    row.appendChild(qi); row.appendChild(ai);
    list.appendChild(row);
  });
  card.appendChild(list);

  // أزرار الحفظ والاستعادة
  const bar=mk('div','display:flex;gap:10px;margin-top:14px;flex-wrap:wrap;');
  const save=mk('button','padding:11px 26px;background:linear-gradient(135deg,#3D6B53,#2a4d3a);color:#fff;border:none;border-radius:10px;font-family:Cairo;font-weight:900;font-size:.85rem;cursor:pointer;',' حفظ ومزامنة للجميع');
  save.onclick=saveCompAdmin;
  const reset=mk('button','padding:11px 22px;background:#fff;color:#c0392b;border:2px solid #c0392b;border-radius:10px;font-family:Cairo;font-weight:900;font-size:.85rem;cursor:pointer;','↩ استعادة الافتراضي لهذه المسابقة');
  reset.onclick=()=>{ if(!confirm('استعادة الإعدادات والأسئلة الافتراضية لهذه المسابقة؟')) return;
    const cfg=_compCfg();
    if(isChar){ if(cfg.chars) delete cfg.chars[cat]; } else { delete cfg[_compAdminSel]; }
    localStorage.setItem('hh_comp_config', JSON.stringify(cfg));
    _hhApplyCompConfig(); renderCompAdmin();
    if(typeof _hh_saveCustomizationsToCloud==='function') _hh_saveCustomizationsToCloud();
    toast('استُعيد الافتراضي','success');
  };
  bar.appendChild(save); bar.appendChild(reset); card.appendChild(bar);
  box.appendChild(card);
}

function saveCompAdmin(){
  try{
    const isWafa=_compAdminSel==='wafa';
    const isQuran=_compAdminSel==='quran';
    const isChar=!isWafa && !isQuran;
    const cat = isWafa? _HH_WAFA_CAT : (isQuran? _HH_AJYAL_QURAN_COMP_CAT : _compAdminSel);
    const base=JSON.parse(JSON.stringify(_HH_PARTNER_QUESTIONS[cat]||[]));
    document.querySelectorAll('#comp-admin-body .ca-q').forEach(inp=>{ const i=+inp.dataset.i; if(base[i]&&inp.value.trim()) base[i].q=inp.value.trim(); });
    document.querySelectorAll('#comp-admin-body .ca-a').forEach(inp=>{ const i=+inp.dataset.i; if(base[i]&&inp.value.trim()) base[i].a=inp.value.trim(); });
    const cfg=_compCfg();
    if(isWafa){
      cfg.wafa={
        label:(document.getElementById('ca-label')||{}).value||'',
        name1:(document.getElementById('ca-n1')||{}).value||'',
        name2:(document.getElementById('ca-n2')||{}).value||'',
        img:(document.getElementById('ca-img-prev')||{}).src||'',
        subs:[0,1,2,3].map(i=>((document.getElementById('ca-sub-'+i)||{}).value||'')),
        questions:base
      };
      if(cfg.wafa.img && cfg.wafa.img.indexOf('data:image')!==0) delete cfg.wafa.img;
    } else if(isChar){
      cfg.chars=cfg.chars||{};
      const subsN=(_HH_CHAR_COMPS[cat]&&_HH_CHAR_COMPS[cat].subs||[]).length;
      cfg.chars[cat]={
        label:(document.getElementById('ca-label')||{}).value||'',
        name1:(document.getElementById('ca-n1')||{}).value||'',
        name2:(document.getElementById('ca-n2')||{}).value||'',
        img:(document.getElementById('ca-img-prev')||{}).src||'',
        subs:Array.from({length:subsN},(_,i)=>((document.getElementById('ca-sub-'+i)||{}).value||'')),
        questions:base
      };
      if(cfg.chars[cat].img && cfg.chars[cat].img.indexOf('data:image')!==0) delete cfg.chars[cat].img;
    } else {
      cfg.quran={ label:(document.getElementById('ca-label')||{}).value||'', questions:base };
    }
    //  حارس الحجم: حماية مستند المزامنة من حد 1MB (تلف صامت سابقاً)
    const _cfgStr=JSON.stringify(cfg);
    if(_cfgStr.length > 700*1024){
      toast('حجم التخصيصات تجاوز الحد الآمن (700KB) · صغّر الصورة أو استعد الافتراضي لمسابقة أخرى','error');
      return;
    }
    localStorage.setItem('hh_comp_config', _cfgStr);
    _hhApplyCompConfig();
    toast('✓ حُفظت تخصيصات المسابقة','success');
    if(typeof _hh_saveCustomizationsToCloud==='function') _hh_saveCustomizationsToCloud();
    renderCompAdmin();
  }catch(e){ toast('تعذر الحفظ: '+e.message,'error'); }
}

function adminTab(tab){
  const tabs = ['home','users','questions','review','permissions','reviews','backup','paths','categories','announcements','stats','whatsnew','reports','toolbox','landing','sponsors','competitions','teachers','directory','classes','curriculum','activity','healthcheck'];

  document.querySelectorAll('.admin-tab').forEach(b=>{
    const onclick = b.getAttribute('onclick')||'';
    const match = onclick.match(/adminTab\('([^']+)'\)/);
    if(match) b.classList.toggle('active', match[1]===tab);
  });
  document.querySelectorAll('.mc-item[data-tab]').forEach(b=>{
    b.classList.toggle('active', b.dataset.tab===tab);
  });
  document.querySelectorAll('.mc-mobile-group[data-tab]').forEach(b=>{
    b.classList.toggle('active', b.dataset.tab===tab);
  });

  tabs.forEach(t=>{
    const p = document.getElementById('admin-'+t+'-panel');
    if(p) p.style.display = t===tab ? 'block' : 'none';
  });

  if(tab==='home'){ try{ mcRenderHome(); }catch(e){console.warn('mcRenderHome:',e);} }
  if(tab==='teachers'){ try{ hhAdmLoadTeachers('pending'); }catch(e){} }
  if(tab==='directory'){ try{ hhLoadTeacherDirectory(); }catch(e){} }
  if(tab==='classes'){ try{ hhAdmLoadClasses(); }catch(e){} }
  if(tab==='activity'){ try{ hhAdmLoadActivity(); }catch(e){} }
  if(tab==='review'){ try{ qrInit(); }catch(e){console.warn('qrInit:',e);} }
  if(tab==='questions'){ populateAQCatSelect(); _updateQDBStatusBanner(); }
  if(tab==='permissions') loadPermissionsPanel();
  if(tab==='backup') loadBackupPanel();
  if(tab==='paths') renderPathsAdminPanel();
  if(tab==='categories') renderAdminCategoriesList();
  if(tab==='announcements') loadAnnouncementForm();
  if(tab==='stats') refreshAdminStats();
  if(tab==='whatsnew') renderWhatsNewAdmin();
  if(tab==='reports') renderProblemReports();
  if(tab==='toolbox') renderToolboxAdmin();
  if(tab==='sponsors') renderSponsorsAdmin();
  if(tab==='landing') lpLoadSettings();
  if(tab==='competitions') renderCompAdmin();
  if(tab==='healthcheck') runHealthCheck();

  try{ localStorage.setItem('mc_last_tab', tab); }catch(e){}
}

