const TBX_TOOLS = [
  {id:'games',     name:'الألعاب التنافسية', desc:'فرق طلابك وتنافسوا',          color:'#8A1538', section:'حصصك التفاعلية'},
  {id:'custom-q',  name:'أسئلتي المخصصة',    desc:'اصنع بنك أسئلتك الخاص',         color:'#5a3a8e', section:'حصصك التفاعلية'},
  {id:'lesson',    name:'الحصة التفاعلية',    desc:'حصص حركية تشاركية',             color:'#1F4E79', section:'حصصك التفاعلية'},
  {id:'activity',  name:'مولد الأنشطة',      desc:'أنشطة جاهزة بنقرة',             color:'#A67C4A', section:'حصصك التفاعلية'},
  {id:'grader',    name:'المصحح الذكي',     desc:'تصحيح أوتوماتيكي',              color:'#3D6B53', section:'إدارة الفصل'},
  {id:'classes',   name:'فصولي',              desc:'إدارة الطلاب والفصول',          color:'#8A1538', section:'إدارة الفصل'},
  {id:'certs',     name:'الشهادات',           desc:'شهادات تفوق ومشاركة',           color:'#B8924A', section:'إدارة الفصل'},
  {id:'bag',       name:'حقيبة المعلم',       desc:'ملفات وموارد جاهزة',            color:'#1F4E79', section:'إدارة الفصل'}
];

function _hh_getToolboxStates(){
  try{ return JSON.parse(localStorage.getItem('hh_tbx_states')||'{}'); }
  catch(e){ return {}; }
}
function _hh_saveToolboxStates(s){
  localStorage.setItem('hh_tbx_states', JSON.stringify(s));
}

function renderToolboxAdmin(){
  if(typeof isAdminUser==='function' && !isAdminUser(currentUser)){
    if(typeof toast==='function') toast('فقط المدير','error');
    return;
  }
  const list = document.getElementById('tbx-list');
  if(!list) return;
  const states = _hh_getToolboxStates();

  list.innerHTML = '';
  // ترتيب حسب الأقسام
  const sections = {};
  TBX_TOOLS.forEach(t => {
    sections[t.section] = sections[t.section] || [];
    sections[t.section].push(t);
  });

  Object.entries(sections).forEach(([secName, tools]) => {
    const secDiv = document.createElement('div');
    secDiv.style.cssText = 'margin-bottom:14px;';
    secDiv.innerHTML = '<div style="font-family:Cairo;font-weight:900;color:#8A1538;font-size:.95rem;margin-bottom:8px;padding:6px 12px;background:#F8F8F6;border-radius:8px;border-right:4px solid #B8924A;">'+esc(secName)+'</div>';

    tools.forEach(tool => {
      const state = states[tool.id] || {visible:true, status:'available'};
      // الافتراضي: 4 أدوات soon (lesson/activity/grader/classes/certs/bag)
      const defaultStatus = ['games','custom-q'].includes(tool.id) ? 'available' : 'soon';
      if(states[tool.id] === undefined){
        state.status = defaultStatus;
      }

      const card = document.createElement('div');
      card.style.cssText = 'background:#fff;border:1.5px solid #ecf0f1;border-right:4px solid '+tool.color+';border-radius:10px;padding:12px;margin-bottom:8px;display:flex;align-items:center;gap:10px;flex-wrap:wrap;';
      card.innerHTML = '' + '<div style="flex:1;min-width:180px;">' +   '<div style="font-family:Cairo;font-weight:900;color:#3D0918;font-size:.92rem;">'+esc(tool.name)+'</div>' +   '<div style="font-family:Tajawal;font-size:.75rem;color:#666;margin-top:2px;">'+esc(tool.desc)+'</div>' + '</div>' + '<div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap;">' +   '<label style="display:flex;align-items:center;gap:4px;font-family:Cairo;font-weight:900;font-size:.72rem;color:#8A1538;cursor:pointer;">' +     '<input type="checkbox" '+(state.visible !== false ? 'checked' : '')+' onchange="toggleToolboxItem(\''+tool.id+'\',\'visible\',this.checked)" style="width:16px;height:16px;cursor:pointer;">' +     '<span>ظاهر</span>' +   '</label>' +   '<select onchange="toggleToolboxItem(\''+tool.id+'\',\'status\',this.value)" style="padding:5px 10px;border:1.5px solid #B8924A;border-radius:8px;font-family:Cairo;font-weight:900;font-size:.72rem;color:#8A1538;background:#fff;cursor:pointer;">' +     '<option value="available" '+(state.status === 'available' ? 'selected' : '')+'>متاح</option>' +     '<option value="soon" '+(state.status === 'soon' ? 'selected' : '')+'>قريبا</option>' +   '</select>' + '</div>';
      secDiv.appendChild(card);
    });
    list.appendChild(secDiv);
  });

  // زر حفظ + ملاحظة
  const note = document.createElement('div');
  note.style.cssText = 'margin-top:10px;padding:10px;background:#F8F8F6;border:1px dashed #B8924A;border-radius:8px;font-family:Tajawal;font-size:.78rem;color:#8A6D2E;text-align:center;';
  note.innerHTML = '✓ التغييرات تحفظ تلقائيا. ستظهر في المحبرة بعد إعادة التحميل.';
  list.appendChild(note);
}

function toggleToolboxItem(id, key, value){
  if(typeof isAdminUser==='function' && !isAdminUser(currentUser)){ return; }
  const states = _hh_getToolboxStates();
  states[id] = states[id] || {};
  states[id][key] = value;
  _hh_saveToolboxStates(states);
  if(typeof toast==='function') toast('تم الحفظ','success');
  // تطبيق فوري لو شاشة المحبرة مفتوحة
  if(typeof applyToolboxStates === 'function') applyToolboxStates();
}

// تطبيق حالة المحبرة على الواجهة المرئية (يستدعى عند فتح screen-toolbox)
function applyToolboxStates(){
  const states = _hh_getToolboxStates();
  // خريطة id الإداري → onclick في الواجهة
  const idMap = {
    'games':    "showScreen('screen-setup')",
    'custom-q': "showScreen('screen-custom-q')",
    'lesson':   "showSoonToast('الحصة التفاعلية')",
    'activity': "showSoonToast('مولد الأنشطة')",
    'grader':   "showSoonToast('المصحح الذكي')",
    'classes':  "showSoonToast('فصولي')",
    'certs':    "showSoonToast('الشهادات')",
    'bag':      "showScreen('screen-bag')"
  };

  document.querySelectorAll('#screen-toolbox .tbx-tool').forEach(btn => {
    const onclickAttr = btn.getAttribute('onclick') || '';
    let toolId = null;
    for(const [id, fn] of Object.entries(idMap)){
      if(onclickAttr.includes(fn.split('(')[0]) && (fn.includes("'"+id) || onclickAttr.includes(fn))){
        toolId = id;
        break;
      }
    }
    // محاولة بديلة: مطابقة بالاسم
    if(!toolId){
      const nameEl = btn.querySelector('.tbx-tool-name');
      if(nameEl){
        const name = nameEl.textContent.trim();
        const tool = TBX_TOOLS.find(t => t.name === name || name.includes(t.name));
        if(tool) toolId = tool.id;
      }
    }
    if(!toolId) return;
    const state = states[toolId];
    if(!state) return;
    // إخفاء/إظهار
    btn.style.display = (state.visible === false) ? 'none' : '';
    // تحديث الشارة (متاح/قريبا) لو تم تغييرها
    if(state.status){
      const badge = btn.querySelector('.tbx-tool-badge');
      if(badge){
        if(state.status === 'available'){
          btn.classList.remove('tbx-soon');
          btn.classList.add('tbx-available');
          badge.classList.remove('tbx-badge-soon');
          badge.classList.add('tbx-badge-available');
          badge.textContent = 'متاح';
        } else {
          btn.classList.remove('tbx-available');
          btn.classList.add('tbx-soon');
          badge.classList.remove('tbx-badge-available');
          badge.classList.add('tbx-badge-soon');
          badge.textContent = 'قريبا';
        }
      }
    }
  });
}
