// ═══════════════════════════════════════════════════════════
//  شارة "جديد" ديناميكية على زر ماذا الجديد في القائمة
// ═══════════════════════════════════════════════════════════
window.refreshWhatsNewBadge = function(){
  try{
    const all = (typeof _hh_getWhatsNew === 'function' ? _hh_getWhatsNew() : []).filter(it => it.published);
    if(all.length === 0){
      const b = document.getElementById('nav-wn-badge');
      if(b) b.style.display = 'none';
      return;
    }
    all.sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0));
    const lastSeen = localStorage.getItem('hh_wn_last_seen') || null;
    const newCount = lastSeen ? all.findIndex(it => it.id === lastSeen) : all.length;
    const badge = document.getElementById('nav-wn-badge');
    if(!badge) return;
    if(newCount > 0 || newCount === -1){
      const c = newCount === -1 ? all.length : newCount;
      badge.textContent = c > 1 ? c : 'جديد';
      badge.style.display = 'inline-flex';
    } else {
      badge.style.display = 'none';
    }
  }catch(e){ /* silent */ }
};

// CSS للنبضة (مرة واحدة فقط)
(function injectWnPulseCss(){
  if(document.getElementById('hh-wn-pulse-css')) return;
  const s = document.createElement('style');
  s.id = 'hh-wn-pulse-css';
  s.textContent = '@keyframes hh-wn-pulse{0%,100%{box-shadow:0 0 0 0 rgba(212,188,133,.7);}50%{box-shadow:0 0 0 4px rgba(212,188,133,0);}}';
  document.head.appendChild(s);
})();

// تشغيل تلقائي عند تحميل الصفحة (للزوار)
function _hh_autoShowWhatsNew(){
  // تحديث الشارة فورا
  setTimeout(function(){ try{ refreshWhatsNewBadge(); }catch(e){} }, 500);
  // افتح المودال بعد 4 ثوان (لما المستخدم يستوعب الصفحة)
  setTimeout(function(){
    try{
      // لا نزاحم نوافذ البداية: الخصوصية أو الجولة التعريفية أولى · تكفيه الشارة
      const _vis = el => { if(!el) return false; const st = getComputedStyle(el); return st.display !== 'none' && st.visibility !== 'hidden'; };
      if(_vis(document.getElementById('privacy-consent-modal')) || _vis(document.getElementById('onboarding-modal'))){ refreshWhatsNewBadge(); return; }
      showWhatsNewModal({}); refreshWhatsNewBadge();
    }catch(e){}
  }, 4000);
}
if(document.readyState === 'loading'){
  document.addEventListener('DOMContentLoaded', _hh_autoShowWhatsNew);
} else {
  _hh_autoShowWhatsNew();
}

