/**
 * بناء صف خدمة واحدة في لوحة الأدمن
 */
function _buildAdminServiceRow(svc, pathType){
  const status = getServiceStatus(pathType, svc.id);
  const statusInfo = {
    'available': { label:'متاحة',  emoji:'<svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 15l-5-5 1.41-1.41L10 14.17l7.59-7.59L19 8l-9 9z"/></svg>', color:'#3D6B53', bg:'#EBF2EE' },
    'soon':      { label:'قريبا',  emoji:'<svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M6 2v6h.01L6 8.01 10 12l-4 4 .01.01H6V22h12v-5.99h-.01L18 16l-4-4 4-3.99-.01-.01H18V2H6z"/></svg>', color:'#8A6D2E', bg:'#fef3d6' },
    'hidden':    { label:'مخفية',   emoji:'', color:'#922b21', bg:'#fde6e6' }
  }[status] || { label:'?', emoji:'?', color:'#888', bg:'#f0f0f0' };

  // شارة الحالة بجانب العنوان
  const statusBadge = `<span style="display:inline-flex;align-items:center;gap:3px;padding:2px 8px;border-radius:10px;background:${statusInfo.bg};color:${statusInfo.color};border:1px solid ${statusInfo.color};font-size:.62rem;font-weight:900;margin-right:6px;vertical-align:middle;font-family:Cairo,sans-serif;">${statusInfo.emoji} ${statusInfo.label}</span>`;

  // خلفية البطاقة تعكس الحالة
  const cardBg = status === 'hidden' ? '#fef5f5' : (status === 'soon' ? '#fffaeb' : '#f7fbf8');
  const cardBorder = status === 'hidden' ? '#f5cfcf' : (status === 'soon' ? '#f3e0a8' : '#cfe5d6');

  return `
    <div style="display:flex;align-items:center;gap:10px;padding:10px;background:${cardBg};border:1.5px solid ${cardBorder};border-radius:10px;margin-bottom:6px;${status === 'hidden' ? 'opacity:.85;' : ''}">
      <!-- الأيقونة -->
      <div style="width:36px;height:36px;border-radius:8px;background:linear-gradient(135deg,#8A1538,#5E0E26);color:#D4BC85;display:flex;align-items:center;justify-content:center;flex-shrink:0;${svc.iconBg}">
        <div style="width:18px;height:18px;">${svc.icon}</div>
      </div>
      <!-- العنوان والوصف -->
      <div style="flex:1;min-width:0;">
        <div style="font-family:Cairo;font-weight:900;color:#5E0E26;font-size:.85rem;line-height:1.3;">${svc.title} ${statusBadge}</div>
        <div style="font-size:.7rem;color:#888;font-weight:600;margin-top:2px;line-height:1.3;">${svc.desc}</div>
      </div>
      <!-- أزرار الحالة (3 خيارات) -->
      <div style="display:flex;gap:4px;flex-shrink:0;">
        <button onclick="_setServiceStatus('${svc.id}','available');"
                title="متاحة"
                style="width:32px;height:32px;border-radius:7px;border:1.5px solid ${status === 'available' ? '#3D6B53' : '#e0e6e0'};background:${status === 'available' ? '#3D6B53' : '#fff'};color:${status === 'available' ? '#fff' : '#3D6B53'};cursor:pointer;font-size:.92rem;display:flex;align-items:center;justify-content:center;transition:all .15s;"> ✓
        </button>
        <button onclick="_setServiceStatus('${svc.id}','soon');"
                title="قريبا"
                style="width:32px;height:32px;border-radius:7px;border:1.5px solid ${status === 'soon' ? '#B8924A' : '#e0e6e0'};background:${status === 'soon' ? '#B8924A' : '#fff'};color:${status === 'soon' ? '#fff' : '#8A6D2E'};cursor:pointer;font-size:.92rem;display:flex;align-items:center;justify-content:center;transition:all .15s;">
          <svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M6 2v6h.01L6 8.01 10 12l-4 4 .01.01H6V22h12v-5.99h-.01L18 16l-4-4 4-3.99-.01-.01H18V2H6z"/></svg>
        </button>
        <button onclick="_setServiceStatus('${svc.id}','hidden');"
                title="مخفية"
                style="width:32px;height:32px;border-radius:7px;border:1.5px solid ${status === 'hidden' ? '#c0392b' : '#e0e6e0'};background:${status === 'hidden' ? '#c0392b' : '#fff'};color:${status === 'hidden' ? '#fff' : '#c0392b'};cursor:pointer;font-size:.92rem;display:flex;align-items:center;justify-content:center;transition:all .15s;"> ✕
        </button>
      </div>
    </div> `;
}

/**
 * رسم لوحة إدارة المسارات (تستدعى عند فتح التبويبة)
 */
async function renderPathsAdminPanel(){
  const teacherEl = document.getElementById('admin-teacher-services');
  const studentEl = document.getElementById('admin-student-services');
  if(!teacherEl || !studentEl) return;

  // حمل الحالات من Firestore أولا
  try{ await loadPathServicesStatuses(); }catch(e){}

  // ارسم الخدمات
  if(typeof TEACHER_PATH_SERVICES !== 'undefined'){
    teacherEl.innerHTML = TEACHER_PATH_SERVICES.map(svc => _buildAdminServiceRow(svc, 'teacher')).join('');
  }
  if(typeof STUDENT_PATH_SERVICES !== 'undefined'){
    studentEl.innerHTML = STUDENT_PATH_SERVICES.map(svc => _buildAdminServiceRow(svc, 'student')).join('');
  }
}

window.renderPathsAdminPanel = renderPathsAdminPanel;

// ═══════════════════════════════════════════════════════════════════
// نظام النسخ الاحتياطي · Backup & Restore System
// ═══════════════════════════════════════════════════════════════════

var _backupFileContent = null;

/**
 * تحميل لوحة النسخ الاحتياطي (الإحصائيات + آخر تصدير)
 */
async function loadBackupPanel(){
  // تحديث الإحصائيات
  try{
    if(!OFFLINE_MODE && db){
      const [usersSnap, reviewsSnap] = await Promise.all([
        db.collection('users').get(),
        db.collection('reviews').get()
      ]);
      document.getElementById('backup-stat-users').textContent = usersSnap.size;
      document.getElementById('backup-stat-reviews').textContent = reviewsSnap.size;
      // عد الأسئلة المخصصة من QDB + custom
      const customQs = JSON.parse(localStorage.getItem('hh_custom_cats')||'{}');
      const customCount = Object.values(customQs).reduce((s,a)=>s + (Array.isArray(a)?a.length:0), 0);
      const defaultCount = Object.values(QDB||{}).reduce((s,a)=>s + (Array.isArray(a)?a.length:0), 0);
      document.getElementById('backup-stat-questions').textContent = defaultCount + customCount;
    } else {
      document.getElementById('backup-stat-users').textContent = 'محلي';
      document.getElementById('backup-stat-reviews').textContent = '·';
      document.getElementById('backup-stat-questions').textContent = Object.values(QDB||{}).reduce((s,a)=>s + (Array.isArray(a)?a.length:0), 0);
    }
  }catch(e){ console.error('Backup stats error:', e); }

  // تاريخ آخر تصدير
  const lastExport = localStorage.getItem('hh_last_backup_at');
  const lastEl = document.getElementById('backup-last-export');
  if(lastEl){
    if(lastExport){
      const d = new Date(parseInt(lastExport));
      lastEl.textContent = d.toLocaleDateString('ar-QA',{year:'numeric',month:'long',day:'numeric'}) + ' · ' + d.toLocaleTimeString('ar-QA',{hour:'2-digit',minute:'2-digit'});
    } else {
      lastEl.textContent = 'لم يتم التصدير بعد';
    }
  }
}

/**
 * تصدير النسخة الاحتياطية
 */
async function exportBackup(){
  const btn = document.getElementById('backup-export-btn');
  const originalHTML = btn.innerHTML;
  btn.innerHTML = '<span>جاري تجهيز النسخة...</span>';
  btn.disabled = true;

  try{
    const backup = {
      _meta: {
        version: '1.0',
        platform: 'Al-Halhali Educational Platform',
        exportedAt: new Date().toISOString(),
        exportedBy: currentUser?.email || 'admin',
        domain: 'alhalhali.com' },
      data: {}
    };

    const incUsers = document.getElementById('bk-inc-users').checked;
    const incQuestions = document.getElementById('bk-inc-questions').checked;
    const incReviews = document.getElementById('bk-inc-reviews').checked;
    const incLB = document.getElementById('bk-inc-leaderboard').checked;

    if(!OFFLINE_MODE && db){
      // جمع البيانات من Firebase
      if(incUsers){
        const snap = await db.collection('users').get();
        backup.data.users = snap.docs.map(d=>({id:d.id, ...d.data()}));
      }
      if(incReviews){
        const snap = await db.collection('reviews').get();
        backup.data.reviews = snap.docs.map(d=>({id:d.id, ...d.data()}));
      }
      if(incLB){
        try{
          const snap = await db.collection('leaderboard').get();
          backup.data.leaderboard = snap.docs.map(d=>({id:d.id, ...d.data()}));
        }catch(e){ backup.data.leaderboard = []; }
      }
    }

    if(incQuestions){
      // الأسئلة الافتراضية + المخصصة من localStorage
      backup.data.defaultQuestions = QDB || {};
      backup.data.customQuestions = JSON.parse(localStorage.getItem('hh_custom_cats')||'{}');
    }

    // بيانات إضافية من localStorage
    backup.data.localStorage = {
      hh_saved_cats: localStorage.getItem('hh_saved_cats'),
      hh_custom_cats: localStorage.getItem('hh_custom_cats'),
      hh_privacy_consent: localStorage.getItem('hh_privacy_consent')
    };

    // إنشاء الملف وتنزيله
    const jsonStr = JSON.stringify(backup, null, 2);
    const blob = new Blob([jsonStr], {type: 'application/json;charset=utf-8'});
    const url = URL.createObjectURL(blob);
    const now = new Date();
    const dateStr = now.toISOString().split('T')[0];
    const fileName = `alhalhali-backup-${dateStr}.json`;

    const a = document.createElement('a');
    a.href = url;
    a.download = fileName;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(()=>URL.revokeObjectURL(url), 1000);

    // تسجيل وقت التصدير
    localStorage.setItem('hh_last_backup_at', Date.now().toString());
    loadBackupPanel(); // تحديث التاريخ

    btn.innerHTML = '<span>تم التنزيل بنجاح</span>';
    toast('تم حفظ النسخة الاحتياطية: ' + fileName, 'success');
    setTimeout(()=>{ btn.innerHTML = originalHTML; btn.disabled = false; }, 2200);

  }catch(e){
    console.error('Export error:', e);
    btn.innerHTML = '<span>حدث خطأ · حاول مجددا</span>';
    toast('تعذر التصدير: ' + e.message, 'error');
    setTimeout(()=>{ btn.innerHTML = originalHTML; btn.disabled = false; }, 2500);
  }
}

/**
 * عند اختيار ملف للاستيراد
 */
function handleBackupFileSelect(event){
  const file = event.target.files[0];
  const label = document.getElementById('backup-file-label');
  const nameEl = document.getElementById('backup-file-name');
  const btn = document.getElementById('backup-import-btn');
  const resultEl = document.getElementById('backup-import-result');

  if(!file){
    _backupFileContent = null;
    btn.disabled = true;
    return;
  }

  if(!file.name.endsWith('.json')){
    toast('يجب اختيار ملف JSON', 'error');
    return;
  }

  if(file.size > 10 * 1024 * 1024){
    toast('حجم الملف كبير جدا (الحد الأقصى 10MB)', 'error');
    return;
  }

  const reader = new FileReader();
  reader.onload = function(e){
    try{
      const content = JSON.parse(e.target.result);
      // التحقق من صحة البنية
      if(!content._meta || content._meta.platform !== 'Al-Halhali Educational Platform'){
        toast('هذا الملف ليس نسخة احتياطية صالحة من الملهم', 'error');
        return;
      }
      _backupFileContent = content;
      nameEl.textContent = file.name;
      label.classList.add('has-file');
      btn.disabled = false;

      // عرض معلومات الملف
      const exportedAt = new Date(content._meta.exportedAt).toLocaleDateString('ar-QA',{year:'numeric',month:'long',day:'numeric'});
      const counts = [];
      if(content.data?.users) counts.push(content.data.users.length + ' مستخدم');
      if(content.data?.reviews) counts.push(content.data.reviews.length + ' تقييم');
      if(content.data?.customQuestions) counts.push(Object.keys(content.data.customQuestions).length + ' فئة أسئلة');
      resultEl.innerHTML = '<div style="background:#e8f2ec;border-right:3px solid #8A1538;padding:8px 12px;border-radius:8px;color:#8A1538;"><strong>تاريخ التصدير:</strong> '+exportedAt+'<br><strong>المحتوى:</strong> '+counts.join('، ')+'</div>';
    }catch(err){
      toast('الملف غير صالح أو تالف', 'error');
      console.error(err);
    }
  };
  reader.readAsText(file);
}

/**
 * استيراد النسخة الاحتياطية
 */
async function importBackup(){
  if(!_backupFileContent){
    toast('اختر ملف نسخة احتياطية أولا', 'error');
    return;
  }

  const confirmMsg = 'تحذير مهم!\n\n' +
    'سيتم استبدال البيانات الحالية في قاعدة البيانات بالبيانات من الملف المختار.\n\n' +
    'هذه العملية لا يمكن التراجع عنها.\n\n' +
    'هل تريد المتابعة؟';
  if(!confirm(confirmMsg)) return;

  // تأكيد إضافي
  if(!confirm('تأكيد نهائي: هل أنت متأكد من استبدال البيانات؟')) return;

  const btn = document.getElementById('backup-import-btn');
  const resultEl = document.getElementById('backup-import-result');
  const originalHTML = btn.innerHTML;
  btn.innerHTML = '<span>جاري الاستعادة...</span>';
  btn.disabled = true;

  const log = [];
  let hasError = false;

  try{
    const data = _backupFileContent.data || {};

    // استعادة الأسئلة المخصصة (localStorage - آمن وفوري)
    if(data.customQuestions){
      localStorage.setItem('hh_custom_cats', JSON.stringify(data.customQuestions));
      const count = Object.values(data.customQuestions).reduce((s,a)=>s + (Array.isArray(a)?a.length:0), 0);
      log.push('✓ ' + count + ' سؤال مخصص');
    }

    // استعادة إعدادات localStorage
    if(data.localStorage){
      if(data.localStorage.hh_saved_cats) localStorage.setItem('hh_saved_cats', data.localStorage.hh_saved_cats);
      log.push('✓ الإعدادات المحلية');
    }

    // استعادة Firebase (إن كنا متصلين)
    if(!OFFLINE_MODE && db){
      // المستخدمون · merge بدل overwrite لتجنب فقدان الحسابات النشطة
      if(data.users && Array.isArray(data.users)){
        for(const user of data.users){
          try{
            const {id, ...userData} = user;
            if(id) await db.collection('users').doc(id).set(userData, {merge: true});
          }catch(e){ console.error('User restore error:', e); }
        }
        log.push('✓ ' + data.users.length + ' مستخدم');
      }

      // التقييمات · overwrite الموجود وإضافة الجديد
      if(data.reviews && Array.isArray(data.reviews)){
        for(const review of data.reviews){
          try{
            const {id, ...reviewData} = review;
            if(id) await db.collection('reviews').doc(id).set(reviewData);
          }catch(e){ console.error('Review restore error:', e); }
        }
        log.push('✓ ' + data.reviews.length + ' تقييم');
      }

      // لوحة المتصدرين
      if(data.leaderboard && Array.isArray(data.leaderboard)){
        for(const lb of data.leaderboard){
          try{
            const {id, ...lbData} = lb;
            if(id) await db.collection('leaderboard').doc(id).set(lbData);
          }catch(e){ console.error('LB restore error:', e); }
        }
        log.push('✓ ' + data.leaderboard.length + ' سجل في المتصدرين');
      }
    }

    resultEl.innerHTML = '<div style="background:#EBF2EE;border-right:3px solid #3D6B53;padding:10px 12px;border-radius:8px;color:#5E0E26;font-weight:800;">تمت الاستعادة بنجاح:<br>' + log.join('<br>') + '</div>';
    toast('تمت استعادة النسخة بنجاح · أعد تحميل الصفحة', 'success');
    btn.innerHTML = '<span>نجحت الاستعادة · أعد التحميل</span>';
    setTimeout(()=>{
      if(confirm('تمت الاستعادة بنجاح. هل تريد إعادة تحميل الصفحة الآن؟')){
        window.location.reload();
      }
      btn.innerHTML = originalHTML;
      btn.disabled = false;
    }, 1500);

  }catch(e){
    console.error('Import error:', e);
    hasError = true;
    resultEl.innerHTML = '<div style="background:#fff4f4;border-right:3px solid #c0392b;padding:10px 12px;border-radius:8px;color:#8b1a1a;font-weight:800;">فشل الاستيراد: ' + e.message + '</div>';
    toast('تعذر الاستيراد: ' + e.message, 'error');
    btn.innerHTML = originalHTML;
    btn.disabled = false;
  }
}
