// ════ إدارة صور الفئات ════
function openCatImgManager(){
  const existing=document.getElementById('cat-img-modal');
  if(existing)existing.remove();

  const overlay=document.createElement('div');
  overlay.id='cat-img-modal';
  overlay.style.cssText='position:fixed;inset:0;z-index:9000;background:rgba(0,0,0,.6);display:flex;align-items:center;justify-content:center;padding:16px;';
  overlay.onclick=function(e){if(e.target===overlay)overlay.remove();};

  const box=document.createElement('div');
  box.style.cssText='background:#fff;border-radius:16px;padding:20px;max-width:520px;width:100%;max-height:82vh;overflow-y:auto;box-shadow:6px 6px 0 #8A1538;direction:rtl;';

  // رأس
  const hdr=document.createElement('div');
  hdr.style.cssText='display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;border-bottom:2px solid #8A1538;padding-bottom:8px;';
  const htitle=document.createElement('div');
  htitle.style.cssText='font-weight:900;font-size:1rem;color:#8A1538;';
  htitle.textContent=' صور الفئات';
  const hclose=document.createElement('button');
  hclose.textContent='✕';
  hclose.style.cssText='background:none;border:none;font-size:1.3rem;cursor:pointer;color:#555;';
  hclose.onclick=function(){overlay.remove();};
  hdr.appendChild(htitle); hdr.appendChild(hclose);
  box.appendChild(hdr);

  const note=document.createElement('div');
  note.style.cssText='font-size:.78rem;color:#777;margin-bottom:12px;';
  note.textContent='ارفع صورة مخصصة لأي فئة بدل الرسمة التلقائية';
  box.appendChild(note);

  const list=document.createElement('div');
  list.style.cssText='display:flex;flex-direction:column;gap:8px;';

  Object.keys(CAT_INFO).forEach(function(cat){
    var ci=CAT_INFO[cat]||{};
    var savedImg=localStorage.getItem('cat_img_'+cat);

    var row=document.createElement('div');
    row.style.cssText='display:flex;align-items:center;gap:10px;padding:8px 10px;border:1px solid #eee;border-radius:8px;';

    // أيقونة
    var icon=document.createElement('div');
    icon.style.cssText='width:40px;height:40px;border-radius:8px;overflow:hidden;background:'+(ci.bg||'#f0f4f8')+';display:flex;align-items:center;justify-content:center;flex-shrink:0;';
    if(savedImg){
      icon.innerHTML='<img src="'+savedImg+'" alt="أيقونة" style="width:40px;height:40px;object-fit:contain;">';
    } else if(CAT_SVG&&CAT_SVG[cat]){
      var tmp=document.createElement('div');
      tmp.innerHTML=CAT_SVG[cat];
      var svgEl=tmp.querySelector('svg');
      if(svgEl){svgEl.setAttribute('width','40');svgEl.setAttribute('height','40');icon.appendChild(svgEl);}
    } else {
      icon.innerHTML=ci.emoji||'<svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M21 5c-1.11-.35-2.33-.5-3.5-.5-1.95 0-4.05.4-5.5 1.5-1.45-1.1-3.55-1.5-5.5-1.5S2.45 4.9 1 6v14.65c0 .25.25.5.5.5.1 0 .15-.05.25-.05C3.1 20.45 5.05 20 6.5 20c1.95 0 4.05.4 5.5 1.5 1.35-.85 3.8-1.5 5.5-1.5 1.65 0 3.35.3 4.75 1.05.1.05.15.05.25.05.25 0 .5-.25.5-.5V6c-.6-.45-1.25-.75-2-1z"/></svg>';
      icon.style.fontSize='1.3rem';
    }
    row.appendChild(icon);

    // اسم
    var name=document.createElement('div');
    name.style.cssText='flex:1;font-size:.82rem;font-weight:700;color:#8A1538;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;';
    name.textContent=ci.label||cat;
    row.appendChild(name);

    // input رفع
    var inp=document.createElement('input');
    inp.type='file'; inp.accept='image/*'; inp.style.display='none';
    inp.setAttribute('data-cat', cat);
    inp.onchange=function(e){ uploadCatImg(e.target.getAttribute('data-cat'), e.target.files[0]); };
    row.appendChild(inp);

    // زر رفع
    var upBtn=document.createElement('button');
    upBtn.textContent='رفع';
    upBtn.style.cssText='padding:4px 10px;border:1.5px solid #8A1538;border-radius:6px;background:#fff;font-size:.72rem;font-weight:700;cursor:pointer;';
    upBtn.onclick=function(){inp.click();};
    row.appendChild(upBtn);

    // زر حذف
    if(savedImg){
      var delBtn=document.createElement('button');
      delBtn.textContent='حذف';
      delBtn.style.cssText='padding:4px 8px;border:1.5px solid #c0392b;border-radius:6px;background:#fff;font-size:.72rem;color:#c0392b;cursor:pointer;';
      delBtn.onclick=function(){ removeCatImg(cat); overlay.remove(); openCatImgManager(); };
      row.appendChild(delBtn);
    }

    list.appendChild(row);
  });

  box.appendChild(list);
  overlay.appendChild(box);
  document.body.appendChild(overlay);
}


async function uploadCatImg(cat, file){
  if(!file||!cat)return;
  if(typeof toast==='function') toast('جار معالجة الصورة...', 'info');
  try{
    const dataUrl = await hhCompressImage(file, 250, 500);
    
    // 1) حفظ محلي (سريع وفوري)
    try{ localStorage.setItem('cat_img_'+cat, dataUrl); }catch(e){
      console.warn('localStorage save failed:', e);
    }
    
    var ci=CAT_INFO[cat]||{};
    
    // 2) حفظ سحابي (لكل المستخدمين)
    if(!OFFLINE_MODE && db && isAdminUser()){
      try{
        await db.collection('admin_cat_images').doc(_hh_safeDocId(cat)).set({
          cat: cat,
          dataUrl: dataUrl,
          updatedAt: firebase.firestore.FieldValue.serverTimestamp(),
          updatedBy: currentUser.email
        });
        toast('✓ تم رفع صورة '+(ci.label||cat)+' لكل المستخدمين','success');
      }catch(e){
        console.error('cloud img save:', e);
        toast('تم الحفظ محليا فقط (فشل الرفع السحابي)','warn');
      }
    } else {
      toast('تم حفظ صورة '+(ci.label||cat)+' (محليا)','info');
    }
    
    // 3) إعادة رسم اللوحة إن كانت مفتوحة
    if(document.getElementById('screen-board').classList.contains('active')&&G.selectedCats.length){
      buildBoard(); updateBoardUI();
    }
    var m=document.getElementById('cat-img-modal');
    if(m)m.remove();
    if(typeof openCatImgManager==='function') openCatImgManager();
  }catch(err){
    if(typeof toast==='function') toast('فشل معالجة الصورة', 'error');
    console.error(err);
  }
}

// تحويل اسم الفئة العربي إلى docId آمن
function _hh_safeDocId(cat){
  // Firestore لا يقبل '/'، نستبدل المسافات والأحرف الخاصة
  return encodeURIComponent(cat).replace(/%/g,'_');
}

// ════════════════════════════════════════════════════
//  مزامنة تخصيصات الأدمن (ألوان/إخفاء/مخصّصة) عبر السحابة
// تصل لكل المستخدمين فوراً · قلب "الفولاذية"
// ════════════════════════════════════════════════════

// حفظ تخصيصات الأدمن في السحابة (يستدعى عند أي تغيير من الأدمن)
// ════════════════════════════════════════════════════
//  فحص صحة المنصة · يكشف الأخطاء والنواقص فعلياً
// ════════════════════════════════════════════════════
async function runHealthCheck(){
  const box = document.getElementById('hc-results');
  if(!box) return;
  box.innerHTML = '<div style="text-align:center;padding:30px;color:#8A6D2E;font-family:Cairo;">⏳ جاري الفحص...</div>';
  const checks = [];

  // دالة مساعدة لإضافة نتيجة
  function add(status, title, detail){
    checks.push({status, title, detail});
  }

  // 1) اتصال Firebase
  if(typeof db !== 'undefined' && db && !OFFLINE_MODE){
    add('ok', 'الاتصال بقاعدة البيانات', 'Firebase متصل ويعمل');
  } else {
    add('error', 'الاتصال بقاعدة البيانات', 'المنصة بوضع عدم الاتصال · المزامنة معطّلة. تحقق من إعداد Firebase.');
  }

  // 2) حالة تسجيل الدخول كأدمن
  if(isAdminUser(currentUser)){
    add('ok', 'صلاحية الأدمن', 'أنت مسجّل كأدمن · يمكنك الحفظ السحابي');
  } else {
    add('error', 'صلاحية الأدمن', 'لست مسجّلاً كأدمن. تخصيصاتك لن تُحفظ في السحابة.');
  }

  // 3) اختبار الكتابة في السحابة (مزامنة فعلية)
  if(typeof db !== 'undefined' && db && !OFFLINE_MODE && isAdminUser(currentUser)){
    try{
      await db.collection('platform_settings').doc('_healthcheck_test').set({t: Date.now()});
      add('ok', 'الكتابة في السحابة (المزامنة)', 'نجح اختبار الكتابة · المزامنة تعمل ✓');
      try{ await db.collection('platform_settings').doc('_healthcheck_test').delete(); }catch(e){}
    }catch(e){
      if(e.code === 'permission-denied'){
        add('error', 'الكتابة في السحابة (المزامنة)', 'الصلاحيات ترفض الكتابة! راجع قواعد Firestore · تأكد أن platform_settings تسمح للأدمن بالكتابة.');
      } else {
        add('error', 'الكتابة في السحابة (المزامنة)', 'فشل: '+(e.message||e.code));
      }
    }
  } else {
    add('warn', 'الكتابة في السحابة (المزامنة)', 'لم يُختبر · يتطلب اتصالاً وصلاحية أدمن');
  }

  // 3.5) سلامة محتوى «جزء عم» · كشف الأسئلة الدخيلة المضافة عبر لوحة الأدمن
  try{
    const _JUZ_AMMA = new Set(['النبأ','النازعات','عبس','التكوير','الانفطار','المطففين','الانشقاق','البروج','الطارق','الأعلى','الغاشية','الفجر','البلد','الشمس','الليل','الضحى','الشرح','التين','العلق','القدر','البينة','الزلزلة','العاديات','القارعة','التكاثر','العصر','الهمزة','الفيل','قريش','الماعون','الكوثر','الكافرون','النصر','المسد','الإخلاص','الفلق','الناس']);
    const _norm = t => String(t||'').replace(/^سورة\s+/,'').replace(/^ال/,'').trim();
    const _JUZ_NORM = new Set([..._JUZ_AMMA].map(_norm));
    const _foreignHints = ['عروس القرآن','الرحمن','يس','الكهف','البقرة','الملك','الواقعة','مريم','يوسف','آل عمران','الفاتحة'];
    const juzQs = (typeof QDB!=='undefined' && QDB['جزء عم']) ? QDB['جزء عم'] : [];
    const intruders = [];
    juzQs.forEach(q=>{
      const ansOk = /\d/.test(String(q.a||'')) || _JUZ_NORM.has(_norm(q.a));
      const hint = _foreignHints.find(h => (q.q||'').includes(h) || (q.a||'').includes(h));
      if(!ansOk || hint) intruders.push((q.q||'').slice(0,40)+' ← '+(q.a||''));
    });
    if(juzQs.length === 0){
      add('warn', 'سلامة أسئلة «جزء عم»', 'الفئة فارغة أو لم تُحمَّل بعد');
    } else if(intruders.length === 0){
      add('ok', 'سلامة أسئلة «جزء عم»', 'كل الأسئلة ('+juzQs.length+') لسور من جزء عم فعلاً ✓');
    } else {
      add('error', 'سلامة أسئلة «جزء عم»', 'أسئلة دخيلة لسور ليست في جزء عم ('+intruders.length+'): '+intruders.join(' | ')+' · احذفها من «إدارة الأسئلة» ثم احفظ للسحابة.');
    }
  }catch(e){ add('warn','سلامة أسئلة «جزء عم»','تعذر الفحص: '+(e.message||e)); }

  // 4) قراءة التخصيصات من السحابة
  if(typeof db !== 'undefined' && db && !OFFLINE_MODE){
    try{
      const doc = await db.collection('platform_settings').doc('admin_customizations').get();
      if(doc.exists){
        const d = doc.data();
        const when = d.updated_at ? new Date(d.updated_at).toLocaleString('ar') : 'غير معروف';
        add('ok', 'التخصيصات في السحابة', 'موجودة. آخر تحديث: '+when);
      } else {
        add('warn', 'التخصيصات في السحابة', 'لا توجد تخصيصات محفوظة بعد. غيّر لوناً أو أخفِ فئة لإنشائها.');
      }
    }catch(e){
      add('error', 'التخصيصات في السحابة', 'فشل القراءة: '+(e.message||e.code));
    }
  }

  // 5) Service Worker (التخزين المؤقت)
  if('serviceWorker' in navigator){
    // الـ Service Worker يعمل فقط على https أو localhost
    const _proto = location.protocol;
    const _host = location.hostname;
    const _secure = (_proto === 'https:') || (_host === 'localhost') || (_host === '127.0.0.1');
    if(!_secure){
      add('warn', 'Service Worker', 'لا يعمل على هذا البروتوكول ('+_proto+'). يتطلب https. سيعمل تلقائياً على الموقع المباشر almulhimedu.org');
    } else {
      try{
        const regs = await navigator.serviceWorker.getRegistrations();
        if(regs.length > 0){
          add('ok', 'Service Worker', 'مفعّل · التحديثات تصل للمستخدمين');
        } else {
          // مسجّل غير موجود · نتحقق هل ملف sw.js موجود أصلاً على الخادم
          let swExists = false;
          try{
            const r = await fetch('/sw.js', {method:'HEAD', cache:'no-store'});
            swExists = r.ok;
          }catch(_){}
          if(swExists){
            add('warn', 'Service Worker', 'ملف sw.js موجود لكنه لم يُسجّل بعد. أعد تحميل الصفحة مرة واحدة لتفعيله.');
          } else {
            add('error', 'Service Worker', 'ملف sw.js غير موجود على الخادم! ارفع sw.js إلى جذر الموقع على Firebase ليعمل التحديث التلقائي.');
          }
        }
      }catch(e){ add('warn','Service Worker','تعذّر الفحص: '+(e.message||e.code||e)); }
    }
  } else {
    add('warn', 'Service Worker', 'المتصفح الحالي لا يدعم هذه الخاصية');
  }

  // 6) عدد الأسئلة المتاحة
  try{
    let qCount = 0;
    if(typeof QDB !== 'undefined') Object.keys(QDB).forEach(c => { qCount += (QDB[c]||[]).length; });
    if(qCount > 0) add('ok', 'بنك الأسئلة', qCount+' سؤال متاح');
    else add('warn', 'بنك الأسئلة', 'لم تُحمّل الأسئلة بعد');
  }catch(e){}

  // 7) صور الشركاء (هل في السحابة صور معطوبة؟)
  if(typeof db !== 'undefined' && db && !OFFLINE_MODE){
    try{
      const snap = await db.collection('admin_cat_images').get();
      let partnerImgs = 0;
      snap.forEach(doc => {
        const d = doc.data();
        if(d && d.cat && (d.cat.indexOf('بيرف آب')!==-1 || d.cat.indexOf('طموح')!==-1)) partnerImgs++;
      });
      if(partnerImgs > 0){
        add('warn', 'صور الشركاء في السحابة', partnerImgs+' صورة شريك قديمة قد تتعارض مع الشعار المدمج. استخدم زر "تنظيف صور الشركاء".');
      } else {
        add('ok', 'صور الشركاء', 'نظيفة · الشعار المدمج يظهر للجميع');
      }
    }catch(e){}
  }

  // 8) طبقة تعديلات الفئات الخارجية (الخرائط/الأعلام/العواصم/الأساطير/الشركاء)
  try{
    let extLocal = 0, extLocalCats = 0;
    if(typeof _hhLoadExtOverrides === 'function'){
      const ov = _hhLoadExtOverrides();
      Object.keys(ov).forEach(c => { if(Array.isArray(ov[c])){ extLocalCats++; extLocal += ov[c].length; } });
    }
    if(extLocalCats > 0){
      add('ok', 'تعديلات أسئلة الخرائط', extLocalCats+' فئة معدّلة ('+extLocal+' سؤال) محفوظة محلياً');
    } else {
      add('ok', 'تعديلات أسئلة الخرائط', 'لا تعديلات على فئات الخرائط · الأسئلة الأصلية');
    }
    if(typeof db !== 'undefined' && db && !OFFLINE_MODE){
      try{
        const snap = await db.collection('admin_qdb').doc('ext_overrides').get();
        if(snap.exists){
          const cloud = JSON.parse(snap.data().data||'{}');
          const cloudCats = Object.keys(cloud||{}).length;
          const when = snap.data().updatedAt && snap.data().updatedAt.toDate ? snap.data().updatedAt.toDate().toLocaleString('ar') : 'غير معروف';
          add('ok', 'تعديلات الخرائط في السحابة', cloudCats+' فئة منشورة للمستخدمين. آخر تحديث: '+when);
        } else if(extLocalCats > 0){
          add('warn', 'تعديلات الخرائط في السحابة', 'لديك تعديلات محلية لم تُنشر بعد للمستخدمين. افتح فئة خرائط واضغط حفظ وأنت أدمن متصل.');
        }
      }catch(e){ add('warn','تعديلات الخرائط في السحابة','تعذر الفحص: '+(e.message||e.code)); }
    }
  }catch(e){}

  // 9) إصدار النسخة وتوفّر تحديث (Service Worker)
  if('serviceWorker' in navigator){
    try{
      const reg = await navigator.serviceWorker.getRegistration();
      if(reg){
        try{ reg.update(); }catch(e){}
        if(reg.waiting){
          add('warn', 'تحديث متاح', 'يوجد نسخة جديدة جاهزة بانتظار التفعيل. أعد تحميل الصفحة أو اضغط «حدّث الآن» في الشريط.');
        } else if(reg.installing){
          add('ok', 'تحديث جارٍ', 'يجري تنزيل نسخة جديدة الآن...');
        } else {
          add('ok', 'إصدار المنصة', 'أنت على أحدث نسخة منشورة');
        }
      }
    }catch(e){}
  }

  // 10) دعم التخزين المحلي (مساحة المتصفح)
  try{
    let used = 0;
    for(let i=0;i<localStorage.length;i++){
      const k = localStorage.key(i);
      used += (k.length + (localStorage.getItem(k)||'').length);
    }
    const usedMB = (used/1024/1024).toFixed(2);
    if(used > 4.2*1024*1024){
      add('warn', 'مساحة المتصفح', 'الاستهلاك '+usedMB+' ميجابايت · قريب من الحد. قلّل حجم الصور المرفوعة بالأسئلة.');
    } else {
      add('ok', 'مساحة المتصفح', 'الاستهلاك '+usedMB+' ميجابايت · ضمن الحدود الآمنة');
    }
  }catch(e){}

  // ── فحص مصدر البيانات لكل فئة (يكشف تعارض الطبقات الثلاث) ──
  try{
    const extOv = (typeof _hhLoadExtOverrides==='function') ? (_hhLoadExtOverrides()||{}) : {};
    const overriddenCats = Object.keys(extOv);
    let conflicts = [];
    let heavyCats = [];
    overriddenCats.forEach(function(c){
      const ovArr = extOv[c]||[];
      const liveArr = (typeof QDB!=='undefined' && QDB[c])||[];
      const origArr = (typeof QDB_ORIGINAL!=='undefined' && QDB_ORIGINAL[c])||[];
      // تعارض: التجاوز موجود لكن الحي لا يطابقه
      if(ovArr.length && liveArr.length && ovArr.length !== liveArr.length){
        conflicts.push(c+' (تجاوز:'+ovArr.length+' / حي:'+liveArr.length+')');
      }
      const kb = Math.round(JSON.stringify(ovArr).length/1024);
      if(kb > 150) heavyCats.push(c+' ('+kb+'KB)');
    });
    const totalKB = Math.round(JSON.stringify(extOv).length/1024);

    if(!overriddenCats.length){
      add('ok','مصدر بيانات الفئات','كل الفئات تُقرأ من ملفاتها الأصلية · لا تجاوزات محفوظة');
    } else if(conflicts.length){
      add('error','مصدر بيانات الفئات','تعارض في '+conflicts.length+' فئة: '+conflicts.slice(0,3).join(' · ')+' · قد يرى الأدمن غير ما يراه المستخدمون. استعد الافتراضي لهذه الفئة ثم أعد التعديل.');
    } else {
      add('ok','مصدر بيانات الفئات', overriddenCats.length+' فئة معدّلة من لوحة التحكم ('+totalKB+'KB إجمالاً) · متطابقة مع النسخة الحية');
    }
    if(heavyCats.length){
      add('warn','فئات ثقيلة الصور','الفئات التالية كبيرة وقد تُعيق المزامنة: '+heavyCats.slice(0,3).join(' · ')+' · استخدم صوراً أصغر عند التعديل');
    }
    if(totalKB > 700){
      add('error','حجم التجاوزات','الإجمالي '+totalKB+'KB · تجاوز الحد الآمن (حد المستند 1MB). لن تُحفظ تعديلات جديدة حتى تخفّف الصور.');
    }
  }catch(e){}

  // عرض النتائج
  const icons = {ok:'', warn:'', error:''};
  const colors = {ok:'#3D6B53', warn:'#B8924A', error:'#c0392b'};
  const bgs = {ok:'#f0f7f3', warn:'#fdf8ee', error:'#fdf0ee'};
  const errCount = checks.filter(c=>c.status==='error').length;
  const warnCount = checks.filter(c=>c.status==='warn').length;

  let summary = '';
  if(errCount === 0 && warnCount === 0){
    summary = '<div style="background:#f0f7f3;border:2px solid #3D6B53;border-radius:12px;padding:16px;text-align:center;font-family:Cairo;font-weight:900;color:#3D6B53;margin-bottom:8px;"> المنصة بصحة ممتازة · لا أخطاء ولا نواقص</div>';
  } else {
    summary = '<div style="background:'+(errCount>0?'#fdf0ee':'#fdf8ee')+';border:2px solid '+(errCount>0?'#c0392b':'#B8924A')+';border-radius:12px;padding:16px;text-align:center;font-family:Cairo;font-weight:900;color:'+(errCount>0?'#c0392b':'#B8924A')+';margin-bottom:8px;">'+
      (errCount>0 ? ' '+errCount+' خطأ' : '')+(errCount>0&&warnCount>0?' و ':'')+(warnCount>0?' '+warnCount+' تنبيه':'')+' · راجع التفاصيل أدناه</div>';
  }

  box.innerHTML = summary + checks.map(c => '<div style="background:'+bgs[c.status]+';border-right:4px solid '+colors[c.status]+';border-radius:8px;padding:13px 16px;">'+
      '<div style="font-family:Cairo;font-weight:800;font-size:.9rem;color:'+colors[c.status]+';margin-bottom:3px;">'+icons[c.status]+' '+c.title+'</div>'+
      '<div style="font-size:.8rem;color:#555;line-height:1.5;">'+c.detail+'</div>'+
    '</div>' ).join('');
}

async function _hh_saveCustomizationsToCloud(){
  // تشخيص واضح لكل حالة فشل
  if(OFFLINE_MODE){ console.warn(' مزامنة: المنصة بوضع عدم الاتصال (OFFLINE_MODE)'); return false; }
  if(!db){ console.warn(' مزامنة: قاعدة البيانات (db) غير مهيأة'); return false; }
  if(!isAdminUser(currentUser)){ console.warn(' مزامنة: المستخدم الحالي ليس أدمن · لن يُحفظ. (currentUser=', currentUser && currentUser.email, ')'); return false; }
  try{
    const payload = {
      hidden_cats: _hh_getHiddenCats(),
      cat_colors: JSON.parse(localStorage.getItem('hh_cat_colors')||'{}'),
      custom_cats: JSON.parse(localStorage.getItem('hh_custom_cats')||'{}'),
      custom_groups: JSON.parse(localStorage.getItem('hh_custom_groups')||'[]'),
      sponsors_config: JSON.parse(localStorage.getItem('hh_sponsors_config')||'null'),
      landing_settings: JSON.parse(localStorage.getItem('hh_landing_settings')||'null'),
      path_services: JSON.parse(localStorage.getItem('hh_path_services')||'null'),
      activity_logo: localStorage.getItem('hh_activity_logo')||null,
      comp_config: JSON.parse(localStorage.getItem('hh_comp_config')||'null'),
      updated_at: Date.now()
    };
    await db.collection('platform_settings').doc('admin_customizations').set(payload);
    _hhLog(' مزامنة: حُفظت التخصيصات في السحابة بنجاح', payload.cat_colors);
    if(typeof toast === 'function') toast('✓ تمت المزامنة للسحابة','success');
    return true;
  }catch(e){
    console.error(' مزامنة: فشل الحفظ في السحابة ·', e.code || '', e.message);
    if(typeof toast === 'function'){
      if(e.code === 'permission-denied') toast('فشل المزامنة: الصلاحيات ترفض الكتابة','error');
      else toast('فشل المزامنة: '+e.message,'error');
    }
    return false;
  }
}

// تحميل تخصيصات الأدمن من السحابة (يستدعى لكل المستخدمين عند فتح الموقع)
async function loadCustomizationsFromCloud(){
  if(OFFLINE_MODE){ console.warn(' تحميل: وضع عدم الاتصال'); return; }
  if(!db){ console.warn(' تحميل: قاعدة البيانات غير مهيأة'); return; }
  try{
    const doc = await db.collection('platform_settings').doc('admin_customizations').get();
    if(!doc.exists){ console.warn(' تحميل: لا توجد تخصيصات في السحابة بعد (لم يحفظ الأدمن شيئاً)'); return; }
    const data = doc.data();
    if(!data){ console.warn(' تحميل: الوثيقة فارغة'); return; }
    _hhLog(' تحميل: وصلت التخصيصات من السحابة', data.cat_colors);
    // تطبيق الفئات المخفية
    if(Array.isArray(data.hidden_cats)){
      localStorage.setItem('hh_hidden_cats', JSON.stringify(data.hidden_cats));
    }
    // تطبيق ألوان الفئات
    if(data.cat_colors && typeof data.cat_colors === 'object'){
      localStorage.setItem('hh_cat_colors', JSON.stringify(data.cat_colors));
    }
    // تطبيق الفئات المخصّصة
    if(data.custom_cats && typeof data.custom_cats === 'object'){
      localStorage.setItem('hh_custom_cats', JSON.stringify(data.custom_cats));
    }
    // تطبيق المجموعات المخصّصة
    if(Array.isArray(data.custom_groups)){
      localStorage.setItem('hh_custom_groups', JSON.stringify(data.custom_groups));
    }
    // تطبيق إعدادات الشركاء/الرعاة
    if(data.sponsors_config && typeof data.sponsors_config === 'object'){
      localStorage.setItem('hh_sponsors_config', JSON.stringify(data.sponsors_config));
    }
    // تطبيق إعدادات صفحة الهبوط
    if(data.landing_settings && typeof data.landing_settings === 'object'){
      localStorage.setItem('hh_landing_settings', JSON.stringify(data.landing_settings));
    }
    // تطبيق خدمات المسارات (الأقسام المخفية/الظاهرة)
    if(data.path_services && typeof data.path_services === 'object'){
      localStorage.setItem('hh_path_services', JSON.stringify(data.path_services));
    }
    // تطبيق شعار الأنشطة
    if(data.activity_logo){
      localStorage.setItem('hh_activity_logo', data.activity_logo);
    }
    // تطبيق تخصيصات المسابقات
    if(data.comp_config && typeof data.comp_config === 'object'){
      localStorage.setItem('hh_comp_config', JSON.stringify(data.comp_config));
      try{ _hhApplyCompConfig(); }catch(e){}
    }
  }catch(e){
    console.warn('loadCustomizations cloud:', e.message);
  }
}

function _hh_safeDocId_partner(cat){ return encodeURIComponent(cat).replace(/%/g,'_'); }

// حفظ صورة مؤثر في السحابة (تصل لكل المستخدمين)
async function _hh_saveInfluencerImgToCloud(influencerId, dataUrl){
  if(OFFLINE_MODE || !db || !isAdminUser(currentUser)) return false;
  try{
    await db.collection('admin_influencer_images').doc(String(influencerId)).set({
      influencerId: String(influencerId),
      dataUrl: dataUrl,
      updated_at: Date.now()
    });
    return true;
  }catch(e){
    console.warn('saveInfluencerImg cloud:', e.message);
    return false;
  }
}

// تحميل صور المؤثرين من السحابة (لكل المستخدمين عند فتح الموقع)
