// تنظيف صور فئات الشركاء من السحابة والجهاز (ليظهر الشعار الأصلي من الكود للجميع)
async function cleanPartnerCloudImages(){
  if(!confirm('سيحذف هذا كل الصور المرفوعة لفئات الشركاء (بيرف آب وطموح) من السحابة، ليظهر الشعار الأصلي المدمج لجميع المستخدمين. متابعة؟')) return;
  // كل فئات الشركاء من CAT_INFO
  const partnerCats = Object.keys(CAT_INFO).filter(c => c.indexOf('بيرف آب')!==-1 || c.indexOf('طموح')!==-1);
  let cloudDeleted = 0, localDeleted = 0;
  for(const cat of partnerCats){
    // حذف محلي
    if(localStorage.getItem('cat_img_'+cat)){ localStorage.removeItem('cat_img_'+cat); localDeleted++; }
    // حذف سحابي
    if(!OFFLINE_MODE && db && isAdminUser()){
      try{
        await db.collection('admin_cat_images').doc(_hh_safeDocId(cat)).delete();
        cloudDeleted++;
      }catch(e){ console.warn('cloud img delete:', cat, e); }
    }
  }
  toast('تم التنظيف: '+cloudDeleted+' من السحابة، '+localDeleted+' من الجهاز. الشعار الأصلي سيظهر للجميع.','success');
  // إعادة رسم
  if(typeof renderAdminCategoriesList==='function') renderAdminCategoriesList();
  if(document.getElementById('screen-board') && document.getElementById('screen-board').classList.contains('active') && typeof G!=='undefined' && G.selectedCats && G.selectedCats.length){
    if(typeof buildBoard==='function') buildBoard();
  }
}

async function removeCatImg(cat){
  // حذف محلي
  localStorage.removeItem('cat_img_'+cat);
  
  // حذف سحابي
  if(!OFFLINE_MODE && db && isAdminUser()){
    try{
      await db.collection('admin_cat_images').doc(_hh_safeDocId(cat)).delete();
      toast('تم حذف الصورة من السحابة ومن الجهاز','info');
    }catch(e){
      console.warn('cloud img delete:', e);
      toast('حذفت محليا (فشل الحذف السحابي)','warn');
    }
  } else {
    toast('تم حذف الصورة المخصصة','info');
  }
  
  if(document.getElementById('screen-board').classList.contains('active') && G.selectedCats.length){
    buildBoard(); updateBoardUI();
  }
}
