// ════ من نحن · مربعات قابلة للفتح ════
function toggleAbout(id){
  // ════ التوافقية: للروابط القديمة، توجه للمربع الجديد إن وجد ════
  const oldToNew = {
    'about-why-inspiration':'why',
    'about-essence-content':'essence',
    'about-vision':'vision',
    'about-goals':'goals',
    'about-founder':'founder',
    'about-teacher':'teacher' };
  if(oldToNew[id]){
    const sq = document.querySelector('.about-square[data-asq="'+oldToNew[id]+'"]');
    if(sq){
      window.toggleAboutSquare(sq);
      return;
    }
  }
  // ════ النظام القديم (إن وجد) ════
  const detail = document.getElementById(id);
  if(!detail) return;
  const isOpen = detail.classList.contains('open');
  document.querySelectorAll('.about-detail').forEach(d=>d.classList.remove('open'));
  document.querySelectorAll('.about-toggle-card').forEach(c=>c.classList.remove('open'));
  if(!isOpen && detail){
    detail.classList.add('open');
    document.querySelectorAll('.about-toggle-card').forEach(c=>{
      if(c.getAttribute('onclick') && c.getAttribute('onclick').includes(id)){
        c.classList.add('open');
      }
    });
    detail.scrollIntoView({behavior:'smooth', block:'nearest'});
  }
}

// ═══════════════════════════════════════════════════════════
//  toggleAboutSquare · فتح/إغلاق مربعات قصتنا
// المربع الواحد يفتح محتواه داخله؛ يغلق الباقي تلقائيا
// ═══════════════════════════════════════════════════════════
window.toggleAboutSquare = function(sq){
  if(!sq) return;
  const wasOpen = sq.classList.contains('open');
  // إغلاق الكل
  document.querySelectorAll('.about-square.open').forEach(s => s.classList.remove('open'));
  // فتح المطلوب
  if(!wasOpen){
    sq.classList.add('open');
    setTimeout(() => sq.scrollIntoView({behavior:'smooth', block:'nearest'}), 200);
  }
};

// ═══════════════════════════════════════════════════════════
// anToggleCard · فتح/إغلاق بطاقات "من نحن" الجديدة
// ═══════════════════════════════════════════════════════════
window.anToggleCard = function(card){
  if(!card) return;
  const wasOpen = card.classList.contains('open');
  document.querySelectorAll('.an-card.open').forEach(c => c.classList.remove('open'));
  if(!wasOpen){
    card.classList.add('open');
    setTimeout(() => card.scrollIntoView({behavior:'smooth', block:'nearest'}), 220);
  }
};

// ════ إعادة اللعب مع تعديل أسماء الفرق ════
function toggleReplayTeams(){
  const box = document.getElementById('replay-teams');
  const confirmBtn = document.getElementById('replay-confirm-btn');
  const isHidden = box.style.display === 'none';
  box.style.display = isHidden ? 'block' : 'none';
  confirmBtn.style.display = isHidden ? 'block' : 'none';
  if(isHidden){
    const inputsDiv = document.getElementById('replay-team-inputs');
    inputsDiv.innerHTML = '';
    G.teams.forEach((name, i)=>{
      const wrap = document.createElement('div');
      wrap.style.cssText = 'display:flex;align-items:center;gap:8px;';
      wrap.innerHTML = `<span style="font-size:.8rem;font-weight:700;color:#8A1538;min-width:60px;">الفريق ${i+1}</span>
        <input type="text" id="replay-team-${i}" value="${esc(name)}"
          style="flex:1;padding:8px 12px;border:2px solid #8A1538;border-radius:8px;font-family:Tajawal,sans-serif;font-size:.9rem;text-align:center;">`;
      inputsDiv.appendChild(wrap);
    });
  }
}

function replayGame(){
  // تحديث أسماء الفرق
  G.teams.forEach((_, i)=>{
    const inp = document.getElementById('replay-team-'+i);
    if(inp && inp.value.trim()) G.teams[i] = inp.value.trim();
  });
  // حفظ الأسماء
  localStorage.setItem('hh_team_names', JSON.stringify(G.teams));
  // إعادة تهيئة اللعبة بنفس الإعدادات
  G.scores = G.teams.map(()=>0);
  G.turn = 0;
  G.answered = false;
  // إعادة بناء اللوح
  startGame(G.teams, G.selectedCats);
}
