// ════ رؤية كلمة السر ════
function togglePassVis(inputId, btnId){
  const inp = document.getElementById(inputId);
  const btn = document.getElementById(btnId);
  if(!inp) return;
  if(inp.type === 'password'){
    inp.type = 'text';
    if(btn) btn.innerHTML = '<svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M12 7c2.76 0 5 2.24 5 5 0 .65-.13 1.26-.36 1.83l2.92 2.92c1.51-1.26 2.7-2.89 3.43-4.75-1.73-4.39-6-7.5-11-7.5-1.4 0-2.74.25-3.98.7l2.16 2.16C10.74 7.13 11.35 7 12 7zM2 4.27l2.28 2.28.46.46C3.08 8.3 1.78 10.02 1 12c1.73 4.39 6 7.5 11 7.5 1.55 0 3.03-.3 4.38-.84l.42.42L19.73 22 21 20.73 3.27 3 2 4.27z"/></svg>';
  } else {
    inp.type = 'password';
    if(btn) btn.innerHTML = '<svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M12 4.5C7 4.5 2.73 7.61 1 12c1.73 4.39 6 7.5 11 7.5s9.27-3.11 11-7.5c-1.73-4.39-6-7.5-11-7.5zM12 17a5 5 0 110-10 5 5 0 010 10zm0-8a3 3 0 100 6 3 3 0 000-6z"/></svg>';
  }
}

// ════ تغيير كلمة السر ════
function toggleChangePass(){
  const form = document.getElementById('pf-pass-form');
  if(!form) return;
  const isHidden = form.style.display === 'none';
  form.style.display = isHidden ? 'block' : 'none';
  if(isHidden){
    document.getElementById('pf-pass-new').value = '';
    document.getElementById('pf-pass-confirm').value = '';
    document.getElementById('pf-pass-err').textContent = '';
  }
}

async function saveNewPass(){
  const newPass = document.getElementById('pf-pass-new').value;
  const confirm = document.getElementById('pf-pass-confirm').value;
  const errEl = document.getElementById('pf-pass-err');
  errEl.textContent = '';
  if(newPass.length < 6){ errEl.textContent = 'كلمة المرور 6 أحرف على الأقل'; return; }
  if(newPass !== confirm){ errEl.textContent = 'كلمتا المرور غير متطابقتين'; return; }
  if(OFFLINE_MODE){ errEl.textContent = 'غير متاح في الوضع المحلي'; return; }
  try{
    const user = auth.currentUser;
    if(!user){ errEl.textContent = 'يجب تسجيل الدخول أولا'; return; }
    await user.updatePassword(newPass);
    toggleChangePass();
    toast('تم تغيير كلمة المرور', 'success');
  } catch(e){
    if(e.code === 'auth/requires-recent-login'){
      errEl.textContent = 'لأمان حسابك، سجل الخروج ثم الدخول مجددا وحاول مرة أخرى';
    } else {
      errEl.textContent = 'حدث خطأ: ' + e.message;
    }
  }
}
