// ═══ تهيئة الشاشة عند الدخول ═══
function initActivityGen(){
  loadActivityTeacherData();
  selectActivityTemplate('worksheet');
  refreshDailyInspiration();
}

// ═══ فتح مولد الشهادات مباشرة (من خانة المعلم) ═══
function openCertificateDirect(){
  if(!hhCertAllowed()) return;
  showScreen('screen-activity-gen');
  // تأخير صغير حتى تتحمل الشاشة
  setTimeout(()=>{
    loadActivityTeacherData();
    selectActivityTemplate('certificate');
    refreshDailyInspiration();
    // تمرير صفحة المولد لقسم اختيار القالب
    setTimeout(()=>{
      const step3 = document.getElementById('ag-step3');
      if(step3) step3.scrollIntoView({behavior:'smooth', block:'start'});
    }, 200);
  }, 100);
}

// ═══ حفظ بيانات المعلم ═══
function saveActivityTeacherData(){
  const teacherName = document.getElementById('ag-teacher-name').value.trim();
  if(!teacherName){ toast('اكتب اسمك أولا', 'warn'); return; }
  try{
    localStorage.setItem('hh_activity_teacher', JSON.stringify({
      teacherName,
      schoolName: document.getElementById('ag-school-name').value.trim(),
      subject: document.getElementById('ag-subject').value.trim(),
      grade: document.getElementById('ag-grade').value.trim()
    }));
    if(ACTIVITY_GEN.logoDataUrl){
      localStorage.setItem('hh_activity_logo', ACTIVITY_GEN.logoDataUrl);
    }
    toast('✓ حفظت بياناتك · لن تكتبها مرة أخرى', 'success');
  }catch(e){ toast('الذاكرة ممتلئة', 'error'); }
}

function loadActivityTeacherData(){
  try{
    const saved = localStorage.getItem('hh_activity_teacher');
    if(saved){
      const data = JSON.parse(saved);
      document.getElementById('ag-teacher-name').value = data.teacherName || '';
      document.getElementById('ag-school-name').value = data.schoolName || '';
      document.getElementById('ag-subject').value = data.subject || '';
      document.getElementById('ag-grade').value = data.grade || '';
    }
    const savedLogo = localStorage.getItem('hh_activity_logo');
    if(savedLogo){
      ACTIVITY_GEN.logoDataUrl = savedLogo;
      const preview = document.getElementById('ag-logo-preview');
      if(preview) preview.innerHTML = `<img src="${savedLogo}" alt="شعار" style="max-width:60px;max-height:60px;border-radius:8px;">`;
      const label = document.getElementById('ag-logo-label');
      if(label) label.textContent = '✓ شعار المدرسة محفوظ';
      const removeBtn = document.getElementById('ag-logo-remove');
      if(removeBtn) removeBtn.style.display = 'inline-block';
    }
  }catch(e){}
}

// ═══ معاينة الشعار ═══
function previewActivityLogo(event){
  const file = event.target.files[0];
  if(!file) return;
  if(typeof toast==='function') toast('جار معالجة الشعار...', 'info');
  hhCompressImage(file, 200, 400).then(dataUrl => {
    ACTIVITY_GEN.logoDataUrl = dataUrl;
    document.getElementById('ag-logo-preview').innerHTML = `<img src="${dataUrl}" alt="معاينة الشعار" style="max-width:60px;max-height:60px;border-radius:8px;">`;
    document.getElementById('ag-logo-label').textContent = '✓ تم اختيار الشعار';
    document.getElementById('ag-logo-remove').style.display = 'inline-block';
    if(typeof toast==='function') toast('تم تحميل الشعار', 'success');
  }).catch(err => {
    if(typeof toast==='function') toast('فشل معالجة الصورة', 'error');
    console.error(err);
  });
}

function removeActivityLogo(){
  ACTIVITY_GEN.logoDataUrl = null;
  localStorage.removeItem('hh_activity_logo');
  document.getElementById('ag-logo-preview').innerHTML = `<svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="#3D6B53" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="2" ry="2"/><circle cx="8.5" cy="8.5" r="1.5"/><polyline points="21 15 16 10 5 21"/></svg>`;
  document.getElementById('ag-logo-label').textContent = 'ارفع شعار المدرسة (اختياري)';
  document.getElementById('ag-logo-remove').style.display = 'none';
  document.getElementById('ag-logo-input').value = '';
}

// ═══ اختيار القالب ═══
function selectActivityTemplate(template){
  ACTIVITY_GEN.currentTemplate = template;
  document.querySelectorAll('.ag-template-btn').forEach(btn => {
    const isSelected = btn.dataset.template === template;
    if(isSelected){
      btn.style.border = '2px solid #3D6B53';
      btn.style.background = 'linear-gradient(135deg,#e8f2ec,#fff)';
      const label = btn.querySelector('div:last-child');
      if(label){ label.style.color = '#2C5340'; label.style.fontWeight = '900'; }
    } else {
      btn.style.border = '1.5px solid #e0e8f0';
      btn.style.background = '#fafafa';
      const label = btn.querySelector('div:last-child');
      if(label){ label.style.color = '#555'; label.style.fontWeight = '800'; }
    }
  });
  renderActivityDetailsForm(template);
}

// ═══ حقول التفاصيل حسب القالب ═══
function renderActivityDetailsForm(template){
  const container = document.getElementById('ag-details-form');
  if(!container) return;
  if(template === 'worksheet'){
    container.innerHTML = `
      <input id="ag-ws-title" placeholder="عنوان النشاط (مثل: الحضارة الإسلامية)" style="width:100%;padding:10px;border:1.5px solid #dce5ea;border-radius:8px;font-family:Tajawal;font-size:.85rem;margin-bottom:8px;outline:none;box-sizing:border-box;">
      <textarea id="ag-ws-intro" placeholder="مقدمة قصيرة للنشاط (اختياري)" style="width:100%;padding:10px;border:1.5px solid #dce5ea;border-radius:8px;font-family:Tajawal;font-size:.82rem;margin-bottom:8px;resize:vertical;min-height:50px;outline:none;box-sizing:border-box;"></textarea>
      <label style="font-size:.78rem;font-weight:700;color:#8A1538;display:block;margin-bottom:6px;">الأسئلة (سؤال في كل سطر):</label>
      <textarea id="ag-ws-questions" placeholder="1. ما عاصمة الدولة الأموية؟&#10;2. متى بدأت الدولة العباسية؟&#10;3. اذكر ثلاثة من أشهر علماء الأندلس." style="width:100%;padding:10px;border:1.5px solid #dce5ea;border-radius:8px;font-family:Tajawal;font-size:.82rem;resize:vertical;min-height:120px;outline:none;box-sizing:border-box;"></textarea> `;
  } else if(template === 'quiz'){
    container.innerHTML = `
      <input id="ag-qz-title" placeholder="عنوان الاختبار" style="width:100%;padding:10px;border:1.5px solid #dce5ea;border-radius:8px;font-family:Tajawal;font-size:.85rem;margin-bottom:8px;outline:none;box-sizing:border-box;" value="اختبار قصير">
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:8px;">
        <input id="ag-qz-duration" placeholder="المدة (دقيقة)" type="number" value="20" style="padding:10px;border:1.5px solid #dce5ea;border-radius:8px;font-family:Tajawal;font-size:.85rem;outline:none;box-sizing:border-box;">
        <input id="ag-qz-total" placeholder="الدرجة الكلية" type="number" value="20" style="padding:10px;border:1.5px solid #dce5ea;border-radius:8px;font-family:Tajawal;font-size:.85rem;outline:none;box-sizing:border-box;">
      </div>
      <label style="font-size:.78rem;font-weight:700;color:#8A1538;display:block;margin-bottom:6px;">الأسئلة (الصيغة: السؤال؟ | الإجابة · في كل سطر):</label>
      <textarea id="ag-qz-items" placeholder="ما عاصمة قطر؟ | الدوحة&#10;من مؤسس قطر الحديثة؟ | الشيخ جاسم بن محمد&#10;متى استقلت قطر؟ | 1971" style="width:100%;padding:10px;border:1.5px solid #dce5ea;border-radius:8px;font-family:Tajawal;font-size:.82rem;resize:vertical;min-height:140px;outline:none;box-sizing:border-box;"></textarea>
      <div style="margin-top:8px;padding:8px;background:#f5faf7;border-radius:6px;font-size:.72rem;color:#2C5340;"> ستحصل أيضا على ملف PDF منفصل يحوي الإجابات (للمعلم فقط)
      </div> `;
  } else if(template === 'certificate'){
    container.innerHTML = `
      <!-- نوع الشهادة -->
      <label style="font-size:.78rem;font-weight:700;color:#8A1538;display:block;margin-bottom:6px;">نوع الشهادة:</label>
      <select id="ag-cert-type" onchange="onCertTypeChange()" style="width:100%;padding:10px;border:1.5px solid #dce5ea;border-radius:8px;font-family:Tajawal;font-size:.85rem;margin-bottom:10px;outline:none;background:#fff;box-sizing:border-box;">
        <option value="|شهادة تفوق|التفوق الدراسي والالتزام المتميز">شهادة تفوق</option>
        <option value="|شهادة تميز|التميز الأكاديمي والاجتهاد المستمر">شهادة تميز</option>
        <option value="|شهادة إنجاز|تحقيق إنجاز متميز">شهادة إنجاز</option>
        <option value="|شهادة تشجيع|الجهد المبذول والتطور الملحوظ"> شهادة تشجيع</option>
        <option value="|شهادة مشاركة|المشاركة الفاعلة في الأنشطة">شهادة مشاركة</option>
        <option value="|شهادة سلوك مثالي|السلوك المثالي وحسن الأخلاق"> شهادة سلوك مثالي</option>
        <option value="|شهادة قائد فصل|روح القيادة وحسن إدارة الفصل">شهادة قائد فصل</option>
        <option value="|شهادة باحث متميز|البحث والاستكشاف والإبداع"> شهادة باحث متميز</option>
        <option value="|شهادة قارئ نهم|الشغف بالقراءة والمعرفة"> شهادة قارئ نهم</option>
        <option value="|شهادة موهوب|الموهبة والإبداع المتميز">شهادة موهوب</option>
      </select>

      <!-- اسم الطالب + الصف -->
      <div style="display:grid;grid-template-columns:2fr 1fr;gap:10px;margin-bottom:8px;">
        <input id="ag-cert-student" placeholder="اسم الطالب/ة" style="padding:10px;border:1.5px solid #dce5ea;border-radius:8px;font-family:Tajawal;font-size:.85rem;outline:none;box-sizing:border-box;">
        <input id="ag-cert-class" placeholder="الفصل (اختياري)" style="padding:10px;border:1.5px solid #dce5ea;border-radius:8px;font-family:Tajawal;font-size:.85rem;outline:none;box-sizing:border-box;">
      </div>

      <!-- السبب + التقدير -->
      <input id="ag-cert-reason" placeholder="السبب" style="width:100%;padding:10px;border:1.5px solid #dce5ea;border-radius:8px;font-family:Tajawal;font-size:.85rem;margin-bottom:8px;outline:none;box-sizing:border-box;" value="التفوق الدراسي والالتزام المتميز">

      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:12px;">
        <input id="ag-cert-title" placeholder="عنوان الشهادة" style="padding:10px;border:1.5px solid #dce5ea;border-radius:8px;font-family:Tajawal;font-size:.85rem;outline:none;box-sizing:border-box;" value="شهادة تفوق">
        <input id="ag-cert-grade" placeholder="التقدير" style="padding:10px;border:1.5px solid #dce5ea;border-radius:8px;font-family:Tajawal;font-size:.85rem;outline:none;box-sizing:border-box;" value="ممتاز">
      </div>

      <!-- معلومات إضافية -->
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:12px;">
        <input id="ag-cert-year" placeholder="العام الدراسي (اختياري)" style="padding:10px;border:1.5px solid #dce5ea;border-radius:8px;font-family:Tajawal;font-size:.85rem;outline:none;box-sizing:border-box;" value="2025-2026">
        <input id="ag-cert-term" placeholder="الفصل/المناسبة (اختياري)" style="padding:10px;border:1.5px solid #dce5ea;border-radius:8px;font-family:Tajawal;font-size:.85rem;outline:none;box-sizing:border-box;">
      </div>

      <!-- التوقيعات الديناميكية -->
      <div style="background:#fafafa;border:1.5px solid #e0e8f0;border-radius:10px;padding:12px;">
        <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px;">
          <span style="font-family:Cairo;font-weight:900;color:#8A1538;font-size:.85rem;">التوقيعات</span>
          <span style="font-size:.7rem;color:#888;">يمنع تجاوز 4 توقيعات</span>
        </div>
        <div id="ag-cert-signatures-list" style="display:flex;flex-direction:column;gap:6px;margin-bottom:8px;">
          <!-- يملأ ديناميكيا -->
        </div>
        <button id="ag-cert-add-sig" onclick="addCertSignature()" style="width:100%;padding:8px;background:#e8f2ec;border:1.5px dashed #3D6B53;border-radius:8px;font-family:Cairo;font-weight:800;font-size:.78rem;color:#2C5340;cursor:pointer;">
          <svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M19 13h-6v6h-2v-6H5v-2h6V5h2v6h6v2z"/></svg> إضافة توقيع
        </button>
      </div>

      <!-- خيار إظهار توقيع المنصة -->
      <div style="margin-top:10px;padding:10px 12px;background:#fff8e8;border:1.5px solid #B8924A;border-radius:10px;">
        <label style="display:flex;align-items:center;gap:8px;cursor:pointer;font-family:Tajawal;font-size:.82rem;color:#8A6D2E;font-weight:700;">
          <input type="checkbox" id="ag-cert-show-platform" checked style="width:18px;height:18px;accent-color:#B8924A;cursor:pointer;">
          <span>إظهار "منصة الملهم · حيث يبدأ الإلهام" في الشهادة</span>
        </label>
      </div> `;
    // عبئ التوقيعات الافتراضية (المعلم بالاسم المحفوظ)
    initCertSignatures();
  }
}

// ═══ نوع الشهادة ═══
function onCertTypeChange(){
  const sel = document.getElementById('ag-cert-type');
  if(!sel) return;
  const parts = sel.value.split('|');
  if(parts.length === 3){
    const titleEl = document.getElementById('ag-cert-title');
    const reasonEl = document.getElementById('ag-cert-reason');
    if(titleEl) titleEl.value = parts[1];
    if(reasonEl) reasonEl.value = parts[2];
  }
}

// ═══ إدارة التوقيعات ═══
function initCertSignatures(){
  const list = document.getElementById('ag-cert-signatures-list');
  if(!list) return;
  // التوقيع الافتراضي: المعلم
  const teacherName = (document.getElementById('ag-teacher-name')||{}).value || '';
  list.innerHTML = '';
  addCertSignatureRow('المعلم', teacherName);
}

function addCertSignature(){
  const list = document.getElementById('ag-cert-signatures-list');
  if(!list) return;
  if(list.children.length >= 4){
    toast('الحد الأقصى 4 توقيعات', 'warn');
    return;
  }
  // اقتراحات شائعة بحسب الترتيب
  const suggestions = ['مدير المدرسة', 'موجه المادة', 'رئيس القسم', 'المشرف التربوي', 'ولي الأمر'];
  const used = Array.from(list.querySelectorAll('.sig-position-input')).map(i=>i.value.trim());
  const next = suggestions.find(s => !used.includes(s)) || '';
  addCertSignatureRow(next, '');
}

function addCertSignatureRow(position, name){
  const list = document.getElementById('ag-cert-signatures-list');
  if(!list) return;
  const row = document.createElement('div');
  row.style.cssText = 'display:grid;grid-template-columns:1fr 1.3fr auto;gap:6px;align-items:center;';
  row.innerHTML = `
    <input class="sig-position-input" placeholder="المنصب" value="${escAG(position)}" style="padding:8px;border:1.5px solid #dce5ea;border-radius:6px;font-family:Tajawal;font-size:.8rem;outline:none;box-sizing:border-box;">
    <input class="sig-name-input" placeholder="الاسم" value="${escAG(name)}" style="padding:8px;border:1.5px solid #dce5ea;border-radius:6px;font-family:Tajawal;font-size:.8rem;outline:none;box-sizing:border-box;">
    <button onclick="this.parentElement.remove()" style="padding:8px 10px;background:#fff;border:1.5px solid #c0392b;color:#c0392b;border-radius:6px;font-family:Cairo;font-weight:800;font-size:.7rem;cursor:pointer;">×</button> `;
  list.appendChild(row);
}

function getCertSignatures(){
  const list = document.getElementById('ag-cert-signatures-list');
  if(!list) return [];
  return Array.from(list.children).map(row => {
    const inputs = row.querySelectorAll('input');
    return {
      position: (inputs[0]?.value || '').trim(),
      name: (inputs[1]?.value || '').trim()
    };
  }).filter(s => s.position || s.name);
}

// ═══ جمع بيانات النشاط ═══
function collectActivityData(){
  const today = new Date().toLocaleDateString('ar-EG', { year:'numeric', month:'long', day:'numeric' });
  // الشعار: إما من ACTIVITY_GEN.logoDataUrl أو من المحفوظ
  let logo = ACTIVITY_GEN.logoDataUrl;
  if(!logo){
    try{ logo = localStorage.getItem('hh_activity_logo'); }catch(e){}
  }
  const common = {
    teacherName: document.getElementById('ag-teacher-name').value.trim(),
    schoolName: document.getElementById('ag-school-name').value.trim(),
    subject: document.getElementById('ag-subject').value.trim(),
    grade: document.getElementById('ag-grade').value.trim(),
    date: today,
    logo: logo
  };
  const tpl = ACTIVITY_GEN.currentTemplate;
  if(tpl === 'worksheet'){
    const questionsText = (document.getElementById('ag-ws-questions')||{}).value || '';
    return {
      ...common, template: 'worksheet',
      title: (document.getElementById('ag-ws-title')||{}).value || 'ورقة عمل',
      intro: (document.getElementById('ag-ws-intro')||{}).value || '',
      questions: questionsText.split('\n').map(q=>q.trim()).filter(q=>q)
    };
  } else if(tpl === 'quiz'){
    const itemsText = (document.getElementById('ag-qz-items')||{}).value || '';
    const items = itemsText.split('\n').map(line=>{
      const parts = line.split('|').map(p=>p.trim());
      return { q: parts[0]||'', a: parts[1]||'' };
    }).filter(x=>x.q);
    return {
      ...common, template: 'quiz',
      title: (document.getElementById('ag-qz-title')||{}).value || 'اختبار قصير',
      duration: (document.getElementById('ag-qz-duration')||{}).value || '20',
      total: (document.getElementById('ag-qz-total')||{}).value || '20',
      items
    };
  } else if(tpl === 'certificate'){
    const sel = document.getElementById('ag-cert-type');
    let icon = '<svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M19 5h-2V3H7v2H5c-1.1 0-2 .9-2 2v1c0 2.55 1.92 4.63 4.39 4.94A5.01 5.01 0 0011 15.9V19H7v2h10v-2h-4v-3.1A5.01 5.01 0 0016.61 12.94C19.08 12.63 21 10.55 21 8V7c0-1.1-.9-2-2-2zM5 8V7h2v3.82C5.84 10.4 5 9.3 5 8zm14 0c0 1.3-.84 2.4-2 2.82V7h2v1z"/></svg>';
    if(sel && sel.value){
      const parts = sel.value.split('|');
      if(parts.length === 3) icon = parts[0];
    }
    return {
      ...common, template: 'certificate',
      certIcon: icon,
      studentName: (document.getElementById('ag-cert-student')||{}).value || '',
      studentClass: (document.getElementById('ag-cert-class')||{}).value || '',
      reason: (document.getElementById('ag-cert-reason')||{}).value || '',
      certTitle: (document.getElementById('ag-cert-title')||{}).value || 'شهادة تفوق',
      certGrade: (document.getElementById('ag-cert-grade')||{}).value || 'ممتاز',
      academicYear: (document.getElementById('ag-cert-year')||{}).value || '',
      term: (document.getElementById('ag-cert-term')||{}).value || '',
      signatures: getCertSignatures(),
      showPlatform: !!(document.getElementById('ag-cert-show-platform')||{}).checked
    };
  }
}

function escAG(str){
  if(!str) return '';
  return String(str).replace(/[&<>"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
}

// ═══ توليد HTML للمعاينة والـ PDF ═══
function buildActivityHTML(data){
  const logoHtml = data.logo ? `<img src="${data.logo}" alt="شعار الشريك" style="max-width:70px;max-height:70px;object-fit:contain;">` : '';
  const metaHtml = `
    <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:20px;padding-bottom:14px;border-bottom:3px double #B8924A;">
      <div style="flex:1;font-family:Cairo,sans-serif;"> ${data.schoolName ? `<div style="font-size:16px;font-weight:900;color:#3D0918;margin-bottom:4px;">${escAG(data.schoolName)}</div>` : ''}
        ${data.subject ? `<div style="font-size:13px;color:#8A6D2E;font-weight:700;">${escAG(data.subject)}${data.grade?' · الصف '+escAG(data.grade):''}</div>` : ''}
        <div style="font-size:11px;color:#888;margin-top:4px;">${data.date}</div>
      </div>
      <div style="flex-shrink:0;">${logoHtml}</div>
    </div> `;

  if(data.template === 'worksheet'){
    const questionsHtml = data.questions.map(q => `
      <div style="margin-bottom:18px;padding-bottom:14px;border-bottom:1px dashed #ccc;">
        <div style="font-family:Cairo,sans-serif;font-weight:800;color:#8A1538;font-size:14px;margin-bottom:10px;">${escAG(q)}</div>
        <div style="height:60px;border:1px solid #e0e0e0;border-radius:4px;background:linear-gradient(#fafafa 1px, transparent 1px);background-size:100% 28px;"></div>
      </div> `).join('');
    return `
      <div style="font-family:Tajawal,sans-serif;padding:40px;direction:rtl;color:#1a1a2e;background:#fff;min-height:842px;"> ${metaHtml}
        <div style="text-align:center;margin:30px 0 24px;">
          <div style="display:inline-block;padding:10px 28px;background:linear-gradient(135deg,#3D0918,#8A1538);color:#D4BC85;font-family:Cairo,sans-serif;font-weight:900;font-size:20px;border-radius:10px;border:2px solid #B8924A;">${escAG(data.title)}</div>
        </div> ${data.intro ? `<div style="background:#fff8e8;border-right:4px solid #B8924A;padding:14px;border-radius:8px;margin-bottom:22px;font-size:13px;line-height:1.7;color:#555;">${escAG(data.intro)}</div>` : ''}
        <div style="margin-bottom:20px;">
          <div style="font-family:Cairo,sans-serif;font-weight:900;color:#8A1538;font-size:15px;margin-bottom:12px;">الاسم: _______________________</div>
        </div> ${questionsHtml}
        <div style="margin-top:40px;padding-top:14px;border-top:2px solid #B8924A;display:flex;justify-content:space-between;font-size:11px;color:#888;">
          <div>المعلم: ${escAG(data.teacherName || '')}</div>
          <div>منصة الملهم · حيث يبدأ الإلهام</div>
        </div>
      </div> `;
  } else if(data.template === 'quiz'){
    const itemsHtml = data.items.map((item, i) => `
      <div style="margin-bottom:16px;padding:12px;background:#fafafa;border-right:3px solid #8A1538;border-radius:6px;">
        <div style="font-family:Cairo,sans-serif;font-weight:800;color:#1a1a2e;font-size:14px;margin-bottom:8px;">س${i+1}: ${escAG(item.q)}</div>
        <div style="height:40px;border-bottom:1px dashed #aaa;"></div>
      </div> `).join('');
    return `
      <div style="font-family:Tajawal,sans-serif;padding:40px;direction:rtl;color:#1a1a2e;background:#fff;min-height:842px;"> ${metaHtml}
        <div style="text-align:center;margin:30px 0 24px;">
          <div style="display:inline-block;padding:10px 28px;background:linear-gradient(135deg,#4a0e1f,#8A1538);color:#fff;font-family:Cairo,sans-serif;font-weight:900;font-size:20px;border-radius:10px;border:2px solid #B8924A;">${escAG(data.title)}</div>
        </div>
        <div style="display:flex;justify-content:space-around;background:#fff8e8;padding:10px;border-radius:8px;margin-bottom:20px;font-family:Cairo,sans-serif;font-weight:800;font-size:12px;color:#8A6D2E;">
          <div>⏱ المدة: ${escAG(data.duration)} دقيقة</div>
          <div><svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M5 9.2h3v9H5zM10.6 5h2.8v13h-2.8zM16.2 13h2.8v5h-2.8z"/></svg> الدرجة: ${escAG(data.total)}</div>
          <div>عدد الأسئلة: ${data.items.length}</div>
        </div>
        <div style="margin-bottom:16px;padding:10px;background:#f5f5f5;border-radius:6px;font-family:Cairo,sans-serif;font-size:13px;">
          <strong>الاسم:</strong> _________________________
          <span style="float:left;"><strong>الدرجة:</strong> _____/${escAG(data.total)}</span>
        </div> ${itemsHtml}
        <div style="margin-top:40px;padding-top:14px;border-top:2px solid #B8924A;display:flex;justify-content:space-between;font-size:11px;color:#888;">
          <div>المعلم: ${escAG(data.teacherName || '')}</div>
          <div>منصة الملهم · حيث يبدأ الإلهام</div>
        </div>
      </div> `;
  } else if(data.template === 'certificate'){
    // التوقيعات: المعلم افتراضيا + التاريخ + توقيعات إضافية
    const sigs = (data.signatures && data.signatures.length > 0) ? data.signatures : [];
    const allSigs = sigs.length > 0 ? sigs : [{ position:'المعلم', name: data.teacherName || '' }];
    
    const sigsCount = allSigs.length;
    const sigFontSize = sigsCount >= 4 ? '11px' : sigsCount === 3 ? '12px' : '13px';
    const sigWidth = sigsCount >= 4 ? '120px' : sigsCount === 3 ? '140px' : '160px';
    
    const signaturesHTML = allSigs.map(s => `
      <div style="text-align:center;">
        <div style="width:${sigWidth};height:1.5px;background:linear-gradient(90deg,transparent,#8A6D2E,transparent);margin:0 auto 6px;"></div>
        <div style="font-family:Cairo,sans-serif;font-size:${sigFontSize};color:#3a230f;font-weight:900;line-height:1.4;">${escAG(s.position || '')}</div> ${s.name ? `<div style="font-family:Cairo,sans-serif;font-size:${sigFontSize};color:#8A6D2E;font-weight:700;margin-top:3px;">${escAG(s.name)}</div>` : ''}
      </div> `).join('');
    const dateColumn = `
      <div style="text-align:center;">
        <div style="width:${sigWidth};height:1.5px;background:linear-gradient(90deg,transparent,#8A6D2E,transparent);margin:0 auto 6px;"></div>
        <div style="font-family:Cairo,sans-serif;font-size:${sigFontSize};color:#3a230f;font-weight:900;">التاريخ</div>
        <div style="font-family:Cairo,sans-serif;font-size:${sigFontSize};color:#8A6D2E;font-weight:700;margin-top:3px;">${data.date}</div>
      </div> `;
    
    // ترويسة المدرسة الفاخرة (شريط رسمي)
    const schoolBanner = `
      <div style="display:flex;align-items:center;justify-content:space-between;padding:14px 24px;background:linear-gradient(135deg,#3D0918 0%,#8A1538 100%);border-radius:12px;border:2px solid #B8924A;margin-bottom:18px;box-shadow:0 4px 12px rgba(42,26,12,.2);">
        <!-- الشعار -->
        <div style="flex-shrink:0;width:64px;height:64px;background:#fff;border-radius:50%;display:flex;align-items:center;justify-content:center;border:2.5px solid #B8924A;box-shadow:0 2px 6px rgba(0,0,0,.15);"> ${data.logo 
            ? `<img src="${data.logo}" alt="شعار" style="max-width:50px;max-height:50px;object-fit:contain;border-radius:50%;">`
            : `<svg width="34" height="34" viewBox="0 0 24 24" fill="#8A1538"><path d="M12 3L1 9l4 2.18v6L12 21l7-3.82v-6l2-1.09V17h2V9L12 3zm6.82 6L12 12.72 5.18 9 12 5.28 18.82 9zM17 15.99l-5 2.73-5-2.73v-3.72L12 15l5-2.73v3.72z"/></svg>`
          }
        </div>
        <!-- اسم المدرسة في الوسط -->
        <div style="flex:1;text-align:center;padding:0 16px;">
          <div style="font-family:Cairo,sans-serif;font-weight:900;font-size:18px;color:#fff;letter-spacing:.3px;line-height:1.3;">${escAG(data.schoolName || 'مدرسة')}</div>
          <div style="font-family:Cairo,sans-serif;font-size:11px;color:#D4BC85;font-weight:600;margin-top:3px;letter-spacing:1px;">◆ المؤسسة التعليمية ◆</div>
        </div>
        <!-- المعلومات الأكاديمية -->
        <div style="flex-shrink:0;text-align:left;font-family:Cairo,sans-serif;"> ${data.academicYear ? `<div style="font-size:11px;color:#D4BC85;font-weight:800;background:rgba(212,188,133,.15);padding:3px 10px;border-radius:12px;border:1px solid rgba(212,188,133,.4);margin-bottom:4px;">العام ${escAG(data.academicYear)}</div>` : ''}
          ${data.term ? `<div style="font-size:10px;color:#d4cdb0;font-weight:700;text-align:center;">${escAG(data.term)}</div>` : ''}
        </div>
      </div> `;
    
    // اسم الطالب + الفصل
    const studentDisplay = data.studentClass
      ? `<div style="font-size:24px;font-weight:900;">${escAG(data.studentName || '________________')}</div><div style="font-size:13px;font-weight:700;color:#d4cdb0;margin-top:6px;letter-spacing:.5px;">${escAG(data.studentClass)}</div>`
      : `<div style="font-size:24px;font-weight:900;">${escAG(data.studentName || '________________')}</div>`;
    
    // رقم تسلسلي للشهادة (للأرشفة)
    const serialNumber = '#' + (Date.now().toString().slice(-6));

    return `
      <div style="font-family:Cairo,Tajawal,Arial,sans-serif;padding:30px 36px;direction:rtl;color:#1a1a2e;background:linear-gradient(135deg,#fffaf0 0%,#fef5e0 50%,#fffaf0 100%);min-height:560px;position:relative;border:14px double #B8924A;box-sizing:border-box;box-shadow:inset 0 0 80px rgba(184,146,74,.08);">
        
        <!-- زخارف الزوايا الكلاسيكية -->
        <div style="position:absolute;top:18px;right:18px;width:48px;height:48px;border-top:3px solid #B8924A;border-right:3px solid #B8924A;border-radius:6px 0 0 0;"></div>
        <div style="position:absolute;top:18px;left:18px;width:48px;height:48px;border-top:3px solid #B8924A;border-left:3px solid #B8924A;border-radius:0 6px 0 0;"></div>
        <div style="position:absolute;bottom:18px;right:18px;width:48px;height:48px;border-bottom:3px solid #B8924A;border-right:3px solid #B8924A;border-radius:0 0 0 6px;"></div>
        <div style="position:absolute;bottom:18px;left:18px;width:48px;height:48px;border-bottom:3px solid #B8924A;border-left:3px solid #B8924A;border-radius:0 0 6px 0;"></div>
        
        <!-- رقم تسلسلي (أعلى يمين) -->
        <div style="position:absolute;top:32px;right:30px;font-family:Cairo,sans-serif;font-size:10px;color:#8A6D2E;font-weight:700;letter-spacing:.5px;">${serialNumber}</div>
        
        <!-- ترويسة المدرسة الفاخرة -->
        <div style="margin-top:20px;">${schoolBanner}</div>
        
        <!-- العنوان الرئيسي للشهادة -->
        <div style="text-align:center;margin:18px 0 14px;">
          <div style="display:flex;align-items:center;justify-content:center;gap:18px;">
            <div style="width:50px;height:1.5px;background:linear-gradient(90deg,transparent,#B8924A);"></div>
            <div style="font-size:32px;line-height:1;">${data.certIcon || '<svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M19 5h-2V3H7v2H5c-1.1 0-2 .9-2 2v1c0 2.55 1.92 4.63 4.39 4.94A5.01 5.01 0 0011 15.9V19H7v2h10v-2h-4v-3.1A5.01 5.01 0 0016.61 12.94C19.08 12.63 21 10.55 21 8V7c0-1.1-.9-2-2-2zM5 8V7h2v3.82C5.84 10.4 5 9.3 5 8zm14 0c0 1.3-.84 2.4-2 2.82V7h2v1z"/></svg>'}</div>
            <div style="width:50px;height:1.5px;background:linear-gradient(90deg,#B8924A,transparent);"></div>
          </div>
          <div style="font-family:Cairo,sans-serif;font-weight:900;font-size:30px;color:#3D0918;letter-spacing:1.5px;margin-top:6px;text-shadow:1px 1px 2px rgba(184,146,74,.15);">${escAG(data.certTitle)}</div>
          <div style="display:flex;align-items:center;justify-content:center;gap:8px;margin-top:6px;">
            <div style="width:30px;height:1.5px;background:#B8924A;"></div>
            <div style="width:8px;height:8px;background:#B8924A;transform:rotate(45deg);border-radius:1px;"></div>
            <div style="width:30px;height:1.5px;background:#B8924A;"></div>
          </div>
        </div>
        
        <!-- نص التقديم -->
        <div style="text-align:center;font-size:14px;color:#555;margin:14px 0 10px;font-weight:500;font-style:italic;"> تمنح هذه الشهادة بكل فخر واعتزاز إلى الطالب/ة
        </div>
        
        <!-- اسم الطالب + الصف -->
        <div style="text-align:center;margin:12px 0;">
          <div style="display:inline-block;padding:14px 44px;background:linear-gradient(135deg,#3D0918 0%,#8A1538 50%,#3D0918 100%);color:#D4BC85;font-family:Cairo,sans-serif;border-radius:12px;border:2.5px solid #B8924A;letter-spacing:.5px;box-shadow:0 4px 12px rgba(42,26,12,.25);position:relative;"> ${studentDisplay}
          </div>
        </div>
        
        <!-- السبب -->
        <div style="text-align:center;font-size:13px;color:#333;margin:14px 50px;line-height:1.8;font-weight:600;"> تقديرا لـ <span style="color:#8A1538;font-weight:900;">${escAG(data.reason)}</span>
        </div>
        
        <!-- التقدير (وسام) -->
        <div style="text-align:center;margin:14px 0;">
          <div style="display:inline-block;padding:7px 24px;background:linear-gradient(135deg,#B8924A 0%,#a08316 50%,#B8924A 100%);color:#fff;font-family:Cairo,sans-serif;font-weight:900;font-size:15px;border-radius:8px;letter-spacing:.5px;box-shadow:0 3px 8px rgba(184,146,74,.4);border:1.5px solid #8A6D2E;"> التقدير: ${escAG(data.certGrade)} 
          </div>
        </div>
        
        <!-- التوقيعات + التاريخ -->
        <div style="display:flex;justify-content:space-around;align-items:flex-start;margin-top:28px;padding:0 20px;flex-wrap:wrap;gap:10px;"> ${signaturesHTML}
          ${dateColumn}
        </div>
        
        <!-- التذييل الفاخر (اختياري) --> ${data.showPlatform !== false ? `
        <div style="position:absolute;bottom:30px;left:0;right:0;text-align:center;">
          <div style="display:inline-flex;align-items:center;gap:6px;padding:4px 14px;background:rgba(184,146,74,.1);border-radius:20px;border:1px solid rgba(184,146,74,.3);">
            <span style="font-size:9px;color:#8A6D2E;font-weight:700;font-family:Cairo,sans-serif;">منصة الملهم</span>
            <span style="width:3px;height:3px;background:#B8924A;border-radius:50%;"></span>
            <span style="font-size:9px;color:#8A1538;font-weight:700;font-family:Cairo,sans-serif;">حيث يبدأ الإلهام</span>
          </div>
        </div> ` : ''}
      </div> `;
  }
  return '';
}

// ═══ المعاينة ═══
function previewActivity(){
  const data = collectActivityData();
  if(!data.teacherName){ toast('اكتب اسمك أولا في الخطوة 1', 'warn'); return; }
  document.getElementById('ag-preview-content').innerHTML = buildActivityHTML(data);
  document.getElementById('ag-preview-modal').style.display = 'block';
}

function closeActivityPreview(){
  document.getElementById('ag-preview-modal').style.display = 'none';
}

// ═══ تحميل PDF ═══
async function downloadActivityPDF(){
  const data = collectActivityData();
  if(!data.teacherName){ toast('اكتب اسمك أولا في الخطوة 1', 'warn'); return; }
  
  // تحميل html2pdf إن لم يكن محملا
  if(typeof html2pdf === 'undefined'){
    toast('جاري تحضير المكتبة...', 'info');
    try{
      await loadScript('https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.10.1/html2pdf.bundle.min.js');
    }catch(e){
      toast('تعذر تحميل المكتبة · تحقق من الإنترنت', 'error');
      return;
    }
  }
  
  toast('جاري إنتاج PDF...', 'info');

  const temp = document.createElement('div');
  temp.style.position = 'fixed';
  temp.style.left = '-9999px';
  temp.style.top = '0';
  temp.style.fontFamily = 'Cairo,Tajawal,Arial,sans-serif';
  temp.dir = 'rtl';
  temp.innerHTML = buildActivityHTML(data);
  document.body.appendChild(temp);

  try{
    const fileName = `${data.template === 'worksheet' ? 'ورقة_عمل' : data.template === 'quiz' ? 'اختبار' : 'شهادة'}_${Date.now()}.pdf`;
    
    await html2pdf().set({
      margin: 0,
      filename: fileName,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { 
        scale: 2.5,
        useCORS: true,
        backgroundColor: '#ffffff',
        letterRendering: true,
        allowTaint: true,
        logging: false
      },
      jsPDF: {
        unit: 'mm',
        format: 'a4',
        orientation: (data.template === 'certificate') ? 'landscape' : 'portrait',
        compress: true
      }
    }).from(temp).save();
    
    toast('✓ تم التحميل', 'success');

    //  حفظ في حقيبة المعلم تلقائيا
    saveToTeacherBag(data);

    if(data.template === 'quiz' && data.items.length > 0){
      setTimeout(()=>generateAnswerKey(data), 800);
    }
  }catch(err){
    console.error(err);
    toast('حدث خطأ · حاول مرة أخرى', 'error');
  }finally{
    if(temp.parentNode) document.body.removeChild(temp);
  }
}

async function generateAnswerKey(data){
  if(typeof html2pdf === 'undefined'){
    try{ await loadScript('https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.10.1/html2pdf.bundle.min.js'); }
    catch(e){ return; }
  }
  const answersHtml = data.items.map((item, i) => `
    <div style="margin-bottom:12px;padding:10px;background:#e8f2ec;border-right:3px solid #3D6B53;border-radius:6px;">
      <div style="font-family:Cairo,sans-serif;font-weight:800;color:#1a1a2e;font-size:13px;margin-bottom:4px;">س${i+1}: ${escAG(item.q)}</div>
      <div style="font-family:Cairo,sans-serif;font-weight:900;color:#2C5340;font-size:13px;">✓ الإجابة: ${escAG(item.a)}</div>
    </div> `).join('');
  const html = `
    <div style="font-family:Cairo,Tajawal,Arial,sans-serif;padding:30px;direction:rtl;color:#1a1a2e;background:#fff;min-height:842px;">
      <div style="text-align:center;padding:12px;background:#B8924A;color:#fff;font-family:Cairo,sans-serif;font-weight:900;font-size:18px;border-radius:8px;margin-bottom:20px;"> نموذج الإجابات · للمعلم فقط
      </div>
      <div style="text-align:center;font-family:Cairo,sans-serif;font-weight:900;color:#3D0918;font-size:16px;margin-bottom:16px;">${escAG(data.title)}</div> ${answersHtml}
    </div> `;
  const temp = document.createElement('div');
  temp.style.position = 'fixed';
  temp.style.left = '-9999px';
  temp.style.top = '0';
  temp.dir = 'rtl';
  temp.innerHTML = html;
  document.body.appendChild(temp);
  try{
    await html2pdf().set({
      margin: 0,
      filename: `نموذج_إجابات_${Date.now()}.pdf`,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { scale: 2.5, useCORS: true, backgroundColor: '#fff', letterRendering: true },
      jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
    }).from(temp).save();
    toast('✓ تم تحميل نموذج الإجابات', 'success');
  }catch(e){ console.error(e); }
  finally{ if(temp.parentNode) document.body.removeChild(temp); }
}

// ═══════════════════════════════════════════════════════════════════
//  المصحح الذكي · توفير ساعة كاملة من التصحيح اليدوي
// ═══════════════════════════════════════════════════════════════════

let GRADER_MODE = 'mcq'; // mcq | tf
let GRADER_RESULTS = null;

function initGrader(){
  // تعيين عدد الأسئلة الافتراضي
  const numEl = document.getElementById('gr-num-questions');
  if(numEl && !numEl.value) numEl.value = '10';
  rebuildAnswerKey();
  // إضافة طالب أول افتراضيا
  const list = document.getElementById('gr-students-list');
  if(list && list.children.length === 0){
    addGraderStudent();
  }
  // إخفاء قسم النتائج إن كان ظاهرا
  const res = document.getElementById('gr-results-section');
  if(res) res.style.display = 'none';
}

function setGraderMode(mode){
  GRADER_MODE = mode;
  document.querySelectorAll('.gr-mode-btn').forEach(b=>{
    b.classList.remove('gr-mode-active');
    b.style.background = '#fff';
    b.style.color = '#666';
    b.style.borderColor = '#dce5ea';
  });
  const active = document.getElementById('gr-mode-' + mode);
  if(active){
    active.classList.add('gr-mode-active');
    active.style.background = '#3D6B53';
    active.style.color = '#fff';
    active.style.borderColor = '#3D6B53';
  }
  rebuildAnswerKey();
  // إعادة بناء صفوف الطلاب
  document.querySelectorAll('.gr-student-row').forEach(row=>{
    const studentId = row.dataset.studentId;
    const nameInput = row.querySelector('.gr-student-name');
    const name = nameInput ? nameInput.value : '';
    rebuildStudentAnswers(row, name);
  });
}

function rebuildAnswerKey(){
  const num = parseInt(document.getElementById('gr-num-questions').value) || 10;
  const container = document.getElementById('gr-answer-key');
  if(!container) return;
  container.innerHTML = '';
  for(let i = 1; i <= num; i++){
    const wrap = document.createElement('div');
    wrap.style.cssText = 'background:#fff;border:1.5px solid #3D6B53;border-radius:8px;padding:6px;text-align:center;';
    let optionsHTML = '';
    if(GRADER_MODE === 'mcq'){
      ['أ','ب','ج','د'].forEach(opt=>{
        optionsHTML += `<option value="${opt}">${opt}</option>`;
      });
    } else {
      optionsHTML = `<option value="✓">صح</option><option value="✗">خطأ</option>`;
    }
    wrap.innerHTML = `
      <div style="font-family:Cairo;font-size:.7rem;font-weight:800;color:#2C5340;margin-bottom:4px;">س${i}</div>
      <select class="gr-key-select" data-q="${i}" style="width:100%;padding:5px;border:1px solid #3D6B53;border-radius:6px;font-family:Cairo;font-weight:800;font-size:.85rem;background:#fff;color:#8A1538;outline:none;">${optionsHTML}</select> `;
    container.appendChild(wrap);
  }
}

function getAnswerKey(){
  const key = {};
  document.querySelectorAll('.gr-key-select').forEach(sel=>{
    key[sel.dataset.q] = sel.value;
  });
  return key;
}

let _studentIdCounter = 0;
function addGraderStudent(name = ''){
  const list = document.getElementById('gr-students-list');
  if(!list) return;
  _studentIdCounter++;
  const row = document.createElement('div');
  row.className = 'gr-student-row';
  row.dataset.studentId = _studentIdCounter;
  row.style.cssText = 'background:#fff;border:1.5px solid #e0e8f0;border-radius:10px;padding:10px;';
  rebuildStudentAnswers(row, name);
  list.appendChild(row);
}

function rebuildStudentAnswers(row, name){
  const num = parseInt((document.getElementById('gr-num-questions')||{}).value || '10');
  let optionsAttr = '';
  if(GRADER_MODE === 'mcq'){
    optionsAttr = `<option value="">-</option><option value="أ">أ</option><option value="ب">ب</option><option value="ج">ج</option><option value="د">د</option>`;
  } else {
    optionsAttr = `<option value="">-</option><option value="✓">صح</option><option value="✗">خطأ</option>`;
  }
  let answersHTML = '';
  for(let i = 1; i <= num; i++){
    answersHTML += `
      <div style="background:#f9fbf9;border:1px solid #dce5ea;border-radius:6px;padding:4px;text-align:center;">
        <div style="font-size:.6rem;color:#666;font-weight:700;margin-bottom:2px;">${i}</div>
        <select class="gr-student-ans" data-q="${i}" style="width:100%;padding:3px;border:1px solid #dce5ea;border-radius:4px;font-family:Cairo;font-weight:700;font-size:.78rem;outline:none;background:#fff;">${optionsAttr}</select>
      </div> `;
  }
  row.innerHTML = `
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;">
      <input class="gr-student-name" placeholder="اسم الطالب/ة" value="${escAG(name)}" style="flex:1;padding:8px 10px;border:1.5px solid #dce5ea;border-radius:7px;font-family:Tajawal;font-size:.85rem;font-weight:700;outline:none;">
      <button onclick="this.closest('.gr-student-row').remove()" style="padding:6px 10px;background:#fff;color:#c0392b;border:1.5px solid #c0392b;border-radius:6px;font-family:Cairo;font-weight:900;font-size:.7rem;cursor:pointer;">حذف</button>
    </div>
    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(50px,1fr));gap:5px;"> ${answersHTML}
    </div> `;
}

function importStudentsFromClass(){
  // تحميل الفصول المحفوظة
  let classes = [];
  try{
    classes = JSON.parse(localStorage.getItem('hh_classes')||'[]');
  }catch(e){}
  if(classes.length === 0){
    toast('لا يوجد فصول محفوظة. أنشئ فصلا أولا من "فصولي"', 'warn');
    return;
  }
  // مودال اختيار الفصل
  const modalHTML = `
    <div id="gr-class-modal" style="position:fixed;inset:0;background:rgba(0,0,0,.7);z-index:1500;display:flex;align-items:center;justify-content:center;padding:20px;">
      <div style="background:#fff;border-radius:16px;padding:20px;max-width:420px;width:100%;border:2.5px solid #B8924A;box-shadow:0 20px 60px rgba(0,0,0,.3);max-height:80vh;overflow-y:auto;">
        <div style="font-family:Cairo;font-weight:900;font-size:1rem;color:#8A1538;margin-bottom:14px;text-align:center;">اختر فصلا لاستيراد طلابه</div>
        <div style="display:flex;flex-direction:column;gap:8px;"> ${classes.map((cls,i)=>`
            <button onclick="confirmImportClass(${i})" style="text-align:right;padding:12px;background:#f9fbf9;border:1.5px solid #3D6B53;border-radius:10px;cursor:pointer;font-family:Tajawal;">
              <div style="font-family:Cairo;font-weight:900;color:#2C5340;font-size:.9rem;">${escAG(cls.name||'فصل')}</div>
              <div style="font-size:.72rem;color:#666;margin-top:3px;">${(cls.students||[]).length} طالب</div>
            </button> `).join('')}
        </div>
        <button onclick="document.getElementById('gr-class-modal').remove()" style="margin-top:14px;width:100%;padding:9px;background:#fff;color:#c0392b;border:1.5px solid #c0392b;border-radius:8px;font-family:Cairo;font-weight:900;font-size:.82rem;cursor:pointer;">إلغاء</button>
      </div>
    </div> `;
  document.body.insertAdjacentHTML('beforeend', modalHTML);
}

function confirmImportClass(idx){
  let classes = [];
  try{
    classes = JSON.parse(localStorage.getItem('hh_classes')||'[]');
  }catch(e){}
  const cls = classes[idx];
  if(!cls) return;
  // مسح الطلاب الحاليين
  document.getElementById('gr-students-list').innerHTML = '';
  // إضافة الطلاب
  (cls.students || []).forEach(stu => {
    addGraderStudent(stu.name || stu);
  });
  // إغلاق المودال
  const modal = document.getElementById('gr-class-modal');
  if(modal) modal.remove();
  toast(`تم استيراد ${(cls.students||[]).length} طالب من "${cls.name||'الفصل'}"`, 'success');
}

function runGrader(){
  // 1) جمع البيانات
  const testName = (document.getElementById('gr-test-name')||{}).value || 'اختبار غير مسمى';
  const numQ = parseInt((document.getElementById('gr-num-questions')||{}).value || '10');
  const maxScore = parseFloat((document.getElementById('gr-max-score')||{}).value || '100');
  const passScore = parseFloat((document.getElementById('gr-pass-score')||{}).value || '50');
  const key = getAnswerKey();
  
  // 2) جمع إجابات الطلاب
  const studentRows = document.querySelectorAll('.gr-student-row');
  if(studentRows.length === 0){
    toast('أضف طالبا واحدا على الأقل', 'error');
    return;
  }
  
  const students = [];
  let validStudents = 0;
  studentRows.forEach(row => {
    const name = (row.querySelector('.gr-student-name')||{}).value || '';
    if(!name.trim()) return;
    const answers = {};
    row.querySelectorAll('.gr-student-ans').forEach(sel => {
      answers[sel.dataset.q] = sel.value;
    });
    students.push({ name: name.trim(), answers });
    validStudents++;
  });
  
  if(validStudents === 0){
    toast('أضف اسم طالب واحد على الأقل', 'error');
    return;
  }
  
  // 3) حساب النتائج
  const results = students.map(stu => {
    let correct = 0, wrong = 0, blank = 0;
    const detail = [];
    for(let i = 1; i <= numQ; i++){
      const studentAns = stu.answers[i];
      const correctAns = key[i];
      let status;
      if(!studentAns){ status = 'blank'; blank++; }
      else if(studentAns === correctAns){ status = 'correct'; correct++; }
      else { status = 'wrong'; wrong++; }
      detail.push({ q: i, studentAns, correctAns, status });
    }
    const score = numQ > 0 ? (correct / numQ) * maxScore : 0;
    const passed = score >= passScore;
    const percent = numQ > 0 ? Math.round((correct / numQ) * 100) : 0;
    return { ...stu, correct, wrong, blank, score, percent, passed, detail };
  });
  
  // 4) إحصائيات الفصل
  const classStats = {
    total: results.length,
    avgScore: results.reduce((s,r)=>s+r.score, 0) / results.length,
    passed: results.filter(r=>r.passed).length,
    highest: results.reduce((m,r)=>r.score>m.score?r:m, results[0]),
    lowest: results.reduce((m,r)=>r.score<m.score?r:m, results[0]),
  };
  
  // أصعب الأسئلة (أعلى نسبة خطأ)
  const questionStats = [];
  for(let i = 1; i <= numQ; i++){
    let wrongCount = 0;
    results.forEach(r => {
      if(r.detail[i-1].status === 'wrong') wrongCount++;
    });
    questionStats.push({ q: i, wrongCount, percent: Math.round((wrongCount/results.length)*100) });
  }
  questionStats.sort((a,b)=>b.wrongCount - a.wrongCount);
  
  // 5) حفظ النتائج
  GRADER_RESULTS = {
    testName, numQ, maxScore, passScore,
    key, students, results, classStats, questionStats,
    timestamp: new Date().toISOString()
  };
  
  // 6) عرض النتائج
  renderGraderResults();
}

function renderGraderResults(){
  if(!GRADER_RESULTS) return;
  const r = GRADER_RESULTS;
  
  // اظهار القسم
  document.getElementById('gr-results-section').style.display = 'block';
  document.getElementById('gr-summary-test-name').textContent = r.testName;
  
  // الإحصائيات العامة
  const stats = r.classStats;
  const avgPercent = Math.round((stats.avgScore / r.maxScore) * 100);
  const passRate = Math.round((stats.passed / stats.total) * 100);
  
  document.getElementById('gr-summary-stats').innerHTML = `
    <div style="background:#fff;border:1.5px solid #3D6B53;border-radius:10px;padding:10px;text-align:center;">
      <div style="font-size:.65rem;color:#666;font-weight:700;margin-bottom:3px;">عدد الطلاب</div>
      <div style="font-family:Cairo;font-weight:900;font-size:1.4rem;color:#8A1538;">${stats.total}</div>
    </div>
    <div style="background:#fff;border:1.5px solid #B8924A;border-radius:10px;padding:10px;text-align:center;">
      <div style="font-size:.65rem;color:#666;font-weight:700;margin-bottom:3px;">المتوسط</div>
      <div style="font-family:Cairo;font-weight:900;font-size:1.4rem;color:#8A6D2E;">${stats.avgScore.toFixed(1)}</div>
      <div style="font-size:.6rem;color:#999;">من ${r.maxScore}</div>
    </div>
    <div style="background:#fff;border:1.5px solid ${passRate>=70?'#3D6B53':passRate>=50?'#B8924A':'#c0392b'};border-radius:10px;padding:10px;text-align:center;">
      <div style="font-size:.65rem;color:#666;font-weight:700;margin-bottom:3px;">نسبة النجاح</div>
      <div style="font-family:Cairo;font-weight:900;font-size:1.4rem;color:${passRate>=70?'#3D6B53':passRate>=50?'#8A6D2E':'#c0392b'};">${passRate}%</div>
    </div>
    <div style="background:#fff;border:1.5px solid #3D6B53;border-radius:10px;padding:10px;text-align:center;">
      <div style="font-size:.65rem;color:#666;font-weight:700;margin-bottom:3px;">الأعلى</div>
      <div style="font-family:Cairo;font-weight:900;font-size:.95rem;color:#8A1538;line-height:1.2;">${escAG(stats.highest.name)}</div>
      <div style="font-size:.7rem;color:#2C5340;font-weight:800;margin-top:2px;">${stats.highest.score.toFixed(1)}</div>
    </div> `;
  
  // قائمة نتائج الطلاب
  const list = document.getElementById('gr-students-results');
  list.innerHTML = '<div style="font-family:Cairo;font-weight:900;color:#8A1538;margin:10px 0 6px;font-size:.92rem;">نتائج الطلاب</div>';
  
  // ترتيب من الأعلى للأدنى
  const sortedResults = [...r.results].sort((a,b)=>b.score - a.score);
  
  sortedResults.forEach((stu,idx) => {
    const color = stu.passed ? '#3D6B53' : '#c0392b';
    const bg = stu.passed ? '#f0f9f4' : '#fdecea';
    const detailsHTML = stu.detail.map(d => {
      const symbol = d.status === 'correct' ? '✓' : d.status === 'wrong' ? '<svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M19 6.41L17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12z"/></svg>' : '−';
      const dColor = d.status === 'correct' ? '#3D6B53' : d.status === 'wrong' ? '#c0392b' : '#999';
      return `<span style="display:inline-block;width:24px;height:24px;line-height:24px;text-align:center;border-radius:5px;background:#fff;color:${dColor};border:1.5px solid ${dColor};font-family:Cairo;font-weight:900;font-size:.78rem;margin:1px;" title="س${d.q}: ${d.studentAns||'فارغ'} / الصحيح: ${d.correctAns}">${d.q}</span>`;
    }).join('');
    
    list.innerHTML += `
      <div style="background:${bg};border:1.5px solid ${color};border-radius:10px;padding:10px;">
        <div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px;margin-bottom:8px;">
          <div style="display:flex;align-items:center;gap:8px;">
            <div style="width:24px;height:24px;background:${color};color:#fff;border-radius:50%;display:flex;align-items:center;justify-content:center;font-family:Cairo;font-weight:900;font-size:.7rem;">${idx+1}</div>
            <div style="font-family:Cairo;font-weight:900;color:${color};font-size:.92rem;">${escAG(stu.name)}</div>
          </div>
          <div style="display:flex;align-items:center;gap:8px;">
            <div style="font-family:Cairo;font-weight:900;font-size:1rem;color:${color};">${stu.score.toFixed(1)} / ${r.maxScore}</div>
            <div style="background:${color};color:#fff;padding:3px 9px;border-radius:8px;font-family:Cairo;font-weight:900;font-size:.7rem;">${stu.percent}%</div>
            <div style="background:#fff;color:${color};border:1.5px solid ${color};padding:3px 9px;border-radius:8px;font-family:Cairo;font-weight:900;font-size:.68rem;">${stu.passed?'ناجح':'راسب'}</div>
          </div>
        </div>
        <div style="display:flex;flex-wrap:wrap;align-items:center;gap:2px;">
          <span style="font-size:.7rem;color:#666;font-weight:700;margin-left:6px;">✓ ${stu.correct}</span>
          <span style="font-size:.7rem;color:#666;font-weight:700;margin-left:6px;"><svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M19 6.41L17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12z"/></svg> ${stu.wrong}</span> ${stu.blank>0?`<span style="font-size:.7rem;color:#666;font-weight:700;margin-left:6px;">− ${stu.blank}</span>`:''}
          <div style="margin-right:auto;">${detailsHTML}</div>
        </div>
      </div> `;
  });
  
  // الأسئلة الأصعب
  if(r.questionStats[0] && r.questionStats[0].wrongCount > 0){
    list.innerHTML += `<div style="margin-top:14px;padding:10px;background:#fff8e8;border:1.5px solid #B8924A;border-radius:10px;">
      <div style="font-family:Cairo;font-weight:900;color:#8A6D2E;font-size:.85rem;margin-bottom:6px;"><svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M1 21h22L12 2 1 21zm12-3h-2v-2h2v2zm0-4h-2v-4h2v4z"/></svg> أصعب الأسئلة (راجعها مع الطلاب)</div>
      <div style="display:flex;flex-wrap:wrap;gap:6px;"> ${r.questionStats.slice(0,5).filter(q=>q.wrongCount>0).map(q=>`
          <div style="background:#fff;border:1.5px solid #8A6D2E;color:#8A6D2E;padding:4px 9px;border-radius:7px;font-family:Cairo;font-weight:800;font-size:.72rem;">س${q.q} (${q.percent}% خطأ)</div> `).join('')}
      </div>
    </div>`;
  }
  
  // التمرير لقسم النتائج
  setTimeout(()=>{
    document.getElementById('gr-results-section').scrollIntoView({behavior:'smooth', block:'start'});
  }, 200);
}

// ════════════════════════════════════════════════════════════════════
//  نظام إدارة الفصول والطلاب (ClassRoom Management)
// ════════════════════════════════════════════════════════════════════
// يخزن البيانات في localStorage تحت 'hh_classes' و'hh_class_students'
// كل فصل: {id, name, grade, subject, color, createdAt}
// كل طالب: {id, classId, name, number, guardian, createdAt}

const CLASS_COLORS = ['#3D6B53','#8A1538','#8A1538','#1F4E79','#7a5c2e','#5a3a8e','#B8924A','#3D6B53'];
let _hh_currentClassId = null;

function _hh_getClasses(){
  try{ return JSON.parse(localStorage.getItem('hh_classes')||'[]'); }
  catch(e){ return []; }
}
function _hh_saveClasses(arr){
  localStorage.setItem('hh_classes', JSON.stringify(arr));
}
function _hh_getStudents(classId){
  try{
    const all = JSON.parse(localStorage.getItem('hh_class_students')||'[]');
    return classId ? all.filter(s=>s.classId===classId) : all;
  }catch(e){ return []; }
}
function _hh_saveStudents(arr){
  localStorage.setItem('hh_class_students', JSON.stringify(arr));
}
function _hh_genId(prefix){
  return prefix+'_'+Date.now()+'_'+Math.random().toString(36).slice(2,8);
}
function getCurrentClassId(){
  return _hh_currentClassId;
}

/** عرض قائمة الفصول في شاشة الفصول */
function renderClassesList(){
  const classes = _hh_getClasses();
  const list = document.getElementById('classes-list');
  const stats = document.getElementById('classes-stats');
  if(!list) return;

  // إحصائيات
  if(stats){
    const allStudents = _hh_getStudents();
    if(classes.length === 0){
      stats.innerHTML = 'لم تنشئ فصلا بعد · ابدأ بإضافة فصلك الأول';
    } else {
      stats.innerHTML = '<span style="color:#D4BC85;">'+classes.length.toLocaleString('en-US')+'</span> فصل · <span style="color:#D4BC85;">'+allStudents.length.toLocaleString('en-US')+'</span> طالب';
    }
  }

  if(classes.length === 0){
    list.innerHTML = '<div style="background:#fff;border-radius:14px;padding:30px 20px;text-align:center;color:#888;border:1.5px dashed #dce5ea;"><div style="font-size:2rem;margin-bottom:10px;"></div><div style="font-family:Cairo;font-weight:900;color:#8A1538;margin-bottom:6px;">ابدأ بإنشاء فصلك الأول</div><div style="font-size:.82rem;line-height:1.6;">اضغط على زر <strong>"فصل جديد"</strong> في الأعلى لإضافة فصلك الأول، ثم أضف طلابك واحدا واحدا أو ألصق قائمة كاملة من Excel.</div></div>';
    return;
  }

  list.innerHTML = '';
  classes.forEach(cls => {
    const studentCount = _hh_getStudents(cls.id).length;
    const card = document.createElement('div');
    card.style.cssText = 'background:#fff;border-radius:14px;padding:14px 16px;margin-bottom:10px;border-right:5px solid '+(cls.color||'#3D6B53')+';box-shadow:0 2px 8px rgba(0,0,0,.05);cursor:pointer;transition:transform .15s,box-shadow .15s;display:flex;align-items:center;justify-content:space-between;gap:10px;';
    card.onmouseover = ()=>{ card.style.transform='translateY(-2px)'; card.style.boxShadow='0 6px 18px rgba(0,0,0,.08)'; };
    card.onmouseout = ()=>{ card.style.transform=''; card.style.boxShadow='0 2px 8px rgba(0,0,0,.05)'; };
    card.onclick = ()=>openClassDetail(cls.id);
    const subjectLine = cls.subject ? ('<span style="color:#888;font-size:.78rem;">'+esc(cls.subject)+'</span>') : '';
    const gradeLine = cls.grade ? ('<span style="background:'+(cls.color||'#3D6B53')+'15;color:'+(cls.color||'#3D6B53')+';padding:2px 8px;border-radius:10px;font-size:.72rem;font-weight:900;">'+esc(cls.grade)+'</span>') : '';
    card.innerHTML = '<div style="flex:1;min-width:0;"><div style="font-family:Cairo;font-weight:900;color:#3D0918;font-size:1rem;margin-bottom:4px;">'+esc(cls.name||'فصل بلا اسم')+'</div><div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">'+gradeLine+subjectLine+'</div></div><div style="text-align:center;flex-shrink:0;"><div style="font-family:Cairo;font-weight:900;font-size:1.2rem;color:'+(cls.color||'#3D6B53')+';">'+studentCount.toLocaleString('en-US')+'</div><div style="font-size:.68rem;color:#888;">طالب</div></div><svg width="20" height="20" viewBox="0 0 24 24" fill="#bbb" style="flex-shrink:0;transform:scaleX(-1);"><path d="M10 6L8.59 7.41 13.17 12l-4.58 4.59L10 18l6-6z"/></svg>';
    list.appendChild(card);
  });
}

/** فتح تفاصيل فصل معين */
function openClassDetail(classId){
  _hh_currentClassId = classId;
  const cls = _hh_getClasses().find(c=>c.id===classId);
  if(!cls){ toast('الفصل غير موجود','error'); return; }

  // عنوان الشاشة
  const title = document.getElementById('class-detail-title');
  if(title) title.textContent = cls.name || 'الفصل';

  // بطاقة معلومات الفصل
  const info = document.getElementById('class-info-card');
  if(info){
    const items = [];
    if(cls.grade) items.push('<span style="background:#f5faf7;color:#2C5340;padding:4px 10px;border-radius:10px;font-weight:900;font-size:.78rem;">'+esc(cls.grade)+'</span>');
    if(cls.subject) items.push('<span style="background:#F8F8F6;color:#8A6D2E;padding:4px 10px;border-radius:10px;font-weight:900;font-size:.78rem;">'+esc(cls.subject)+'</span>');
    info.innerHTML = '<div style="font-family:Cairo;font-weight:900;font-size:1.1rem;color:#3D0918;margin-bottom:8px;">'+esc(cls.name)+'</div><div style="display:flex;gap:6px;flex-wrap:wrap;">'+items.join('')+'</div>';
  }
  renderStudentsList();
  // تبديل الشاشة
  if(typeof go === 'function'){ go('screen-class-detail'); }
  else {
    document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));
    document.getElementById('screen-class-detail')?.classList.add('active');
  }
}

/** عرض قائمة الطلاب في الفصل الحالي */
function renderStudentsList(){
  const list = document.getElementById('students-list');
  if(!list || !_hh_currentClassId) return;
  const search = (document.getElementById('students-search')?.value || '').trim().toLowerCase();
  let students = _hh_getStudents(_hh_currentClassId);
  if(search){
    students = students.filter(s => (s.name||'').toLowerCase().includes(search) ||
      (s.number||'').toLowerCase().includes(search)
    );
  }
  if(students.length === 0){
    list.innerHTML = '<div style="background:#fff;border-radius:14px;padding:24px;text-align:center;color:#888;border:1.5px dashed #dce5ea;"><div style="font-size:1.6rem;margin-bottom:8px;"></div><div style="font-family:Cairo;font-weight:900;color:#8A1538;font-size:.92rem;margin-bottom:4px;">'+(search?'لم يعثر على طالب':'لا يوجد طلاب بعد')+'</div><div style="font-size:.78rem;">'+(search?'جرب بحثا آخر':'اضغط "إضافة طالب" أو "استيراد قائمة"')+'</div></div>';
    return;
  }
  list.innerHTML = '';
  // ترتيب أبجدي
  students.sort((a,b)=>(a.name||'').localeCompare(b.name||'','ar'));
  students.forEach((s, idx) => {
    const card = document.createElement('div');
    card.style.cssText = 'background:#fff;border-radius:10px;padding:10px 14px;margin-bottom:8px;border:1.5px solid #ecf0f1;display:flex;align-items:center;justify-content:space-between;gap:10px;cursor:pointer;transition:border-color .15s;';
    card.onmouseover = ()=>{ card.style.borderColor='#3D6B53'; };
    card.onmouseout = ()=>{ card.style.borderColor='#ecf0f1'; };
    card.onclick = ()=>openStudentEditor(s.id);
    const numberBadge = s.number ? ('<span style="background:#f5faf7;color:#2C5340;padding:2px 7px;border-radius:8px;font-size:.7rem;font-weight:900;">#'+esc(s.number)+'</span>') : '';
    const guardianLine = s.guardian ? ('<div style="font-size:.7rem;color:#888;margin-top:2px;"> '+esc(s.guardian)+'</div>') : '';
    card.innerHTML = '<div style="background:linear-gradient(135deg,#3D6B53,#2C5340);color:#fff;width:32px;height:32px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:900;flex-shrink:0;">'+(idx+1).toLocaleString('en-US')+'</div><div style="flex:1;min-width:0;"><div style="font-family:Cairo;font-weight:800;color:#3D0918;font-size:.92rem;display:flex;align-items:center;gap:6px;flex-wrap:wrap;">'+esc(s.name||'طالب')+numberBadge+'</div>'+guardianLine+'</div><svg width="16" height="16" viewBox="0 0 24 24" fill="#bbb" style="flex-shrink:0;"><path d="M3 17.25V21h3.75L17.81 9.94l-3.75-3.75L3 17.25zM20.71 7.04c.39-.39.39-1.02 0-1.41l-2.34-2.34c-.39-.39-1.02-.39-1.41 0l-1.83 1.83 3.75 3.75 1.83-1.83z"/></svg>';
    list.appendChild(card);
  });
}

function filterStudents(){ renderStudentsList(); }

/** فتح محرر فصل (جديد أو تعديل) */
function openClassEditor(classId){
  const modal = document.getElementById('class-editor-modal');
  if(!modal) return;
  const isEdit = !!classId;
  document.getElementById('class-editor-title').textContent = isEdit ? 'تعديل الفصل' : 'فصل جديد';
  document.getElementById('class-edit-id').value = classId || '';
  const delBtn = document.getElementById('class-delete-btn');
  if(delBtn) delBtn.style.display = isEdit ? 'block' : 'none';

  // ألوان الفصل
  const colorsWrap = document.getElementById('class-colors');
  if(colorsWrap){
    colorsWrap.innerHTML = '';
    let selectedColor = '#3D6B53';
    if(isEdit){
      const cls = _hh_getClasses().find(c=>c.id===classId);
      if(cls){
        document.getElementById('class-name').value = cls.name || '';
        document.getElementById('class-grade').value = cls.grade || '';
        document.getElementById('class-subject').value = cls.subject || '';
        selectedColor = cls.color || '#3D6B53';
      }
    } else {
      document.getElementById('class-name').value = '';
      document.getElementById('class-grade').value = '';
      document.getElementById('class-subject').value = '';
    }
    CLASS_COLORS.forEach(c => {
      const sw = document.createElement('button');
      sw.type = 'button';
      sw.dataset.color = c;
      sw.style.cssText = 'width:32px;height:32px;border-radius:50%;border:'+(c===selectedColor?'3px solid #3D0918':'2px solid #fff')+';background:'+c+';cursor:pointer;box-shadow:0 1px 4px rgba(0,0,0,.15);transition:transform .15s;';
      sw.onclick = ()=>{
        colorsWrap.querySelectorAll('button').forEach(b=>b.style.border='2px solid #fff');
        sw.style.border = '3px solid #3D0918';
      };
      colorsWrap.appendChild(sw);
    });
  }
  modal.style.display = 'flex';
}

function closeClassEditor(){
  const m = document.getElementById('class-editor-modal');
  if(m) m.style.display = 'none';
}

function saveClass(){
  const id = document.getElementById('class-edit-id').value || _hh_genId('cls');
  const name = (document.getElementById('class-name').value||'').trim();
  if(!name){ toast('اسم الفصل مطلوب','error'); return; }
  const grade = (document.getElementById('class-grade').value||'').trim();
  const subject = (document.getElementById('class-subject').value||'').trim();
  // اللون المختار
  let color = '#3D6B53';
  document.querySelectorAll('#class-colors button').forEach(b => {
    if(b.style.border.includes('3px')) color = b.dataset.color;
  });

  const classes = _hh_getClasses();
  const idx = classes.findIndex(c=>c.id===id);
  const obj = {id, name, grade, subject, color, createdAt: idx>=0 ? classes[idx].createdAt : Date.now()};
  if(idx>=0) classes[idx] = obj;
  else classes.unshift(obj);
  _hh_saveClasses(classes);
  closeClassEditor();
  toast('تم حفظ الفصل','success');
  // تحديث العرض
  if(_hh_currentClassId === id) openClassDetail(id);
  renderClassesList();
}

function deleteClass(){
  const id = document.getElementById('class-edit-id').value;
  if(!id) return;
  const cls = _hh_getClasses().find(c=>c.id===id);
  if(!cls) return;
  if(!confirm('حذف فصل "'+(cls.name||'')+'" مع كل طلابه؟ لا يمكن التراجع.')) return;
  // حذف الفصل
  const classes = _hh_getClasses().filter(c=>c.id!==id);
  _hh_saveClasses(classes);
  // حذف طلاب الفصل
  const students = _hh_getStudents().filter(s=>s.classId!==id);
  _hh_saveStudents(students);
  closeClassEditor();
  toast('تم حذف الفصل','info');
  // الرجوع لقائمة الفصول
  if(_hh_currentClassId === id){
    _hh_currentClassId = null;
    if(typeof go === 'function'){ go('screen-classes'); }
  }
  renderClassesList();
}

/** فتح محرر طالب */
function openStudentEditor(studentId){
  if(!_hh_currentClassId){ toast('اختر فصلا أولا','error'); return; }
  const modal = document.getElementById('student-editor-modal');
  if(!modal) return;
  const isEdit = !!studentId;
  document.getElementById('student-editor-title').textContent = isEdit ? 'تعديل طالب' : 'طالب جديد';
  document.getElementById('student-edit-id').value = studentId || '';
  const delBtn = document.getElementById('student-delete-btn');
  if(delBtn) delBtn.style.display = isEdit ? 'block' : 'none';
  if(isEdit){
    const s = _hh_getStudents().find(x=>x.id===studentId);
    if(s){
      document.getElementById('student-name').value = s.name || '';
      document.getElementById('student-number').value = s.number || '';
      document.getElementById('student-guardian').value = s.guardian || '';
    }
  } else {
    document.getElementById('student-name').value = '';
    document.getElementById('student-number').value = '';
    document.getElementById('student-guardian').value = '';
  }
  modal.style.display = 'flex';
  setTimeout(()=>document.getElementById('student-name')?.focus(), 100);
}

function closeStudentEditor(){
  const m = document.getElementById('student-editor-modal');
  if(m) m.style.display = 'none';
}

function saveStudent(){
  if(!_hh_currentClassId){ toast('لا يوجد فصل','error'); return; }
  const id = document.getElementById('student-edit-id').value || _hh_genId('std');
  const name = (document.getElementById('student-name').value||'').trim();
  if(!name){ toast('اسم الطالب مطلوب','error'); return; }
  const number = (document.getElementById('student-number').value||'').trim();
  const guardian = (document.getElementById('student-guardian').value||'').trim();

  const all = _hh_getStudents();
  const idx = all.findIndex(s=>s.id===id);
  const obj = {id, classId: _hh_currentClassId, name, number, guardian, createdAt: idx>=0 ? all[idx].createdAt : Date.now()};
  if(idx>=0) all[idx] = obj;
  else all.push(obj);
  _hh_saveStudents(all);
  closeStudentEditor();
  toast('تم حفظ الطالب','success');
  renderStudentsList();
}

function deleteStudent(){
  const id = document.getElementById('student-edit-id').value;
  if(!id) return;
  const s = _hh_getStudents().find(x=>x.id===id);
  if(!s) return;
  if(!confirm('حذف طالب "'+(s.name||'')+'"؟')) return;
  const all = _hh_getStudents().filter(x=>x.id!==id);
  _hh_saveStudents(all);
  closeStudentEditor();
  toast('تم حذف الطالب','info');
  renderStudentsList();
}

/** فتح نافذة الاستيراد المجمع */
function openBulkImport(){
  if(!_hh_currentClassId){ toast('اختر فصلا أولا','error'); return; }
  const m = document.getElementById('bulk-import-modal');
  if(m){
    document.getElementById('bulk-students-text').value = '';
    m.style.display = 'flex';
    setTimeout(()=>document.getElementById('bulk-students-text')?.focus(), 100);
  }
}

function closeBulkImport(){
  const m = document.getElementById('bulk-import-modal');
  if(m) m.style.display = 'none';
}

function processBulkImport(){
  if(!_hh_currentClassId){ toast('لا يوجد فصل','error'); return; }
  const text = (document.getElementById('bulk-students-text').value||'').trim();
  if(!text){ toast('أدخل أسماء الطلاب','error'); return; }
  const lines = text.split('\n').map(l=>l.trim()).filter(Boolean);
  if(lines.length === 0){ toast('لا توجد أسماء صالحة','error'); return; }
  const all = _hh_getStudents();
  let added = 0;
  lines.forEach(line => {
    // تنسيق: الاسم | رقم | ولي الأمر
    const parts = line.split('|').map(p=>p.trim());
    const name = parts[0];
    if(!name) return;
    const number = parts[1] || '';
    const guardian = parts[2] || '';
    all.push({
      id: _hh_genId('std'),
      classId: _hh_currentClassId,
      name, number, guardian,
      createdAt: Date.now()+added
    });
    added++;
  });
  _hh_saveStudents(all);
  closeBulkImport();
  toast('تم استيراد '+added.toLocaleString('en-US')+' طالب','success');
  renderStudentsList();
}

// تشغيل تلقائي عند فتح شاشة الفصول
(function(){
  // مراقبة تغير الشاشات
  const observer = new MutationObserver(()=>{
    const active = document.querySelector('.screen.active');
    if(!active) return;
    if(active.id === 'screen-classes') renderClassesList();
    else if(active.id === 'screen-class-detail' && _hh_currentClassId) renderStudentsList();
  });
  if(document.body){
    observer.observe(document.body, {attributes:true, subtree:true, attributeFilter:['class']});
  }
})();
