function saveGraderToBag(){
  if(!GRADER_RESULTS){
    toast('لا توجد نتائج لحفظها', 'error');
    return;
  }
  // حفظ في حقيبة المعلم
  let bag = [];
  try{
    bag = JSON.parse(localStorage.getItem('hh_teacher_bag')||'[]');
  }catch(e){}
  
  const item = {
    id: 'grader_' + Date.now(),
    type: 'grader',
    template: 'grader',
    title: GRADER_RESULTS.testName,
    summary: `${GRADER_RESULTS.classStats.total} طالب • متوسط ${GRADER_RESULTS.classStats.avgScore.toFixed(1)}/${GRADER_RESULTS.maxScore}`,
    date: new Date().toISOString(),
    data: GRADER_RESULTS
  };
  bag.unshift(item);
  if(bag.length > 50) bag = bag.slice(0,50);
  
  try{
    localStorage.setItem('hh_teacher_bag', JSON.stringify(bag));
    toast('تم حفظ النتائج في حقيبتك ✓', 'success');
  }catch(e){
    toast('تعذر الحفظ', 'error');
  }
}

