// ═══════════════════════════════════════════════════════════════════
//  حقيبة المعلم · حفظ واسترجاع الأعمال
// ═══════════════════════════════════════════════════════════════════

let BAG_FILTER = 'all'; // all / worksheet / quiz / certificate

// حفظ عمل في الحقيبة (عند تحميل PDF)
function saveToTeacherBag(data){
  try{
    const bag = getTeacherBag();
    const item = {
      id: 'bag_' + Date.now() + '_' + Math.random().toString(36).slice(2,6),
      template: data.template,
      title: data.title || data.certTitle || 'عمل بدون عنوان',
      data: data,
      createdAt: new Date().toISOString(),
      timeSpent: 47 // وقت تقديري بالدقائق وفره العمل (لإحصائية)
    };
    // لا نحفظ الشعار في كل عمل (يستهلك مساحة) · نعتمد على المحفوظ في hh_activity_logo
    if(item.data.logo) item.data.logo = '__use_saved__';
    bag.unshift(item); // أحدث في الأعلى
    // حد أقصى 50 عمل (لتجنب تخمة الذاكرة)
    if(bag.length > 50) bag.splice(50);
    localStorage.setItem('hh_teacher_bag', JSON.stringify(bag));
  }catch(e){
    // إذا امتلأت الذاكرة، نحاول حذف الأقدم
    try{
      const bag = getTeacherBag();
      if(bag.length > 0){
        bag.splice(Math.floor(bag.length / 2));
        localStorage.setItem('hh_teacher_bag', JSON.stringify(bag));
      }
    }catch(e2){ console.warn('Bag save failed', e2); }
  }
}

function getTeacherBag(){
  try{
    const saved = localStorage.getItem('hh_teacher_bag');
    return saved ? JSON.parse(saved) : [];
  }catch(e){ return []; }
}

function saveTeacherBag(bag){
  try{
    localStorage.setItem('hh_teacher_bag', JSON.stringify(bag));
  }catch(e){ toast('الذاكرة ممتلئة', 'error'); }
}

// تحميل وعرض الحقيبة
function loadTeacherBag(){
  renderBagStats();
  renderBagItems();
}

// رسم الإحصائيات (اللحظة الذهبية)
function renderBagStats(){
  const bag = getTeacherBag();
  const total = bag.length;
  // كل عمل يوفر وقتا مختلفا: التصحيح ~60 د، الأنشطة ~47 د
  let totalMinutes = 0;
  bag.forEach(item => {
    if(item.template === 'grader'){
      // التصحيح يوفر دقيقة لكل طالب + 30 د إعداد التقرير
      const studentsCount = ((item.data||{}).classStats||{}).total || 0;
      totalMinutes += (studentsCount * 2) + 30;
    } else {
      totalMinutes += 47;
    }
  });
  const hours = Math.floor(totalMinutes / 60);
  const days = (totalMinutes / 60 / 8).toFixed(1); // يوم عمل = 8 ساعات
  const el = document.getElementById('bag-stats-content');
  if(!el) return;

  if(total === 0){
    el.innerHTML = `
      <div style="font-size:1rem;line-height:1.7;"> حقيبتك فارغة الآن<br>
        <span style="font-size:.85rem;color:#d4cdb0;font-weight:600;">أنشئ أول عمل وستملأ هنا تلقائيا</span>
      </div> `;
    return;
  }

  // رسائل ديناميكية حسب عدد الأعمال
  let message;
  if(total < 5){
    message = `لديك <span style="color:#D4BC85;font-size:1.3rem;">${total}</span> ${total===1?'عمل':total===2?'عملان':'أعمال'} في حقيبتك`;
  } else if(total < 20){
    message = `وفرت <span style="color:#D4BC85;font-size:1.3rem;">${hours}</span> ساعة من وقتك<br><span style="font-size:.82rem;color:#d4cdb0;font-weight:600;">= ${total} عمل احترافي</span>`;
  } else {
    message = `أنت ملهم! <span style="color:#D4BC85;font-size:1.3rem;">${total}</span> عمل<br><span style="font-size:.82rem;color:#d4cdb0;font-weight:600;">وفرت ${days} يوم عمل كامل</span>`;
  }
  el.innerHTML = message;
}

// رسم قائمة الأعمال
function renderBagItems(){
  const list = document.getElementById('bag-items-list');
  if(!list) return;
  let bag = getTeacherBag();

  // تطبيق الفلترة
  if(BAG_FILTER !== 'all'){
    bag = bag.filter(item => item.template === BAG_FILTER);
  }

  // تطبيق البحث
  const searchTerm = (document.getElementById('bag-search')||{}).value || '';
  if(searchTerm.trim()){
    const term = searchTerm.toLowerCase();
    bag = bag.filter(item => (item.title||'').toLowerCase().includes(term) ||
      (item.data.subject||'').toLowerCase().includes(term) ||
      (item.data.studentName||'').toLowerCase().includes(term)
    );
  }

  if(bag.length === 0){
    list.innerHTML = `
      <div style="text-align:center;padding:40px 20px;background:#fafafa;border-radius:12px;border:2px dashed #ccc;">
        <div style="font-size:3rem;margin-bottom:10px;"></div>
        <div style="font-family:Cairo;font-weight:900;color:#666;font-size:.95rem;margin-bottom:6px;">${searchTerm ? 'لا توجد نتائج' : 'لا توجد أعمال'}</div>
        <div style="font-size:.78rem;color:#999;line-height:1.6;">${searchTerm ? 'جرب كلمة أخرى' : 'كل عمل تنتجه سيحفظ هنا تلقائيا'}</div>
      </div> `;
    return;
  }

  list.innerHTML = bag.map(item => {
    const date = new Date(item.createdAt);
    const dateStr = date.toLocaleDateString('ar-EG', { year:'numeric', month:'short', day:'numeric' });
    const timeStr = date.toLocaleTimeString('ar-EG', { hour:'2-digit', minute:'2-digit' });
    const tplInfo = {
      worksheet: { icon:'', label:'ورقة عمل', color:'#3D6B53', bg:'#e8f2ec' },
      quiz: { icon:'<svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M5 9.2h3v9H5zM10.6 5h2.8v13h-2.8zM16.2 13h2.8v5h-2.8z"/></svg>', label:'اختبار', color:'#8A1538', bg:'#f5e1e7' },
      certificate: { icon:'<svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M19 5h-2V3H7v2H5c-1.1 0-2 .9-2 2v1c0 2.55 1.92 4.63 4.39 4.94A5.01 5.01 0 0011 15.9V19H7v2h10v-2h-4v-3.1A5.01 5.01 0 0016.61 12.94C19.08 12.63 21 10.55 21 8V7c0-1.1-.9-2-2-2zM5 8V7h2v3.82C5.84 10.4 5 9.3 5 8zm14 0c0 1.3-.84 2.4-2 2.82V7h2v1z"/></svg>', label:'شهادة', color:'#B8924A', bg:'#fff8e8' },
      grader: { icon:'', label:'تصحيح', color:'#8A1538', bg:'#f5ede4' }
    }[item.template] || { icon:'', label:'عمل', color:'#666', bg:'#f5f5f5' };

    // معاينة محتوى مختصرة
    let preview = '';
    if(item.template === 'worksheet'){
      const qs = (item.data.questions||[]).length;
      preview = `${qs} ${qs===1?'سؤال':'أسئلة'}`;
    } else if(item.template === 'quiz'){
      const qs = (item.data.items||[]).length;
      preview = `${qs} ${qs===1?'سؤال':'أسئلة'} • ${item.data.duration||'20'} د`;
    } else if(item.template === 'certificate'){
      preview = `للطالب: ${item.data.studentName||'·'}`;
    } else if(item.template === 'grader'){
      const total = (item.data.classStats||{}).total || 0;
      const avg = ((item.data.classStats||{}).avgScore || 0).toFixed(1);
      const max = item.data.maxScore || 100;
      preview = `${total} طالب • متوسط ${avg}/${max}`;
    }

    return `
      <div style="background:#fff;border:1.5px solid #e0e8f0;border-right:4px solid ${tplInfo.color};border-radius:12px;padding:14px;margin-bottom:10px;display:flex;align-items:center;gap:12px;transition:all .2s;box-shadow:0 2px 6px rgba(0,0,0,.04);">
        <div style="width:48px;height:48px;border-radius:10px;background:${tplInfo.bg};display:flex;align-items:center;justify-content:center;font-size:1.5rem;flex-shrink:0;">${tplInfo.icon}</div>
        <div style="flex:1;min-width:0;">
          <div style="display:flex;align-items:center;gap:6px;margin-bottom:4px;">
            <span style="font-family:Cairo;font-weight:900;font-size:.6rem;padding:2px 8px;background:${tplInfo.color};color:#fff;border-radius:10px;">${tplInfo.label}</span>
            <span style="font-size:.7rem;color:#999;">${dateStr} • ${timeStr}</span>
          </div>
          <div style="font-family:Cairo;font-weight:900;color:#8A1538;font-size:.92rem;margin-bottom:3px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${escAG(item.title)}</div>
          <div style="font-size:.74rem;color:#777;font-weight:500;">${preview}${item.data.subject?' • '+escAG(item.data.subject):''}</div>
        </div>
        <div style="display:flex;flex-direction:column;gap:5px;flex-shrink:0;">
          <button onclick="reuseBagItem('${escAttr(item.id)}')" title="إعادة استخدام" style="padding:6px 10px;background:linear-gradient(135deg,#3D6B53,#2C5340);color:#fff;border:none;border-radius:7px;font-family:Cairo;font-weight:800;font-size:.7rem;cursor:pointer;display:flex;align-items:center;gap:4px;">
            <svg width="11" height="11" viewBox="0 0 24 24" fill="currentColor"><path d="M19 9h-4V3H9v6H5l7 7 7-7zM5 18v2h14v-2H5z"/></svg> استخدم
          </button>
          <button onclick="deleteBagItem('${escAttr(item.id)}')" title="حذف" style="padding:6px 10px;background:#fff;border:1.5px solid #c0392b;color:#c0392b;border-radius:7px;font-family:Cairo;font-weight:800;font-size:.7rem;cursor:pointer;"> حذف
          </button>
        </div>
      </div> `;
  }).join('');
}

// تطبيق الفلتر
function setBagFilter(filter){
  BAG_FILTER = filter;
  document.querySelectorAll('.bag-filter-btn').forEach(btn => {
    if(btn.dataset.filter === filter){
      btn.style.background = '#8A1538';
      btn.style.color = '#fff';
      btn.style.border = 'none';
      btn.classList.add('bag-filter-active');
    } else {
      btn.style.background = '#fff';
      btn.style.color = '#8A1538';
      btn.style.border = '1.5px solid #dce5ea';
      btn.classList.remove('bag-filter-active');
    }
  });
  renderBagItems();
}

// البحث
function filterBagItems(){
  renderBagItems();
}

// إعادة استخدام عمل (يفتح المولد ويعبئه بالبيانات)
function reuseBagItem(id){
  const bag = getTeacherBag();
  const item = bag.find(x => x.id === id);
  if(!item){ toast('العمل غير موجود', 'error'); return; }

  //  المصحح له شاشة خاصة · فتحها وعرض النتائج
  if(item.template === 'grader'){
    showScreen('screen-grader');
    setTimeout(()=>{
      initGrader();
      // استرجاع النتائج المحفوظة
      GRADER_RESULTS = item.data;
      // عرض النتائج فورا
      setTimeout(()=>{
        renderGraderResults();
        toast('✓ تم استرجاع نتائج التصحيح', 'success');
      }, 200);
    }, 100);
    return;
  }

  // الانتقال لشاشة المولد
  showScreen('screen-activity-gen');
  
  // بعد الانتقال، نعبئ البيانات
  setTimeout(()=>{
    initActivityGen();
    setTimeout(()=>{
      const d = item.data;
      // اختر القالب المناسب
      selectActivityTemplate(item.template);
      
      // عبئ التفاصيل بعد رسم الفورم
      setTimeout(()=>{
        if(item.template === 'worksheet'){
          const titleEl = document.getElementById('ag-ws-title');
          const introEl = document.getElementById('ag-ws-intro');
          const qsEl = document.getElementById('ag-ws-questions');
          if(titleEl) titleEl.value = d.title || '';
          if(introEl) introEl.value = d.intro || '';
          if(qsEl) qsEl.value = (d.questions || []).join('\n');
        } else if(item.template === 'quiz'){
          const titleEl = document.getElementById('ag-qz-title');
          const durEl = document.getElementById('ag-qz-duration');
          const totEl = document.getElementById('ag-qz-total');
          const itemsEl = document.getElementById('ag-qz-items');
          if(titleEl) titleEl.value = d.title || '';
          if(durEl) durEl.value = d.duration || '20';
          if(totEl) totEl.value = d.total || '20';
          if(itemsEl) itemsEl.value = (d.items || []).map(x => `${x.q} | ${x.a}`).join('\n');
        } else if(item.template === 'certificate'){
          const stuEl = document.getElementById('ag-cert-student');
          const clsEl = document.getElementById('ag-cert-class');
          const reaEl = document.getElementById('ag-cert-reason');
          const titEl = document.getElementById('ag-cert-title');
          const grdEl = document.getElementById('ag-cert-grade');
          const yrEl = document.getElementById('ag-cert-year');
          const trmEl = document.getElementById('ag-cert-term');
          if(stuEl) stuEl.value = d.studentName || '';
          if(clsEl) clsEl.value = d.studentClass || '';
          if(reaEl) reaEl.value = d.reason || '';
          if(titEl) titEl.value = d.certTitle || 'شهادة تفوق';
          if(grdEl) grdEl.value = d.certGrade || 'ممتاز';
          if(yrEl) yrEl.value = d.academicYear || '';
          if(trmEl) trmEl.value = d.term || '';
          // استرجاع خيار إظهار المنصة
          const platEl = document.getElementById('ag-cert-show-platform');
          if(platEl) platEl.checked = (d.showPlatform !== false); // افتراضيا مفعل
          // استرجاع التوقيعات
          if(d.signatures && d.signatures.length > 0){
            const list = document.getElementById('ag-cert-signatures-list');
            if(list){
              list.innerHTML = '';
              d.signatures.forEach(sig => {
                addCertSignatureRow(sig.position || '', sig.name || '');
              });
            }
          }
        }
        toast('✓ تم تحميل العمل · عدل ما تشاء', 'success');
      }, 100);
    }, 50);
  }, 50);
}

// حذف عمل
function deleteBagItem(id){
  if(!confirm('هل أنت متأكد من حذف هذا العمل؟ لا يمكن التراجع.')) return;
  const bag = getTeacherBag();
  const idx = bag.findIndex(x => x.id === id);
  if(idx === -1) return;
  bag.splice(idx, 1);
  saveTeacherBag(bag);
  loadTeacherBag();
  toast('✓ تم الحذف', 'info');
}

