/**
 * استخراج بيانات المستخدم من المصادر المتاحة (Firestore أو localStorage).
 * تعيد بنية موحدة:
 *   { role, points, gamesPlayed, hasReviewed, daysSinceJoined, totalMinutes }
 */
function _hh_extractUserData(user){
  if(!user) return { role:'guest', points:0, gamesPlayed:0, hasReviewed:false, daysSinceJoined:0, totalMinutes:0 };
  const data = {
    role: user.role || user._role || (user.userType==='teacher'?'teacher':user.userType==='student'?'student':null),
    points: user.points || user.pts || 0,
    gamesPlayed: user.gamesPlayed || 0,
    hasReviewed: user.hasReviewed === true,
    daysSinceJoined: 0,
    totalMinutes: user.totalMinutes || 0
  };
  // حساب عدد الأيام منذ التسجيل
  const created = user.createdAt;
  if(created){
    let createdMs = null;
    if(created.toMillis) createdMs = created.toMillis();
    else if(typeof created === 'number') createdMs = created;
    else if(typeof created === 'string'){ const t = new Date(created).getTime(); if(!isNaN(t)) createdMs = t; }
    if(createdMs){
      data.daysSinceJoined = Math.floor((Date.now() - createdMs) / (1000*60*60*24));
    }
  }
  return data;
}

/**
 * احتساب لقب المستخدم · الدالة المركزية للنظام.
 * @param {Object} user كائن مستخدم من Firestore أو currentUser.
 * @returns {Object} كائن اللقب من HH_BADGES.
 */
function getUserBadge(user){
  const d = _hh_extractUserData(user);
  // إن لم يكن للمستخدم دور (زائر) → زائر كريم
  if(!d.role || d.role === 'other' || d.role === 'guest'){
    return HH_BADGES.find(b => b.id === 'guest_curious');
  }
  const role = (d.role === 'teacher') ? 'teacher' : 'student';
  // المرور على ألقاب الدور بالترتيب (الأعلى أولا) ↦ أول شرط ينطبق يفوز
  for(const badge of HH_BADGES){
    if(badge.role !== role) continue;
    try{
      if(badge.condition(d)) return badge;
    }catch(e){}
  }
  // احتياط
  return HH_BADGES.find(b => b.role === role && b.tier === 1) ||
         HH_BADGES.find(b => b.id === 'guest_curious');
}

/**
 * احتساب اللقب للمستخدم الحالي (currentUser) · يجلب بيانات إضافية
 * من localStorage (مثل gamesPlayed و hasReviewed إن لم تكن في Firestore).
 */
async function getCurrentUserBadge(){
  if(!currentUser) return HH_BADGES.find(b => b.id === 'guest_curious');
  const merged = {
    role: _currentUserRole || null,
    points: 0,
    gamesPlayed: 0,
    hasReviewed: false,
    createdAt: null,
    totalMinutes: 0
  };
  // 1) من Firestore إن أمكن · هنا نأخذ الدور من Firestore دائما (لا من _currentUserRole فقط)
  try{
    if(db && !OFFLINE_MODE){
      const doc = await db.collection('users').doc(currentUser.uid).get();
      if(doc.exists){
        const dd = doc.data();
        //  الدور من Firestore يتقدم على _currentUserRole إن وجد
        if(dd.role) merged.role = dd.role;
        merged.points = dd.points || 0;
        merged.gamesPlayed = Math.max(merged.gamesPlayed, dd.gamesPlayed || 0);
        merged.createdAt = dd.createdAt;
        merged.totalMinutes = dd.totalMinutes || 0;
      }
    }
  }catch(e){}
  // 2) Fallback من localStorage إن لم يحدد دور (قد يكون مخزنا محليا)
  if(!merged.role){
    try{
      const localRole = localStorage.getItem('hh_user_role');
      if(localRole === 'teacher' || localRole === 'student' || localRole === 'other'){
        merged.role = localRole;
      }
    }catch(e){}
  }
  // 3) Fallback أخير: المدير يعتبر معلما افتراضا
  if(!merged.role && isAdminUser(currentUser)){
    merged.role = 'teacher';
  }
  // 4) دعم gamesPlayed من localStorage
  try{
    const ach = _loadAchievements();
    if(ach && (ach.gamesPlayed||0) > merged.gamesPlayed){
      merged.gamesPlayed = ach.gamesPlayed;
    }
  }catch(e){}
  // 5) فحص التقييم من localStorage إن وجد
  try{
    if(localStorage.getItem('hh_has_reviewed') === '1') merged.hasReviewed = true;
  }catch(e){}
  return getUserBadge(merged);
}

/**
 * بناء HTML لشارة اللقب · قابلة للاستخدام في أي مكان.
 * @param {Object} badge كائن اللقب
 * @param {Object} opts {size:'sm'|'md'|'lg', withIcon:bool}
 */
function renderBadgeHTML(badge, opts={}){
  if(!badge) return '';
  const size = opts.size || 'sm';
  const withIcon = opts.withIcon !== false;
  const fontSize = size==='lg' ? '.82rem' : size==='md' ? '.72rem' : '.65rem';
  const padY = size==='lg' ? '4px' : size==='md' ? '3px' : '2px';
  const padX = size==='lg' ? '12px' : size==='md' ? '10px' : '8px';
  const iconSz = size==='lg' ? 16 : size==='md' ? 14 : 12;
  const glow = badge.glow && badge.glow!=='none' ? `box-shadow:${badge.glow};` : '';
  const iconHtml = withIcon ? `<span style="display:inline-flex;width:${iconSz}px;height:${iconSz}px;color:${badge.color};">${badge.icon.replace(/width="\d+"/,'width="'+iconSz+'"').replace(/height="\d+"/,'height="'+iconSz+'"')}</span>` : '';
  return `<span class="hh-badge hh-badge-${badge.id}" style="display:inline-flex;align-items:center;gap:5px;background:${badge.bg};color:${badge.color};border:1px solid ${badge.border};padding:${padY} ${padX};border-radius:12px;font-family:Cairo,sans-serif;font-weight:900;font-size:${fontSize};line-height:1.2;white-space:nowrap;${glow}">${iconHtml}<span>${badge.label}</span></span>`;
}

/**
 * عرض لقب المستخدم الحالي في بطاقة الترحيب الرئيسية.
 * يستدعى بعد updateRoyalGreeting().
 */
async function refreshHomeUserBadge(){
  try{
    const wrap = document.getElementById('royal-user-badge');
    if(!wrap) return;
    if(!currentUser){
      wrap.innerHTML = '';
      wrap.style.display = 'none';
      return;
    }
    const badge = await getCurrentUserBadge();
    if(badge){
      wrap.innerHTML = renderBadgeHTML(badge, { size:'md' });
      wrap.style.display = 'block';
    }
  }catch(e){ console.warn('badge refresh failed', e); }
}
window.refreshHomeUserBadge = refreshHomeUserBadge;
window.getUserBadge = getUserBadge;
window.renderBadgeHTML = renderBadgeHTML;
