// القيم الافتراضية (Fallback إذا لم تحمل من Firestore)
const HH_CONTACT_DEFAULTS = {
  email: '20ahmedali25@gmail.com',
  instagram: 'almulhim_edu',
  website: 'alhalhali.com',
  whatsapp: '' // فارغ · لا تظهر البطاقة
};

// المخزن محليا لتجنب الجلب المتكرر
let _contactInfoCache = null;

/**
 * جلب بيانات التواصل من Firestore أو الـ defaults
 */
async function loadContactInfo(){
  // ابدأ بالافتراضيات
  let info = Object.assign({}, HH_CONTACT_DEFAULTS);

  // حاول جلبها من Firestore
  try{
    if(typeof db !== 'undefined' && db && !OFFLINE_MODE){
      const doc = await db.collection('platform_settings').doc('contact').get();
      if(doc.exists){
        const data = doc.data();
        if(data.email !== undefined) info.email = data.email;
        if(data.instagram !== undefined) info.instagram = data.instagram;
        if(data.website !== undefined) info.website = data.website;
        if(data.whatsapp !== undefined) info.whatsapp = data.whatsapp;
      }
    } else {
      // وضع offline → استخدم localStorage
      const cached = localStorage.getItem('hh_contact_info');
      if(cached){
        try{ info = Object.assign(info, JSON.parse(cached)); }catch(e){}
      }
    }
  }catch(e){
    console.warn('Failed to load contact info, using defaults', e);
  }

  _contactInfoCache = info;
  // اعرض البطاقات
  renderContactChannels(info);
  // أظهر زر التعديل إذا الأدمن
  const editBtn = document.getElementById('contact-edit-admin-btn');
  if(editBtn) editBtn.style.display = (typeof isAdminUser === 'function' && isAdminUser(currentUser)) ? 'flex' : 'none';
  return info;
}

