/**
 * فتح مودال التعديل (للأدمن فقط)
 */
function openContactEditModal(){
  if(typeof isAdminUser === 'function' && !isAdminUser(currentUser)){
    if(typeof toast === 'function') toast('هذه الميزة للأدمن فقط', 'error');
    return;
  }
  const info = _contactInfoCache || HH_CONTACT_DEFAULTS;
  const m = document.getElementById('contact-edit-modal');
  if(!m) return;
  // املأ القيم الحالية
  document.getElementById('ce-email').value = info.email || '';
  document.getElementById('ce-instagram').value = (info.instagram || '').replace(/^@/, '');
  document.getElementById('ce-website').value = info.website || '';
  document.getElementById('ce-whatsapp').value = info.whatsapp || '';
  document.getElementById('ce-status').textContent = '';
  m.style.display = 'flex';
}

function closeContactEditModal(){
  const m = document.getElementById('contact-edit-modal');
  if(m) m.style.display = 'none';
}

/**
 * حفظ التعديلات في Firestore
 */
async function saveContactEdits(){
  if(typeof isAdminUser === 'function' && !isAdminUser(currentUser)){
    if(typeof toast === 'function') toast('هذه الميزة للأدمن فقط', 'error');
    return;
  }

  const newInfo = {
    email: document.getElementById('ce-email').value.trim(),
    instagram: document.getElementById('ce-instagram').value.trim().replace(/^@/, ''),
    website: document.getElementById('ce-website').value.trim().replace(/^https?:\/\//, ''),
    whatsapp: document.getElementById('ce-whatsapp').value.trim()
  };

  const statusEl = document.getElementById('ce-status');
  const saveBtn = document.getElementById('ce-save-btn');
  if(statusEl) statusEl.textContent = 'جار الحفظ...';
  if(statusEl) statusEl.style.color = '#888';
  if(saveBtn) saveBtn.disabled = true;

  try{
    if(typeof db !== 'undefined' && db && !OFFLINE_MODE){
      await db.collection('platform_settings').doc('contact').set(newInfo, { merge: true });
    } else {
      // وضع offline → احفظ في localStorage
      localStorage.setItem('hh_contact_info', JSON.stringify(newInfo));
    }

    // حدث الكاش وأعد رسم البطاقات
    _contactInfoCache = newInfo;
    renderContactChannels(newInfo);

    if(statusEl){
      statusEl.textContent = '✓ تم الحفظ · التغييرات الآن لجميع المستخدمين';
      statusEl.style.color = '#3D6B53';
    }
    if(typeof toast === 'function') toast('تم تحديث بيانات التواصل بنجاح', 'success');

    // أغلق المودال بعد ثانية
    setTimeout(() => {
      closeContactEditModal();
    }, 1200);

  }catch(e){
    console.error('Failed to save contact info', e);
    if(statusEl){
      statusEl.innerHTML = '<svg viewBox="0 0 24 24" fill="currentColor" style="width:1em;height:1em;vertical-align:middle;"><path d="M19 6.41L17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12z"/></svg> فشل الحفظ · حاول مجددا';
      statusEl.style.color = '#c0392b';
    }
    if(typeof toast === 'function') toast('فشل الحفظ', 'error');
  }finally{
    if(saveBtn) saveBtn.disabled = false;
  }
}

// دالة مساعدة للأمان
function escapeHtml(str){
  if(typeof str !== 'string') return '';
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// تشغيل تلقائي عند فتح الشاشة
(function watchContactScreen(){
  const orig = window.showScreen;
  if(typeof orig !== 'function') return;
  window.showScreen = function(id){
    const result = orig.apply(this, arguments);
    if(id === 'screen-contact'){
      setTimeout(() => { try{ loadContactInfo(); }catch(e){} }, 100);
    }
    return result;
  };
})();

window.loadContactInfo = loadContactInfo;
window.openContactEditModal = openContactEditModal;
window.closeContactEditModal = closeContactEditModal;
window.saveContactEdits = saveContactEdits;
